--[[
    Speex Hub — зимний ледяной стиль, компактный размер
    Название SPEEX в синей шапке (видно и в свёрнутом виде).
    Игровая логика не подключена — всё меняет только визуальный стейт.
--]]

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local player = Players.LocalPlayer

-- ================= ЦВЕТА =================
local COLOR_BG       = Color3.fromRGB(238, 245, 252)   -- холодный молочно-белый
local COLOR_PANEL    = Color3.fromRGB(224, 236, 250)   -- молочно-голубой
local COLOR_LINE     = Color3.fromRGB(196, 216, 238)
local COLOR_ACCENT   = Color3.fromRGB(120, 170, 225)
local COLOR_ACCENT_D = Color3.fromRGB(190, 214, 242)
local COLOR_TEXT     = Color3.fromRGB(28, 48, 82)
local COLOR_TEXT_D   = Color3.fromRGB(95, 125, 160)
local COLOR_BLUE     = Color3.fromRGB(48, 104, 188)   -- winter ice blue (шапка)
local COLOR_BLUE_D   = Color3.fromRGB(30, 72, 148)

-- ================= РАЗМЕРЫ =================
local WIDTH, HEIGHT = 250, 350
local BOTTOM_H = 60
local RIGHT_W = 48
local MINI_W = 140   -- ширина свёрнутой плашки
local HEADER_H = 36
local PAD = 6

-- ================= ПОВТОРНЫЙ ЗАПУСК: убираем старую копию меню с экрана =================
do
    if getgenv then getgenv().__SpeexHubRun = (getgenv().__SpeexHubRun or 0) + 1 end
    local pg0 = player:WaitForChild("PlayerGui")
    for _, n in ipairs({"SpeexHub", "SpeexMobilePanel", "SpeexIntro", "SpeexStealBar", "SpeexESPLine"}) do
        local old = pg0:FindFirstChild(n)
        if old then pcall(function() old:Destroy() end) end
    end
end

-- ================= БАЗА =================
local ScreenGui = Instance.new("ScreenGui")
ScreenGui.Name = "SpeexHub"
ScreenGui.ResetOnSpawn = false
ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
ScreenGui.Parent = player:WaitForChild("PlayerGui")

local Main = Instance.new("Frame")
Main.Name = "Main"
Main.Size = UDim2.new(0, WIDTH, 0, HEIGHT)
Main.Position = UDim2.new(0, 20, 0.5, -HEIGHT / 2)
Main.BackgroundColor3 = COLOR_BG
Main.BorderSizePixel = 0
Main.ClipsDescendants = true
Main.Parent = ScreenGui

local MainCorner = Instance.new("UICorner", Main)
MainCorner.CornerRadius = UDim.new(0, 12)

local MainStroke = Instance.new("UIStroke", Main)
MainStroke.Color = Color3.fromRGB(176, 206, 238)
MainStroke.Thickness = 3
MainStroke.Transparency = 0.05

-- ================= ФОН: картинка ~9.5 КБ, вшита прямо в скрипт =================
