local B64CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function b64decode(data)
    local lookup = {}
    for i = 1, #B64CHARS do
        lookup[string.byte(B64CHARS, i)] = i - 1
    end
    local out, n = {}, 0
    local buf, bits = 0, 0
    for i = 1, #data do
        local v = lookup[string.byte(data, i)]
        if v then
            buf = buf * 64 + v
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                local byte = math.floor(buf / 2 ^ bits)
                buf = buf % 2 ^ bits
                n = n + 1
                out[n] = string.char(byte)
            end
        end
    end
    return table.concat(out)
end

