    local okIntro = pcall(function()
        local RunService = game:GetService("RunService")
        local pgui = player:WaitForChild("PlayerGui")
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(800, 600)

        ScreenGui.Enabled = false   -- меню покажется после интро

        local intro = Instance.new("ScreenGui")
        intro.Name = "SpeexIntro"
        intro.ResetOnSpawn = false
        intro.IgnoreGuiInset = true
        intro.DisplayOrder = 1000
        intro.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        intro.Parent = pgui

        local stage = Instance.new("CanvasGroup")
        stage.Name = "Stage"
        stage.Size = UDim2.fromScale(1, 1)
        stage.BackgroundColor3 = Color3.fromRGB(6, 10, 20)
        stage.BackgroundTransparency = 1
        stage.BorderSizePixel = 0
        stage.Active = true
        stage.Parent = intro

        local skipped = false
        stage.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                skipped = true
            end
        end)

        -- ---------- музыка (из записи, вшита в скрипт) ----------
        local snd
        pcall(function()
            local gca = getcustomasset or getsynasset
            if writefile and gca then
                writefile("speex_intro.mp3", b64decode(SND_B64))
                snd = Instance.new("Sound")
                snd.Name = "SpeexIntroSound"
                snd.SoundId = gca("speex_intro.mp3")
                snd.Volume = 0.8
                snd.Parent = intro
                snd:Play()
            end
        end)

        -- ---------- дождь со снегом ----------
        local drops, flakes = {}, {}
        for i = 1, 70 do
            local d = Instance.new("Frame")
            d.BorderSizePixel = 0
            d.AnchorPoint = Vector2.new(0.5, 0.5)
            d.BackgroundColor3 = Color3.fromRGB(190, 215, 255)
            d.BackgroundTransparency = 0.35 + math.random() * 0.35
            d.Size = UDim2.fromOffset(2, math.random(14, 30))
            d.Rotation = 10
            d.ZIndex = 5
            d.Parent = stage
            drops[i] = {f = d, x = math.random() * (vp.X + 200), y0 = math.random() * vp.Y, sp = math.random(500, 900)}
        end
        for i = 1, 55 do
            local s = math.random(3, 6)
            local f = Instance.new("Frame")
            f.BorderSizePixel = 0
            f.AnchorPoint = Vector2.new(0.5, 0.5)
            f.BackgroundColor3 = Color3.fromRGB(245, 250, 255)
            f.BackgroundTransparency = 0.1 + math.random() * 0.25
            f.Size = UDim2.fromOffset(s, s)
            f.ZIndex = 6
            f.Parent = stage
            local c = Instance.new("UICorner", f)
            c.CornerRadius = UDim.new(1, 0)
            flakes[i] = {f = f, x = math.random() * vp.X, y0 = math.random() * vp.Y, sp = math.random(50, 130),
                         amp = math.random(10, 30), w = 0.8 + math.random() * 1.4, ph = math.random() * 6.28}
        end

        -- ---------- буквы из осколков ----------
        local CW, CH, GAP, TS = 72, 90, 10, 12     -- ячейка буквы, промежуток, размер осколка
        local FLY = 0.55                           -- время полёта одного осколка
        local STEP = 0.18                          -- пауза между буквами
        local sc = math.clamp(math.min(vp.X / 444, vp.Y / 285), 0.4, 1.3)

        local world = Instance.new("Frame")
        world.Name = "World"
        world.BackgroundTransparency = 1
        world.AnchorPoint = Vector2.new(0.5, 0.5)
        world.Position = UDim2.fromScale(0.5, 0.5)
        world.Size = UDim2.fromOffset(0, 0)
        world.ZIndex = 2
        world.Parent = stage
        local ws = Instance.new("UIScale", world)
        ws.Scale = sc

        local frost = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(250, 253, 255)),
            ColorSequenceKeypoint.new(0.30, Color3.fromRGB(250, 253, 255)),
            ColorSequenceKeypoint.new(0.40, Color3.fromRGB(150, 195, 245)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(100, 150, 215)),
        })

        local shards = {}
        local rows = {
            {text = "SPEEX", top = -CH - 8, start = 0.15},
            {text = "HUB",   top = 8,       start = 0.90},
        }
        for _, row in ipairs(rows) do
            local n = #row.text
            local rowW = n * CW + (n - 1) * GAP
            for i = 1, n do
                local ch = row.text:sub(i, i)
                local lx = -rowW / 2 + (i - 1) * (CW + GAP)
                local ls = row.start + (i - 1) * STEP
                for gy = 0, math.ceil(CH / TS) - 1 do
                    for gx = 0, math.ceil(CW / TS) - 1 do
                        local f = Instance.new("Frame")
                        f.BackgroundTransparency = 1
                        f.BorderSizePixel = 0
                        f.ClipsDescendants = true
                        f.Size = UDim2.fromOffset(TS + 1, TS + 1)   -- +1px нахлёст, чтобы между осколками не было полосок
                        f.Parent = world

                        local l = Instance.new("TextLabel")
                        l.BackgroundTransparency = 1
                        l.Size = UDim2.fromOffset(CW, CH)
                        l.Position = UDim2.fromOffset(-gx * TS, -gy * TS)
                        l.Font = Enum.Font.GothamBlack
                        l.TextSize = 76
                        l.Text = ch
                        l.TextColor3 = Color3.new(1, 1, 1)
                        l.TextTransparency = 1
                        l.Parent = f
                        local g = Instance.new("UIGradient", l)
                        g.Color = frost
                        g.Rotation = 90

                        local ang = math.random() * math.pi * 2
                        local dist = 220 + math.random() * 420
                        shards[#shards + 1] = {
                            f = f, lbl = l,
                            fx = lx + gx * TS, fy = row.top + gy * TS,
                            vx = math.cos(ang) * dist, vy = math.sin(ang) * dist,
                            t0 = ls + math.random() * 0.35,
                            done = false,
                        }
                        f.Position = UDim2.fromOffset(lx + gx * TS + math.cos(ang) * dist, row.top + gy * TS + math.sin(ang) * dist)
                    end
                end
            end
        end

        -- ---------- цикл анимации ----------
        local FADE_LEN, endT = 0.45, 4.0
        local fadeStart = endT - FADE_LEN
        local began = os.clock()
        while true do
            local t = os.clock() - began
            if skipped and fadeStart > t then
                fadeStart, FADE_LEN, endT = t, 0.25, t + 0.25
            end
            if t >= endT then break end

            stage.GroupTransparency = t > fadeStart and math.clamp((t - fadeStart) / FADE_LEN, 0, 1) or 0

            for _, s in ipairs(shards) do
                if not s.done then
                    local u = (t - s.t0) / FLY
                    if u > 0 then
                        if u >= 1 then
                            u = 1
                            s.done = true
                        end
                        local r = (1 - u) ^ 3
                        s.f.Position = UDim2.fromOffset(s.fx + s.vx * r, s.fy + s.vy * r)
                        s.lbl.TextTransparency = math.min(1, r * 1.4)
                    end
                end
            end

            if t > 2.2 then
                world.Position = UDim2.new(0.5, 0, 0.5, math.floor(3 * math.sin((t - 2.2) * 3)))
            end

            for _, d in ipairs(drops) do
                local y = (d.y0 + t * d.sp) % (vp.Y + 60) - 30
                d.f.Position = UDim2.fromOffset(d.x - 0.18 * y, y)
            end
            for _, fl in ipairs(flakes) do
                local y = (fl.y0 + t * fl.sp) % (vp.Y + 30) - 15
                local x = (fl.x + fl.amp * math.sin(t * fl.w + fl.ph) + t * 12) % vp.X
                fl.f.Position = UDim2.fromOffset(x, y)
            end

            RunService.RenderStepped:Wait()
        end

        if snd then pcall(function() snd:Stop() end) end
        intro:Destroy()
    end)

    -- при любой ошибке/пропуске интро убираем остатки и обязательно показываем меню
    pcall(function()
        local o = player.PlayerGui:FindFirstChild("SpeexIntro")
        if o then o:Destroy() end
    end)
    ScreenGui.Enabled = true
end

