-- тумблер
local function makeToggle(parent, pos, state, onChange)
    local holder = Instance.new("Frame")
    holder.Size = UDim2.new(0, 32, 0, 18)
    holder.Position = pos
    holder.BackgroundColor3 = state and COLOR_ACCENT_D or COLOR_BG
    holder.Parent = parent
    local hc = Instance.new("UICorner", holder)
    hc.CornerRadius = UDim.new(1, 0)
    local hs = Instance.new("UIStroke", holder)
    hs.Color = COLOR_LINE
    hs.Thickness = 1

    local knob = Instance.new("TextButton")
    knob.Size = UDim2.new(0, 14, 0, 14)
    knob.Position = state and UDim2.new(1, -16, 0.5, -7) or UDim2.new(0, 2, 0.5, -7)
    knob.BackgroundColor3 = Color3.new(1, 1, 1)
    knob.Text = ""
    knob.AutoButtonColor = false
    knob.Parent = holder
    local kc = Instance.new("UICorner", knob)
    kc.CornerRadius = UDim.new(1, 0)

    local on = state
    local function render()
        knob.Position = on and UDim2.new(1, -16, 0.5, -7) or UDim2.new(0, 2, 0.5, -7)
        holder.BackgroundColor3 = on and COLOR_ACCENT_D or COLOR_BG
    end
    knob.MouseButton1Click:Connect(function()
        on = not on
        render()
        if onChange then onChange(on) end
    end)
    if parent and parent.Name ~= "" and pos then
        Registry[parent.Name .. ":" .. tostring(pos.Y.Offset)] = {
            get = function() return on end,
            set = function(v)
                on = v
                render()
                if onChange then onChange(v) end
            end,
        }
    end
    return holder, function(v)
        on = v
        render()
    end
end

