-- группа кнопок, где активна только одна
local function makeExclusiveRow(parent, items, activeIndex, posY, chipWidth, chipHeight, gap)
    local chips = {}
    for i, text in ipairs(items) do
        local x = (i - 1) * (chipWidth + gap)
        chips[i] = makeChip(parent, UDim2.new(0, x, 0, posY), UDim2.new(0, chipWidth, 0, chipHeight), text, i == activeIndex)
    end
    for i, chip in ipairs(chips) do
        chip.MouseButton1Click:Connect(function()
            for j, other in ipairs(chips) do
                local isActive = (j == i)
                other.BackgroundColor3 = isActive and COLOR_ACCENT_D or COLOR_BG
                other.TextColor3 = isActive and COLOR_TEXT or COLOR_TEXT_D
                local st = other:FindFirstChildOfClass("UIStroke")
                if st then st.Color = isActive and COLOR_ACCENT or COLOR_LINE end
            end
        end)
    end
    return chips
end

