local function makeSideTab(parent, name, order, fraction, active)
    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(1, 0, fraction, -4)
    btn.LayoutOrder = order
    btn.Text = ""
    btn.AutoButtonColor = false
    btn.BackgroundTransparency = 1
    btn.Visible = active == true   -- видна только активная вкладка
    btn.Parent = parent

    local length = TAB_AREA_H * fraction - 4

    local label = Instance.new("TextLabel")
    label.BackgroundTransparency = 1
    label.AnchorPoint = Vector2.new(0.5, 0.5)
    label.Position = UDim2.new(0.5, 0, 0.5, 0)
    label.Size = UDim2.new(0, length, 0, 28)
    label.Text = name
    label.Font = Enum.Font.GothamBlack
    label.TextSize = 10
    label.TextWrapped = false
    label.TextColor3 = active and COLOR_BLUE or COLOR_TEXT_D
    label.Rotation = -90
    label.Parent = btn

    tabLabels[name] = label
    return btn
end

for i, name in ipairs(tabs) do
    makeSideTab(TabHolder, name, i, 1, name == "MAIN")
end

local currentTabIndex = 1
local function selectTab(name)
    for i, n in ipairs(tabs) do
        if n == name then currentTabIndex = i end
    end
    for n2, l2 in pairs(tabLabels) do
        l2.TextColor3 = (n2 == name) and COLOR_BLUE or COLOR_TEXT_D
        l2.Parent.Visible = (n2 == name)   -- показываем только выбранный раздел
    end
    for n2, pg in pairs(pages) do
        pg.Visible = (n2 == name)
    end
end

for name, label in pairs(tabLabels) do
    label.Parent.MouseButton1Click:Connect(function() selectTab(name) end)
end

-- стрелка-шеврон из двух повёрнутых полосок (без шрифтов)
local function makeArrowButton(up)
    local btn = Instance.new("TextButton")
    btn.Name = up and "TabUp" or "TabDown"
    btn.Size = UDim2.new(1, 0, 0, ARROW_H)
    btn.Position = up and UDim2.new(0, 0, 0, 0) or UDim2.new(0, 0, 1, -ARROW_H)
    btn.Text = ""
    btn.AutoButtonColor = false
    btn.BackgroundTransparency = 1
    btn.Parent = SideLeft

    local bars = {}
    for side = -1, 1, 2 do
        local bar = Instance.new("Frame")
        bar.AnchorPoint = Vector2.new(0.5, 0.5)
        bar.Size = UDim2.new(0, 10, 0, 3)
        bar.Position = UDim2.new(0.5, side * 3.4, 0.5, 0)
        -- вверх: левая половина идёт вниз-влево, правая вниз-вправо; вниз — наоборот
        bar.Rotation = (up and 1 or -1) * side * 38
        bar.BackgroundColor3 = COLOR_BLUE
        bar.BorderSizePixel = 0
        bar.Parent = btn
        local c = Instance.new("UICorner", bar)
        c.CornerRadius = UDim.new(1, 0)
        table.insert(bars, bar)
    end

    local function paint(col)
        for _, b in ipairs(bars) do b.BackgroundColor3 = col end
    end
    btn.MouseButton1Down:Connect(function() paint(COLOR_TEXT_D) end)
    btn.MouseButton1Up:Connect(function() paint(COLOR_BLUE) end)
    btn.MouseLeave:Connect(function() paint(COLOR_BLUE) end)
    return btn
end

local arrowUp = makeArrowButton(true)
local arrowDown = makeArrowButton(false)

-- по кругу: сверху вверх с первого раздела -> последний, снизу вниз с последнего -> первый
arrowUp.MouseButton1Click:Connect(function()
    local i = currentTabIndex - 1
    if i < 1 then i = #tabs end
    selectTab(tabs[i])
end)
arrowDown.MouseButton1Click:Connect(function()
    local i = currentTabIndex + 1
    if i > #tabs then i = 1 end
    selectTab(tabs[i])
end)

