    ps.Color = COLOR_ACCENT
    ps.Thickness = 1.5

    local titleLbl = Instance.new("TextLabel")
    titleLbl.BackgroundTransparency = 1
    titleLbl.Position = UDim2.new(0, 8, 0, 4)
    titleLbl.Size = UDim2.new(0, 100, 0, 16)
    titleLbl.Text = "SPEED"
    titleLbl.Font = Enum.Font.GothamBold
    titleLbl.TextSize = 11
    titleLbl.TextColor3 = COLOR_BLUE
    titleLbl.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl.Parent = panel

    local function speedRow(y, labelText, boxName, default)
        makeLabel(panel, UDim2.new(0, 8, 0, y), labelText, UDim2.new(0, 90, 0, 18))
        local box = Instance.new("TextBox")
        box.Name = boxName
        box.Size = UDim2.new(0, 40, 0, 22)
        box.Position = UDim2.new(1, -48, 0, y - 2)
        box.BackgroundColor3 = COLOR_BG
        box.Text = tostring(default)
        box.Font = Enum.Font.GothamBold
        box.TextSize = 12
        box.TextColor3 = COLOR_TEXT
        box.TextXAlignment = Enum.TextXAlignment.Center
        box.ClearTextOnFocus = false
        box.Parent = panel
        local bc = Instance.new("UICorner", box)
        bc.CornerRadius = UDim.new(0, 6)
        local bs = Instance.new("UIStroke", box)
        bs.Color = COLOR_ACCENT
        bs.Thickness = 1.5

        -- только числа (можно с точкой, как 24.5 в MVP)
        box:GetPropertyChangedSignal("Text"):Connect(function()
            local t = box.Text:gsub("[^%d%.]", "")
            if box.Text ~= t then box.Text = t end
        end)
        -- пустое / неверное значение возвращаем к последнему рабочему
        local last = default
        box.FocusLost:Connect(function()
            local v = tonumber(box.Text)
            if v and v > 0 and v < math.huge then
                last = v
            else
                box.Text = tostring(last)
            end
        end)
        return box
    end

    local normalBox = speedRow(26, "Normal Speed", "NormalSpeed", MVP_NORMAL)
    local carryBox = speedRow(56, "Carry Speed", "CarrySpeed", MVP_CARRY)

    local resetBtn = Instance.new("TextButton")
    resetBtn.Name = "ResetBtn"
    resetBtn.Size = UDim2.new(0, 26, 0, 22)
    resetBtn.Position = UDim2.new(1, -78, 0, 38)
    resetBtn.BackgroundColor3 = COLOR_BG
    resetBtn.Text = "R"
    resetBtn.Font = Enum.Font.GothamBold
    resetBtn.TextSize = 12
    resetBtn.TextColor3 = COLOR_BLUE
    resetBtn.AutoButtonColor = false
    resetBtn.Parent = panel
    local rbc = Instance.new("UICorner", resetBtn)
    rbc.CornerRadius = UDim.new(0, 6)
    local rbs = Instance.new("UIStroke", resetBtn)
    rbs.Color = COLOR_ACCENT
    rbs.Thickness = 1.5
    resetBtn.MouseButton1Click:Connect(function()
        normalBox.Text = tostring(MVP_NORMAL)
        carryBox.Text = tostring(MVP_CARRY)
    end)
end

