-- ================= MAIN: Hold Jump / Manual Jump =================
do
    local panel3 = Instance.new("Frame")
    panel3.Name = "JumpPanel"
    panel3.Size = UDim2.new(1, 0, 0, 92)
    panel3.BackgroundColor3 = COLOR_PANEL
    panel3.BorderSizePixel = 0
    panel3.LayoutOrder = 3
    panel3.Parent = currentPage

    local pc3 = Instance.new("UICorner", panel3)
    pc3.CornerRadius = UDim.new(0, 10)

    local ps3 = Instance.new("UIStroke", panel3)
    ps3.Color = COLOR_ACCENT
    ps3.Thickness = 1.5

    local titleLbl3 = Instance.new("TextLabel")
    titleLbl3.BackgroundTransparency = 1
    titleLbl3.Position = UDim2.new(0, 8, 0, 4)
    titleLbl3.Size = UDim2.new(0, 100, 0, 16)
    titleLbl3.Text = "JUMP"
    titleLbl3.Font = Enum.Font.GothamBold
    titleLbl3.TextSize = 11
    titleLbl3.TextColor3 = COLOR_BLUE
    titleLbl3.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl3.Parent = panel3

    local closeBtn3 = Instance.new("TextButton")
    closeBtn3.Size = UDim2.new(0, 16, 0, 16)
    closeBtn3.Position = UDim2.new(1, -22, 0, 4)
    closeBtn3.BackgroundTransparency = 1
    closeBtn3.Text = "X"
    closeBtn3.Font = Enum.Font.GothamBold
    closeBtn3.TextSize = 12
    closeBtn3.TextColor3 = COLOR_TEXT_D
    closeBtn3.AutoButtonColor = false
    closeBtn3.Parent = panel3
    closeBtn3.MouseButton1Click:Connect(function()
        panel3.Visible = false
    end)

    -- Логика прыжков взята из MVP HUB (Infinite Jump: режимы hold / manual)
    local RunService = game:GetService("RunService")
    local JUMP_POWER = 55
    local holdJumpOn = false
    local manualJumpOn = false

    local function getParts()
        local ch = player.Character
        if not ch then return nil end
        return ch:FindFirstChildOfClass("Humanoid"), ch:FindFirstChild("HumanoidRootPart")
    end

    -- Hold Jump (из Zurich Hub, Inf Jump / Hold): пока зажат пробел / кнопка прыжка —
    -- каждые 0.08 с подбрасывает вверх (в том числе в воздухе)
    local HOP_POWER, HOP_COOLDOWN = 55, 0.08
    local lastHopT = 0
    local holdConn = nil

    local function startHoldJump()
        if holdConn then return end
        holdConn = RunService.Heartbeat:Connect(function()
            if not holdJumpOn then return end
            pcall(function()
                local hum, root = getParts()
                if not hum or not root then return end
                local now = tick()
                local wants = UserInputService:IsKeyDown(Enum.KeyCode.Space)
                    or UserInputService:IsKeyDown(Enum.KeyCode.ButtonA)
                    or hum.Jump == true
                if wants and (now - lastHopT) >= HOP_COOLDOWN then
                    lastHopT = now
                    root.Velocity = Vector3.new(root.Velocity.X, HOP_POWER, root.Velocity.Z)
                end
            end)
        end)
    end
    local function stopHoldJump()
        if holdConn then holdConn:Disconnect() holdConn = nil end
    end

    -- мгновенный первый прыжок при нажатии (как в Zurich)
    UserInputService.InputBegan:Connect(function(input, gpe)
        if gpe or not holdJumpOn then return end
        if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
            lastHopT = tick() - HOP_COOLDOWN
        end
    end)

    makeLabel(panel3, UDim2.new(0, 8, 0, 26), "Hold Jump", UDim2.new(0, 100, 0, 18))
    makeToggle(panel3, UDim2.new(1, -44, 0, 26), false, function(v)
        holdJumpOn = v
        if v then startHoldJump() else stopHoldJump() end
    end)

    -- Manual Jump: каждое нажатие прыжка даёт новый прыжок, даже в воздухе
    makeLabel(panel3, UDim2.new(0, 8, 0, 58), "Manual Jump", UDim2.new(0, 100, 0, 18))
    makeToggle(panel3, UDim2.new(1, -44, 0, 58), false, function(v) manualJumpOn = v end)

    UserInputService.JumpRequest:Connect(function()
        if not manualJumpOn then return end
        local _, root = getParts()
        if root then
            local v = root.AssemblyLinearVelocity
            root.AssemblyLinearVelocity = Vector3.new(v.X, JUMP_POWER, v.Z)
        end
    end)
end

-- ================= MAIN: Auto Left / Auto Right (логика из MVP HUB) =================
do
    local RunService = game:GetService("RunService")

    -- точки маршрута из MVP HUB
    local AP = {
        L1 = Vector3.new(-476.48, -6.28, 92.73),
        L2 = Vector3.new(-483.12, -4.95, 94.80),
        L_FACE = Vector3.new(-482.25, -4.96, 92.09),
        R1 = Vector3.new(-476.16, -6.52, 25.62),
        R2 = Vector3.new(-483.06, -5.03, 25.48),
        R_FACE = Vector3.new(-482.06, -6.93, 35.47),
    }

    local panel4 = Instance.new("Frame")
    panel4.Name = "AutoPanel"
    panel4.Size = UDim2.new(1, 0, 0, 92)
    panel4.BackgroundColor3 = COLOR_PANEL
    panel4.BorderSizePixel = 0
    panel4.LayoutOrder = 4
    panel4.Parent = currentPage

    local pc4 = Instance.new("UICorner", panel4)
    pc4.CornerRadius = UDim.new(0, 10)
    local ps4 = Instance.new("UIStroke", panel4)
    ps4.Color = COLOR_ACCENT
    ps4.Thickness = 1.5

    local titleLbl4 = Instance.new("TextLabel")
    titleLbl4.BackgroundTransparency = 1
    titleLbl4.Position = UDim2.new(0, 8, 0, 4)
    titleLbl4.Size = UDim2.new(0, 100, 0, 16)
    titleLbl4.Text = "AUTO"
    titleLbl4.Font = Enum.Font.GothamBold
    titleLbl4.TextSize = 11
    titleLbl4.TextColor3 = COLOR_BLUE
    titleLbl4.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl4.Parent = panel4

    local closeBtn4 = Instance.new("TextButton")
    closeBtn4.Size = UDim2.new(0, 16, 0, 16)
    closeBtn4.Position = UDim2.new(1, -22, 0, 4)
    closeBtn4.BackgroundTransparency = 1
    closeBtn4.Text = "X"
    closeBtn4.Font = Enum.Font.GothamBold
    closeBtn4.TextSize = 12
    closeBtn4.TextColor3 = COLOR_TEXT_D
    closeBtn4.AutoButtonColor = false
    closeBtn4.Parent = panel4
    closeBtn4.MouseButton1Click:Connect(function()
        panel4.Visible = false
    end)

    local conns = {left = nil, right = nil}
    local setVisual = {}

    local function getSpeed()
        local box = Main:FindFirstChild("NormalSpeed", true) -- поле Normal Speed из CUSTOM 1
        return (box and tonumber(box.Text)) or 60
    end

    local function stopAuto(side)
        if conns[side] then conns[side]:Disconnect(); conns[side] = nil end
        local ch = player.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if hum then hum:Move(Vector3.zero, false) end
        if setVisual[side] then setVisual[side](false) end
    end

    local function startAuto(side)
        local other = side == "left" and "right" or "left"
        if conns[other] then stopAuto(other) end
        if conns[side] then conns[side]:Disconnect() end

        local p1 = side == "left" and AP.L1 or AP.R1
        local p2 = side == "left" and AP.L2 or AP.R2
        local face = side == "left" and AP.L_FACE or AP.R_FACE
        local phase = 1

        conns[side] = RunService.Heartbeat:Connect(function()
            local ch = player.Character
            if not ch then return end
            local root = ch:FindFirstChild("HumanoidRootPart")
            local hum = ch:FindFirstChildOfClass("Humanoid")
            if not root or not hum then return end
            local spd = getSpeed()
            local target = phase == 1 and p1 or p2

            local flat = Vector3.new(target.X, root.Position.Y, target.Z)
            if (flat - root.Position).Magnitude < 1 then
                if phase == 1 then
                    phase = 2
                    target = p2
                else
                    -- дошли до конца: стоп и разворот лицом к точке
                    hum:Move(Vector3.zero, false)
                    root.AssemblyLinearVelocity = Vector3.zero
                    stopAuto(side)
                    local facePos = Vector3.new(face.X, root.Position.Y, face.Z)
                    if (facePos - root.Position).Magnitude > 0.01 then
                        root.CFrame = CFrame.new(root.Position, facePos)
                    end
                    return
                end
            end

            local d = target - root.Position
            local flatD = Vector3.new(d.X, 0, d.Z)
            if flatD.Magnitude < 0.001 then return end
            local mv = flatD.Unit
            hum:Move(mv, false)
            root.AssemblyLinearVelocity = Vector3.new(mv.X * spd, root.AssemblyLinearVelocity.Y, mv.Z * spd)
        end)
    end

    makeLabel(panel4, UDim2.new(0, 8, 0, 26), "Auto Left", UDim2.new(0, 100, 0, 18))
    local _, setLeft = makeToggle(panel4, UDim2.new(1, -44, 0, 26), false, function(v)
        if v then startAuto("left") else stopAuto("left") end
    end)

    makeLabel(panel4, UDim2.new(0, 8, 0, 58), "Auto Right", UDim2.new(0, 100, 0, 18))
    local _, setRight = makeToggle(panel4, UDim2.new(1, -44, 0, 58), false, function(v)
        if v then startAuto("right") else stopAuto("right") end
    end)

    setVisual.left = setLeft
    setVisual.right = setRight
    Actions.AutoLeft = {
        get = function() return conns.left ~= nil end,
        set = function(v) setLeft(v); if v then startAuto("left") else stopAuto("left") end end,
    }
    Actions.AutoRight = {
        get = function() return conns.right ~= nil end,
        set = function(v) setRight(v); if v then startAuto("right") else stopAuto("right") end end,
    }
end

-- ================= COMBAT: Anti Ragdoll V1/V2 (из другого хаба), Anti Die, Unwalk =================
currentPage = pages["COMBAT"]
do
    local RunService = game:GetService("RunService")
    local LP = player

    -- ---------- Anti Ragdoll V1 / V2 (перенесено из другого хаба) ----------
    -- V1 = Splatter reset (сброс RagdollEndTime + удаление ragdoll-констрейнтов)
    -- V2 = No Splatter reset (GettingUp + включение моторов/констрейнтов, с кулдауном)
    local _arv = {
        Enabled = false,
        Mode = "V1",
        Connection = nil,
        CharConn = nil,
        NoSplatterCooldown = 0,
    }

    local function getChar()
        return LP.Character
    end

    local function isRagdollStateAR(hum)
        if not hum then return false end
        local st = hum:GetState()
        return hum.PlatformStand
            or st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.FallingDown
    end

    local function forceNoSplatterReset()
        local char = getChar()
        if not char then return end
        local hum  = char:FindFirstChildOfClass("Humanoid")
        local root = char:FindFirstChild("HumanoidRootPart")
        if not hum or not root or hum.Health <= 0 then return end

        pcall(function()
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)

            root.Velocity = Vector3.zero
            root.RotVelocity = Vector3.zero
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero

            for _, obj in ipairs(char:GetDescendants()) do
                if obj:IsA("Motor6D") then obj.Enabled = true end
                if obj:IsA("Constraint") then obj.Enabled = true end
            end

            if workspace.CurrentCamera then
                workspace.CurrentCamera.CameraSubject = hum
            end

            local PM = LP:FindFirstChild("PlayerScripts")
                and LP.PlayerScripts:FindFirstChild("PlayerModule")
            if PM then
                local cm = PM:FindFirstChild("ControlModule")
                if cm then
                    local ok, CM = pcall(require, cm)
                    if ok and CM and CM.Enable then
                        pcall(function() CM:Enable() end)
                    end
                end
            end

            hum.AutoRotate = true
            hum.PlatformStand = false
            hum.Sit = false
        end)
    end

    local function applySplatterReset(char, hum, root)
        if not char or not hum or not root then return end
        pcall(function()
            LP:SetAttribute("RagdollEndTime", workspace:GetServerTimeNow())
        end)

        for _, d in ipairs(char:GetDescendants()) do
            if d:IsA("BallSocketConstraint") then
                d:Destroy()
            elseif d:IsA("Attachment") and d.Name:find("RagdollAttachment") then
                d:Destroy()
            end
        end

        for _, obj in ipairs(char:GetDescendants()) do
            if obj:IsA("Motor6D") and not obj.Enabled then
                obj.Enabled = true
            end
        end

        if hum.Health > 0 then
            pcall(function() hum:ChangeState(Enum.HumanoidStateType.Running) end)
        end

        if workspace.CurrentCamera then
            workspace.CurrentCamera.CameraSubject = hum
        end

        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end

    local function antiRagdollTick()
        if not _arv.Enabled then return end

        local char = getChar()
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end

        local root = char:FindFirstChild("HumanoidRootPart")
        local ragdolled = isRagdollStateAR(hum)

        if _arv.Mode == "V2" then
            if ragdolled then
                local now = tick()
                if now - (_arv.NoSplatterCooldown or 0) > 0.15 then
                    _arv.NoSplatterCooldown = now
                    forceNoSplatterReset()
                end
            end
            return
        end

        if not root then return end

        local endTime = LP:GetAttribute("RagdollEndTime")
        if endTime and (endTime - workspace:GetServerTimeNow()) > 0 then
            ragdolled = true
        end

        if ragdolled then
            applySplatterReset(char, hum, root)
        end
    end

    local function hookCharacter()
        if not _arv.Enabled then return end
        if _arv.Connection then
            _arv.Connection:Disconnect()
            _arv.Connection = nil
        end
        _arv.Connection = RunService.Heartbeat:Connect(antiRagdollTick)
    end

    local function startAntiRagdoll(mode)
        if _arv.Connection then
            _arv.Connection:Disconnect()
            _arv.Connection = nil
        end
        if _arv.CharConn then
            pcall(function() _arv.CharConn:Disconnect() end)
            _arv.CharConn = nil
        end
        _arv.Mode = (mode == "V2") and "V2" or "V1"
        _arv.Enabled = true
        _arv.NoSplatterCooldown = 0
        _arv.Connection = RunService.Heartbeat:Connect(antiRagdollTick)
        _arv.CharConn = LP.CharacterAdded:Connect(function()
            task.wait(0.5)
            if _arv.Enabled then hookCharacter() end
        end)
    end

    local function stopAntiRagdoll()
        _arv.Enabled = false
        if _arv.Connection then
            _arv.Connection:Disconnect()
            _arv.Connection = nil
        end
        if _arv.CharConn then
            _arv.CharConn:Disconnect()
            _arv.CharConn = nil
        end
    end

    local function setAntiRagdollMode(mode)
        stopAntiRagdoll()
        if mode == "v1" then startAntiRagdoll("V1") elseif mode == "v2" then startAntiRagdoll("V2") end
    end

    -- ---------- Anti Die ----------
    local antiDie = { enabled = false, loop = nil, healthConn = nil, charConn = nil, invincibleUntil = 0 }
    local AD_THRESHOLD, AD_INVINCIBLE = 50, 0.75

    local function superHeal(hum)
        if not hum or not hum.Parent then return end
        local maxHealth = hum.MaxHealth or 100
        if maxHealth <= 0 or maxHealth == math.huge then maxHealth = 100 end
        pcall(function()
            hum.Health = maxHealth
            if hum.MaxHealth < maxHealth then hum.MaxHealth = maxHealth end
        end)
        antiDie.invincibleUntil = tick() + AD_INVINCIBLE
        pcall(function()
            for _, child in ipairs(hum.Parent:GetChildren()) do
                if child:IsA("NumberValue") then
                    local n = child.Name:lower()
                    if n:find("health") or n:find("hp") or n:find("life") then child.Value = maxHealth end
                end
                if child:IsA("BoolValue") and child.Name:lower():find("dead") then child.Value = false end
            end
        end)
    end

    local function revive(hum, root, lift)
        superHeal(hum)
        pcall(function()
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            hum:ChangeState(Enum.HumanoidStateType.Running)
        end)
        if root then
            pcall(function()
                root.CFrame = CFrame.new(root.Position + Vector3.new(0, lift, 0))
                root.AssemblyLinearVelocity = Vector3.zero
            end)
        end
    end

    local function preventDamage(root, hum)
        if hum.Health < (hum.MaxHealth or 100) then superHeal(hum) end
        if tick() < antiDie.invincibleUntil and hum.Health < (hum.MaxHealth or 100) then
            hum.Health = hum.MaxHealth or 100
        end
        local state = hum:GetState()
        if state == Enum.HumanoidStateType.Physics or state == Enum.HumanoidStateType.Ragdoll
            or state == Enum.HumanoidStateType.FallingDown or state == Enum.HumanoidStateType.Dead then
            pcall(function()
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                hum:ChangeState(Enum.HumanoidStateType.Running)
            end)
            superHeal(hum)
            if root then pcall(function() root.AssemblyAngularVelocity = Vector3.zero end) end
        end
        if hum.Health <= 0 then revive(hum, root, 2) end
    end

    local function attachHealth(char)
        if antiDie.healthConn then antiDie.healthConn:Disconnect(); antiDie.healthConn = nil end
        local hum = char and (char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 3))
        if not hum then return end
        antiDie.healthConn = hum:GetPropertyChangedSignal("Health"):Connect(function()
            if not antiDie.enabled then return end
            if hum.Health < (hum.MaxHealth or 100) then superHeal(hum) end
            if hum.Health <= 0 then revive(hum, char:FindFirstChild("HumanoidRootPart"), 3) end
        end)
        if hum.Health < (hum.MaxHealth or 100) then superHeal(hum) end
    end

    local function startAntiDie()
        if antiDie.enabled then return end
        antiDie.enabled = true
        antiDie.loop = RunService.Heartbeat:Connect(function()
            local char = LP.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            local root = char:FindFirstChild("HumanoidRootPart")
            if not hum then return end
            if hum.Health <= 0 then revive(hum, root, 3)
            elseif hum.Health <= AD_THRESHOLD or hum.Health < (hum.MaxHealth or 100) then superHeal(hum) end
            preventDamage(root, hum)
        end)
        if LP.Character then attachHealth(LP.Character) end
        antiDie.charConn = LP.CharacterAdded:Connect(function(char)
            if not antiDie.enabled then return end
            task.wait(0.05)
            attachHealth(char)
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then superHeal(hum) end
        end)
    end

    local function stopAntiDie()
        antiDie.enabled = false
        if antiDie.loop then antiDie.loop:Disconnect(); antiDie.loop = nil end
        if antiDie.healthConn then antiDie.healthConn:Disconnect(); antiDie.healthConn = nil end
        if antiDie.charConn then antiDie.charConn:Disconnect(); antiDie.charConn = nil end
        pcall(function()
            local char = LP.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hum then return end
            hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
            hum.BreakJointsOnDeath = true
        end)
    end

    -- ---------- Unwalk ----------
    local unwalkSavedAnimate = nil

    local function startUnwalk()
        local c = LP.Character
        if not c then return end
        local hum = c:FindFirstChildOfClass("Humanoid")
        if hum then
            for _, t in ipairs(hum:GetPlayingAnimationTracks()) do pcall(function() t:Stop() end) end
        end
        local anim = c:FindFirstChild("Animate")
        if anim then
            unwalkSavedAnimate = anim:Clone()
            anim:Destroy()
        end
    end

    local function stopUnwalk()
        local c = LP.Character
        if c and not c:FindFirstChild("Animate") then
            local src = game:GetService("StarterPlayer"):FindFirstChildOfClass("StarterCharacterScripts")
            local starterAnim = src and src:FindFirstChild("Animate")
            if starterAnim then
                starterAnim:Clone().Parent = c
            elseif unwalkSavedAnimate then
                unwalkSavedAnimate:Clone().Parent = c
            end
        end
        unwalkSavedAnimate = nil
    end

    -- ---------- Панель ----------
    local panel5 = Instance.new("Frame")
    panel5.Name = "CombatPanel"
    panel5.Size = UDim2.new(1, 0, 0, 122)
    panel5.BackgroundColor3 = COLOR_PANEL
    panel5.BorderSizePixel = 0
    panel5.LayoutOrder = 1
    panel5.Parent = currentPage
    local pc5 = Instance.new("UICorner", panel5)
    pc5.CornerRadius = UDim.new(0, 10)
    local ps5 = Instance.new("UIStroke", panel5)
    ps5.Color = COLOR_ACCENT
    ps5.Thickness = 1.5

    local titleLbl5 = Instance.new("TextLabel")
    titleLbl5.BackgroundTransparency = 1
    titleLbl5.Position = UDim2.new(0, 8, 0, 4)
    titleLbl5.Size = UDim2.new(0, 100, 0, 16)
    titleLbl5.Text = "PROTECTION"
    titleLbl5.Font = Enum.Font.GothamBold
    titleLbl5.TextSize = 11
    titleLbl5.TextColor3 = COLOR_BLUE
    titleLbl5.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl5.Parent = panel5

    -- Anti Ragdoll: два чипа V1 / V2 (повторное нажатие на активный — выключает)
    makeLabel(panel5, UDim2.new(0, 8, 0, 26), "Anti Ragdoll", UDim2.new(0, 70, 0, 18))
    local chipV1 = makeChip(panel5, UDim2.new(1, -68, 0, 26), UDim2.new(0, 28, 0, 18), "V1", false)
    local chipV2 = makeChip(panel5, UDim2.new(1, -36, 0, 26), UDim2.new(0, 28, 0, 18), "V2", false)
    local arMode = "off"
    local function paintChip(chip, active)
        chip.BackgroundColor3 = active and COLOR_ACCENT_D or COLOR_BG
        chip.TextColor3 = active and COLOR_TEXT or COLOR_TEXT_D
        local st = chip:FindFirstChildOfClass("UIStroke")
        if st then st.Color = active and COLOR_ACCENT or COLOR_LINE end
    end
    local function setMode(mode)
        arMode = mode
        paintChip(chipV1, mode == "v1")
        paintChip(chipV2, mode == "v2")
        setAntiRagdollMode(mode)
    end
    chipV1.MouseButton1Click:Connect(function() setMode(arMode == "v1" and "off" or "v1") end)
    chipV2.MouseButton1Click:Connect(function() setMode(arMode == "v2" and "off" or "v2") end)
    Flags.arMode = {get = function() return arMode end, set = function(m) setMode(m) end}

    -- Anti Die
    makeLabel(panel5, UDim2.new(0, 8, 0, 58), "Anti Die", UDim2.new(0, 100, 0, 18))
    makeToggle(panel5, UDim2.new(1, -44, 0, 58), false, function(v)
        if v then startAntiDie() else stopAntiDie() end
    end)

    -- Unwalk
    makeLabel(panel5, UDim2.new(0, 8, 0, 90), "Unwalk", UDim2.new(0, 100, 0, 18))
    makeToggle(panel5, UDim2.new(1, -44, 0, 90), false, function(v)
        if v then startUnwalk() else stopUnwalk() end
    end)
end
currentPage = pages["MAIN"]

-- ================= COMBAT: Bat Counter V2 + Medusa Counter (логика из MVP HUB) =================
currentPage = pages["COMBAT"]
do
    local RunService = game:GetService("RunService")
    local LP = player
    local PlayersService = Players

    -- ---------- Bat Counter V2 ----------
    local batV2Enabled = false
    local batV2Debounce = false
    local batV2HitCooldown = false
    local batV2Conn = nil
    local BAT_SWING_CD = 0.08
    local lastBatV2Time = 0

    local function isRagdolled(plr)
        if not plr or not plr.Character then return false end
        local hum = plr.Character:FindFirstChildOfClass("Humanoid")
        if not hum then return false end
        local st = hum:GetState()
        return st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll or st == Enum.HumanoidStateType.FallingDown
    end

    local function hasAnimalEquipped(plr)
        if not plr or not plr.Character then return false end
        for _, child in ipairs(plr.Character:GetChildren()) do
            if child:IsA("Tool") then
                if child:FindFirstChild("Handle") or child.Name:find("Animal") or child.Name:find("Pet") then return true end
            end
        end
        return false
    end

    local function getAttacker()
        local myChar = LP.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then return nil end
        local closest, minDist = nil, math.huge
        for _, plr in ipairs(PlayersService:GetPlayers()) do
            if plr ~= LP and plr.Character and hasAnimalEquipped(plr) then
                local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                if tRoot and hum and hum.Health > 0 then
                    local dist = (tRoot.Position - myRoot.Position).Magnitude
                    if dist < 12 and dist < minDist then
                        minDist = dist; closest = plr
                    end
                end
            end
        end
        return closest
    end

    local function getBat()
        local char = LP.Character
        if not char then return nil end
        local function isBat(t)
            local n = t.Name:lower()
            return n:find("bat") or n:find("slap") or n:find("sword") or n:find("knife")
        end
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") and isBat(child) then return child end
        end
        local bp = LP:FindFirstChildOfClass("Backpack")
        if bp then
            for _, child in ipairs(bp:GetChildren()) do
                if child:IsA("Tool") and isBat(child) then child.Parent = char; return child end
            end
            for _, child in ipairs(bp:GetChildren()) do
                if child:IsA("Tool") then child.Parent = char; return child end
            end
        end
        return nil
    end

    local function tryHit()
        if batV2HitCooldown then return end
        batV2HitCooldown = true
        pcall(function()
            local bat = getBat()
            if bat then
                bat:Activate()
                local ev = bat:FindFirstChildWhichIsA("RemoteEvent")
                if ev then ev:FireServer() end
            end
        end)
        task.delay(BAT_SWING_CD, function() batV2HitCooldown = false end)
    end

    local function executeBatV2()
        local now = tick()
        if now - lastBatV2Time < 0.01 then return end
        if batV2Debounce then return end
        batV2Debounce = true
        lastBatV2Time = now
        local attacker = getAttacker()
        if not attacker or isRagdolled(attacker) or not hasAnimalEquipped(attacker) then
            batV2Debounce = false
            return
        end
        local char = LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local attRoot = attacker.Character and attacker.Character:FindFirstChild("HumanoidRootPart")
        if hrp and attRoot then
            if sethiddenproperty then pcall(sethiddenproperty, hrp, "PhysicsRepRootPart", attRoot) end
            local targetPos = attRoot.Position + Vector3.new(0, 0.9, 0)
            if (hrp.Position - targetPos).Magnitude > 8 then hrp.CFrame = CFrame.new(targetPos) end
            tryHit()
            task.delay(0.05, tryHit)
            task.delay(0.1, tryHit)
        end
        task.delay(0.2, function() batV2Debounce = false end)
    end

    local function stopBatV2()
        if batV2Conn then batV2Conn:Disconnect(); batV2Conn = nil end
        batV2Debounce = false
        batV2HitCooldown = false
    end

    local function startBatV2()
        if batV2Conn then return end
        batV2Conn = RunService.Heartbeat:Connect(function()
            if not batV2Enabled or batV2Debounce then return end
            local character = LP.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if not humanoid or humanoid.Health <= 0 then return end
            local st = humanoid:GetState()
            local beingAttacked = st == Enum.HumanoidStateType.Physics
                or st == Enum.HumanoidStateType.Ragdoll
                or st == Enum.HumanoidStateType.FallingDown
                or st == Enum.HumanoidStateType.GettingUp
                or st == Enum.HumanoidStateType.Stunned
            if beingAttacked then
                local attacker = getAttacker()
                if attacker and not isRagdolled(attacker) and hasAnimalEquipped(attacker) then
                    executeBatV2()
                end
            end
        end)
    end

    -- ---------- Medusa Counter ----------
    local MEDUSA_COOLDOWN = 25
    local medusaEnabled = false
    local medusaDebounce = false
    local medusaLastUsed = 0
    local anchorConns = {}
    local charConn = nil

    local function findMedusa()
        local function match(t)
            local n = t.Name:lower()
            return n:find("medusa") or n:find("head") or n:find("stone")
        end
        local c = LP.Character
        if not c then return nil end
        for _, t in ipairs(c:GetChildren()) do
            if t:IsA("Tool") and match(t) then return t end
        end
        local bp = LP:FindFirstChild("Backpack")
        if bp then
            for _, t in ipairs(bp:GetChildren()) do
                if t:IsA("Tool") and match(t) then return t end
            end
        end
        return nil
    end

    local function useMedusa()
        if medusaDebounce then return end
        if tick() - medusaLastUsed < MEDUSA_COOLDOWN then return end
        local c = LP.Character
        if not c then return end
        medusaDebounce = true
        local med = findMedusa()
        if not med then medusaDebounce = false; return end
        if med.Parent ~= c then
            local hum = c:FindFirstChildOfClass("Humanoid")
            if hum then hum:EquipTool(med) end
        end
        pcall(function() med:Activate() end)
        medusaLastUsed = tick()
        medusaDebounce = false
    end

    local function watchPart(part)
        return part:GetPropertyChangedSignal("Anchored"):Connect(function()
            if medusaEnabled and part.Anchored and part.Transparency == 1 then useMedusa() end
        end)
    end

    local function clearAnchor()
        for _, c in pairs(anchorConns) do pcall(function() c:Disconnect() end) end
        anchorConns = {}
    end

    local function setupMedusa(char)
        clearAnchor()
        if not char or not medusaEnabled then return end
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") then table.insert(anchorConns, watchPart(part)) end
        end
        table.insert(anchorConns, char.DescendantAdded:Connect(function(part)
            if part:IsA("BasePart") then table.insert(anchorConns, watchPart(part)) end
        end))
    end

    local function stopMedusa()
        clearAnchor()
        if charConn then charConn:Disconnect(); charConn = nil end
    end

    -- ---------- Панель ----------
    local panel6 = Instance.new("Frame")
    panel6.Name = "CounterPanel"
    panel6.Size = UDim2.new(1, 0, 0, 92)
    panel6.BackgroundColor3 = COLOR_PANEL
    panel6.BorderSizePixel = 0
    panel6.LayoutOrder = 2
    panel6.Parent = currentPage
    local pc6 = Instance.new("UICorner", panel6)
    pc6.CornerRadius = UDim.new(0, 10)
    local ps6 = Instance.new("UIStroke", panel6)
    ps6.Color = COLOR_ACCENT
    ps6.Thickness = 1.5

    local titleLbl6 = Instance.new("TextLabel")
    titleLbl6.BackgroundTransparency = 1
    titleLbl6.Position = UDim2.new(0, 8, 0, 4)
    titleLbl6.Size = UDim2.new(0, 100, 0, 16)
    titleLbl6.Text = "COUNTER"
    titleLbl6.Font = Enum.Font.GothamBold
    titleLbl6.TextSize = 11
    titleLbl6.TextColor3 = COLOR_BLUE
    titleLbl6.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl6.Parent = panel6

    makeLabel(panel6, UDim2.new(0, 8, 0, 26), "Bat Counter V2", UDim2.new(0, 100, 0, 18))
    makeToggle(panel6, UDim2.new(1, -44, 0, 26), false, function(v)
        batV2Enabled = v
        if v then startBatV2() else stopBatV2() end
    end)

    makeLabel(panel6, UDim2.new(0, 8, 0, 58), "Medusa Counter", UDim2.new(0, 100, 0, 18))
    makeToggle(panel6, UDim2.new(1, -44, 0, 58), false, function(v)
        medusaEnabled = v
        if v then
            setupMedusa(LP.Character)
            if charConn then charConn:Disconnect() end
            charConn = LP.CharacterAdded:Connect(function(ch) setupMedusa(ch) end)
        else
            stopMedusa()
        end
    end)
end
currentPage = pages["MAIN"]

-- ================= COMBAT: Drop Brainrot (логика из MVP HUB) =================
currentPage = pages["COMBAT"]
do
    local RunService = game:GetService("RunService")
    local LP = player

    local DROP_ASCEND_DURATION = 0.2
    local DROP_ASCEND_SPEED = 150
    local dropMode = 1          -- 1 = Fling, 2 = Jump Drop
    local dropActive = false
    local lastDropTime = 0
    local dropConn = nil
    local flingThread = nil
    local setDropVisual = nil   -- задаётся ниже, когда создадим тумблер

    local function setVisual(v)
        if setDropVisual then setDropVisual(v) end
    end

    -- опускаем персонажа на землю после дропа
    local function snapToGround(char, root)
        local rp = RaycastParams.new()
        rp.FilterDescendantsInstances = {char}
        rp.FilterType = Enum.RaycastFilterType.Exclude
        local rr = workspace:Raycast(root.Position, Vector3.new(0, -2000, 0), rp)
        if rr then
            local h = char:FindFirstChildOfClass("Humanoid")
            local off = ((h and h.HipHeight) or 2) + (root.Size.Y / 2)
            root.CFrame = CFrame.new(root.Position.X, rr.Position.Y + off, root.Position.Z)
        end
    end

    local function stopDrop()
        dropActive = false
        if dropConn then dropConn:Disconnect(); dropConn = nil end
        if flingThread then pcall(task.cancel, flingThread); flingThread = nil end
        local c = LP.Character
        local root = c and c:FindFirstChild("HumanoidRootPart")
        if root then root.AssemblyLinearVelocity = Vector3.zero end
        setVisual(false)
    end

    local function finishFling()
        flingThread = nil
        dropActive = false
        local c = LP.Character
        if c then
            local r = c:FindFirstChild("HumanoidRootPart")
            local h = c:FindFirstChildOfClass("Humanoid")
            if r then
                r.AssemblyLinearVelocity = Vector3.zero
                r.AssemblyAngularVelocity = Vector3.zero
                if r.Position.Y < -100 then
                    r.CFrame = CFrame.new(r.Position.X, 5, r.Position.Z)
                end
                snapToGround(c, r)
                if h and h.Health > 0 then h:ChangeState(Enum.HumanoidStateType.Running) end
            end
        end
        setVisual(false)
    end

    local function runDrop()
        if dropActive then return end
        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not root or not hum then setVisual(false); return end

        if dropMode == 1 then
            -- Fling: короткий мощный импульс, затем возврат на землю
            local vel = root.AssemblyLinearVelocity
            local speedH = Vector3.new(vel.X, 0, vel.Z).Magnitude
            local cooldown = (speedH > 5) and 0.6 or 0.25
            if tick() - lastDropTime < cooldown then setVisual(false); return end
            lastDropTime = tick()
            dropActive = true
            setVisual(true)
            flingThread = task.spawn(function()
                local startTime = tick()
                while dropActive and (tick() - startTime) < 0.25 do
                    RunService.Heartbeat:Wait()
                    local c = LP.Character
                    local r = c and c:FindFirstChild("HumanoidRootPart")
                    if not r then break end
                    local v = r.AssemblyLinearVelocity
                    v = Vector3.new(0, v.Y, 0)
                    r.AssemblyLinearVelocity = v * 10000 + Vector3.new(0, 10000, 0)
                    RunService.RenderStepped:Wait()
                    if r and r.Parent then r.AssemblyLinearVelocity = v end
                    RunService.Stepped:Wait()
                    if r and r.Parent then r.AssemblyLinearVelocity = v + Vector3.new(0, 0.1, 0) end
                end
                finishFling()
            end)
            task.delay(0.35, function()
                if dropActive then finishFling() end
            end)
            return
        end

        -- Jump Drop: быстрый взлёт на 0.2 сек и приземление
        dropActive = true
        setVisual(true)
        local t0 = tick()
        if dropConn then dropConn:Disconnect() end
        dropConn = RunService.Heartbeat:Connect(function()
            local r = char and char:FindFirstChild("HumanoidRootPart")
            if not r then
                if dropConn then dropConn:Disconnect(); dropConn = nil end
                dropActive = false
                setVisual(false)
                return
            end
            if tick() - t0 >= DROP_ASCEND_DURATION then
                if dropConn then dropConn:Disconnect(); dropConn = nil end
                snapToGround(char, r)
                r.AssemblyLinearVelocity = Vector3.zero
                dropActive = false
                setVisual(false)
                return
            end
            local v = r.AssemblyLinearVelocity
            r.AssemblyLinearVelocity = Vector3.new(v.X, DROP_ASCEND_SPEED, v.Z)
        end)
    end

    -- ---------- Панель ----------
    local panel7 = Instance.new("Frame")
    panel7.Name = "DropPanel"
    panel7.Size = UDim2.new(1, 0, 0, 92)
    panel7.BackgroundColor3 = COLOR_PANEL
    panel7.BorderSizePixel = 0
    panel7.LayoutOrder = 3
    panel7.Parent = currentPage
    local pc7 = Instance.new("UICorner", panel7)
    pc7.CornerRadius = UDim.new(0, 10)
    local ps7 = Instance.new("UIStroke", panel7)
    ps7.Color = COLOR_ACCENT
    ps7.Thickness = 1.5

    local titleLbl7 = Instance.new("TextLabel")
    titleLbl7.BackgroundTransparency = 1
    titleLbl7.Position = UDim2.new(0, 8, 0, 4)
    titleLbl7.Size = UDim2.new(0, 100, 0, 16)
    titleLbl7.Text = "DROP"
    titleLbl7.Font = Enum.Font.GothamBold
    titleLbl7.TextSize = 11
    titleLbl7.TextColor3 = COLOR_BLUE
    titleLbl7.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl7.Parent = panel7

    -- Drop Brainrot: нажатие запускает дроп, тумблер сам выключится по окончании
    makeLabel(panel7, UDim2.new(0, 8, 0, 26), "Drop Brainrot", UDim2.new(0, 100, 0, 18))
    local _, setter = makeToggle(panel7, UDim2.new(1, -44, 0, 26), false, function(v)
        if v then
            task.spawn(runDrop)
        else
            if dropActive then stopDrop() end
        end
    end)
    setDropVisual = setter
    Actions.DropBR = {
        get = function() return dropActive end,
        set = function(v)
            if v then task.spawn(runDrop) else if dropActive then stopDrop() end end
        end,
    }

    -- Drop Mode: Fling / Jump
    makeLabel(panel7, UDim2.new(0, 8, 0, 58), "Mode", UDim2.new(0, 40, 0, 18))
    local chipFling = makeChip(panel7, UDim2.new(1, -92, 0, 58), UDim2.new(0, 42, 0, 18), "Fling", true)
    local chipJump = makeChip(panel7, UDim2.new(1, -46, 0, 58), UDim2.new(0, 38, 0, 18), "Jump", false)
    local function paint(chip, active)
        chip.BackgroundColor3 = active and COLOR_ACCENT_D or COLOR_BG
        chip.TextColor3 = active and COLOR_TEXT or COLOR_TEXT_D
        local st = chip:FindFirstChildOfClass("UIStroke")
        if st then st.Color = active and COLOR_ACCENT or COLOR_LINE end
    end
    local function setDropMode(m)
        if dropActive then stopDrop() end
        dropMode = m
        paint(chipFling, m == 1)
        paint(chipJump, m == 2)
    end
    chipFling.MouseButton1Click:Connect(function() setDropMode(1) end)
    chipJump.MouseButton1Click:Connect(function() setDropMode(2) end)
    Flags.dropModeCtl = {get = function() return dropMode end, set = function(m) setDropMode(m) end}
end
currentPage = pages["MAIN"]


-- ================= COMBAT: AUTO HIT AFTER DROP — после Drop Brainrot сам бьёт (AIMBOT / TP BAT) =================
currentPage = pages["COMBAT"]
do
    local RunService = game:GetService("RunService")

    local HIT_TIME = 3            -- сколько секунд работает выбранный режим после дропа
    local enabled = false
    local mode = "TPBAT"          -- "AIMBOT" или "TPBAT"
    local wasDropping = false
    local runToken = 0

    local function actionFor(m)
        return Actions[m == "AIMBOT" and "BatAimbot" or "BatV2"]
    end

    -- запускаем выбранный режим на HIT_TIME секунд, потом возвращаем как было
    local function startHit()
        local act = actionFor(mode)
        if not act or not act.set then return end
        runToken += 1
        local my = runToken
        local before = act.get and act.get() or false
        pcall(act.set, true)
        task.delay(HIT_TIME, function()
            if my == runToken and not before then
                pcall(act.set, false)
            end
        end)
    end

    -- ждём окончания дропа (DropBR: активен -> неактивен)
    RunService.Heartbeat:Connect(function()
        local d = Actions.DropBR
        local nowDropping = d and d.get and d.get() == true
        if wasDropping and not nowDropping and enabled then
            task.defer(startHit)
        end
        wasDropping = nowDropping
    end)

    -- ---------- Панель ----------
    local pah = Instance.new("Frame")
    pah.Name = "AutoHitDropPanel"
    pah.Size = UDim2.new(1, 0, 0, 92)
    pah.BackgroundColor3 = COLOR_PANEL
    pah.BorderSizePixel = 0
    pah.LayoutOrder = 4
    pah.Parent = currentPage
    Instance.new("UICorner", pah).CornerRadius = UDim.new(0, 10)
    local pahs = Instance.new("UIStroke", pah)
    pahs.Color = COLOR_ACCENT
    pahs.Thickness = 1.5

    local pahTitle = Instance.new("TextLabel")
    pahTitle.BackgroundTransparency = 1
    pahTitle.Position = UDim2.new(0, 8, 0, 4)
    pahTitle.Size = UDim2.new(0, 140, 0, 16)
    pahTitle.Text = "AUTO HIT AFTER DROP"
    pahTitle.Font = Enum.Font.GothamBold
    pahTitle.TextSize = 11
    pahTitle.TextColor3 = COLOR_BLUE
    pahTitle.TextXAlignment = Enum.TextXAlignment.Left
    pahTitle.Parent = pah

    makeLabel(pah, UDim2.new(0, 8, 0, 26), "Auto Hit After Drop", UDim2.new(0, 150, 0, 18))
    local _, setAhdVisual = makeToggle(pah, UDim2.new(1, -44, 0, 26), false, function(v)
        enabled = v
    end)
    Actions.AutoHitAfterDrop = {
        get = function() return enabled end,
        set = function(v) enabled = v == true; setAhdVisual(enabled) end,
    }

    local chipAim = makeChip(pah, UDim2.new(0, 8, 0, 58), UDim2.new(0.5, -12, 0, 24), "AIMBOT", false)
    local chipTp = makeChip(pah, UDim2.new(0.5, 4, 0, 58), UDim2.new(0.5, -12, 0, 24), "TP BAT", true)
    local function paint(chip, active)
        chip.BackgroundColor3 = active and COLOR_ACCENT_D or COLOR_BG
        chip.TextColor3 = active and COLOR_TEXT or COLOR_TEXT_D
        local st = chip:FindFirstChildOfClass("UIStroke")
        if st then st.Color = active and COLOR_ACCENT or COLOR_LINE end
    end
    local function setMode(m)
        mode = (m == "AIMBOT") and "AIMBOT" or "TPBAT"
        paint(chipAim, mode == "AIMBOT")
        paint(chipTp, mode == "TPBAT")
    end
    setMode(mode)
    chipAim.MouseButton1Click:Connect(function() setMode("AIMBOT") end)
    chipTp.MouseButton1Click:Connect(function() setMode("TPBAT") end)
    Flags.afterDropMode = {get = function() return mode end, set = setMode}
end
currentPage = pages["MAIN"]


-- ================= COMBAT: TARGETING — Lock Enemy + Range (логика из MVP HUB) =================
currentPage = pages["COMBAT"]
do
    local RunService = game:GetService("RunService")
    local LP = player

    local lockEnabled = false
    local lockRange = 20
    local lockConn = nil

    local function getClosestTargetBody()
        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then return nil end
        local closest, minDist = nil, math.huge
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LP and plr.Character then
                local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                if tRoot and hum and hum.Health > 0 then
                    local d = (tRoot.Position - root.Position).Magnitude
                    if d < minDist then minDist = d; closest = tRoot end
                end
            end
        end
        return closest
    end

    local function lockTick()
        local char = LP.Character
        if not char then return end
        local root = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not root or not hum then return end
        local target = getClosestTargetBody()
        if not target or (target.Position - root.Position).Magnitude > lockRange then
            if not hum.AutoRotate then hum.AutoRotate = true end
            return
        end
        if hum.AutoRotate then hum.AutoRotate = false end
        local targetVel = target.AssemblyLinearVelocity
        local predictTime = math.clamp(targetVel.Magnitude / 80, 0.08, 0.35)
        local predictedPos = target.Position + targetVel * predictTime
        local targetHead = target.Parent and target.Parent:FindFirstChild("Head")
        local targetHeight = targetHead and targetHead.Position.Y or target.Position.Y
        local myHeight = root.Position.Y + (hum.HipHeight or 0)
        local vertical = math.clamp((targetHeight - myHeight) * 0.15, -1.5, 1.5)
        local flatTarget = Vector3.new(predictedPos.X, root.Position.Y + vertical, predictedPos.Z)
        if (flatTarget - root.Position).Magnitude > 0.1 then
            local goalCF = CFrame.lookAt(root.Position, flatTarget)
            local diffCF = root.CFrame:Inverse() * goalCF
            local _, ry, _ = diffCF:ToEulerAnglesXYZ()
            ry = math.clamp(ry, -2.5, 2.5)
            root.AssemblyAngularVelocity = root.CFrame:VectorToWorldSpace(Vector3.new(0, ry * 42, 0))
        end
    end

    local function startLock()
        if lockConn then lockConn:Disconnect() end
        local acc = 0
        lockConn = RunService.Heartbeat:Connect(function(dt)
            if not lockEnabled then return end
            acc = acc + dt
            if acc < 0.033 then return end
            acc = 0
            pcall(lockTick)
        end)
    end

    local function stopLock()
        if lockConn then lockConn:Disconnect(); lockConn = nil end
        local c = LP.Character
        local root = c and c:FindFirstChild("HumanoidRootPart")
        if root then
            root.AssemblyAngularVelocity = Vector3.zero
            root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, -0.1, root.AssemblyLinearVelocity.Z)
        end
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        if hum then hum.AutoRotate = true end
    end

    -- ---------- Панель ----------
    local panelT = Instance.new("Frame")
    panelT.Name = "TargetingPanel"
    panelT.Size = UDim2.new(1, 0, 0, 92)
    panelT.BackgroundColor3 = COLOR_PANEL
    panelT.BorderSizePixel = 0
    panelT.LayoutOrder = 5
    panelT.Parent = currentPage
    local ptc = Instance.new("UICorner", panelT)
    ptc.CornerRadius = UDim.new(0, 10)
    local pts = Instance.new("UIStroke", panelT)
    pts.Color = COLOR_ACCENT
    pts.Thickness = 1.5

    local titleT = Instance.new("TextLabel")
    titleT.BackgroundTransparency = 1
    titleT.Position = UDim2.new(0, 8, 0, 4)
    titleT.Size = UDim2.new(0, 100, 0, 16)
    titleT.Text = "TARGETING"
    titleT.Font = Enum.Font.GothamBold
    titleT.TextSize = 11
    titleT.TextColor3 = COLOR_BLUE
    titleT.TextXAlignment = Enum.TextXAlignment.Left
    titleT.Parent = panelT

    makeLabel(panelT, UDim2.new(0, 8, 0, 26), "Lock Enemy", UDim2.new(0, 100, 0, 18))
    local _, setLockVisual = makeToggle(panelT, UDim2.new(1, -44, 0, 26), false, function(v)
        lockEnabled = v
        if v then startLock() else stopLock() end
    end)
    Actions.LockEnemy = {
        get = function() return lockEnabled end,
        set = function(v)
            setLockVisual(v)
            lockEnabled = v
            if v then startLock() else stopLock() end
        end,
    }

    local lblRange = makeLabel(panelT, UDim2.new(0, 8, 0, 58), "Lock Enemy Range", UDim2.new(0, 100, 0, 18))
    lblRange.TextSize = 9
    local rangeBox = Instance.new("TextBox")
    rangeBox.Name = "LockRange"
    rangeBox.Size = UDim2.new(0, 36, 0, 22)
    rangeBox.Position = UDim2.new(1, -44, 0, 56)
    rangeBox.BackgroundColor3 = COLOR_BG
    rangeBox.Text = tostring(lockRange)
    rangeBox.Font = Enum.Font.GothamBold
    rangeBox.TextSize = 12
    rangeBox.TextColor3 = COLOR_TEXT
    rangeBox.TextXAlignment = Enum.TextXAlignment.Center
    rangeBox.ClearTextOnFocus = false
    rangeBox.Parent = panelT
    local rbc = Instance.new("UICorner", rangeBox)
    rbc.CornerRadius = UDim.new(0, 6)
    local rbs = Instance.new("UIStroke", rangeBox)
    rbs.Color = COLOR_ACCENT
    rbs.Thickness = 1.5
    rangeBox:GetPropertyChangedSignal("Text"):Connect(function()
        local t = rangeBox.Text:gsub("%D", "")
        if rangeBox.Text ~= t then rangeBox.Text = t end
    end)
    local function applyLockRange()
        local v = tonumber(rangeBox.Text)
        if v then
            lockRange = math.clamp(math.floor(v), 5, 200)
        end
        rangeBox.Text = tostring(lockRange)
    end
    rangeBox.FocusLost:Connect(applyLockRange)
    Flags.apply.LockRange = applyLockRange
end
currentPage = pages["MAIN"]

-- ================= MAIN: Carry / Lagger / TP Down + COMBAT: TP Bat (логика из MVP HUB) =================
do
    local RunService = game:GetService("RunService")
    local LP = player

    local function box(name)
        return Main:FindFirstChild(name, true)
    end
    local function boxNum(name, default)
        local b = box(name)
        local v = b and tonumber(b.Text)
        return (v and v > 0) and v or default
    end

    -- ---------- Скрытие скорости от игры (как в MVP HUB) ----------
    -- Игра сама читает скорость персонажа и, если она слишком большая, убирает брейнрот.
    -- Хук подменяет то, что видят её скрипты: любая скорость больше 20 выглядит как 20.
    -- Работает только если экзекьютор поддерживает getrawmetatable / newcclosure / checkcaller.
    local velHook = _G.__SpeexVelocityHook or {hooked = false, roots = setmetatable({}, {__mode = "k"})}
    _G.__SpeexVelocityHook = velHook
    local lastHookedRoot = nil

    local function hookVelocity(root)
        if not root then return end
        lastHookedRoot = root
        velHook.roots[root] = true
        if velHook.hooked then return end
        if type(getrawmetatable) ~= "function" or type(setreadonly) ~= "function"
            or type(newcclosure) ~= "function" or type(checkcaller) ~= "function" then return end
        pcall(function()
            local mt = getrawmetatable(root)
            if not mt then return end
            local oldIndex = rawget(mt, "__index")
            if type(oldIndex) ~= "function" and type(oldIndex) ~= "table" then return end
            local function original(obj, key)
                if type(oldIndex) == "function" then return oldIndex(obj, key) end
                return oldIndex[key]
            end
            setreadonly(mt, false)
            mt.__index = newcclosure(function(obj, key)
                if not checkcaller() and velHook.roots[obj]
                    and (key == "AssemblyLinearVelocity" or key == "Velocity") then
                    local real = original(obj, key)
                    if real and real.Magnitude > 20 then return real.Unit * 20 end
                    return real
                end
                return original(obj, key)
            end)
            setreadonly(mt, true)
            velHook.hooked = true
        end)
    end

    local function hookCharacter(char)
        if not char then return end
        local root = char:WaitForChild("HumanoidRootPart", 5)
        if root then hookVelocity(root) end
    end
    task.spawn(hookCharacter, LP.Character)
    LP.CharacterAdded:Connect(function(char) task.spawn(hookCharacter, char) end)

    -- ---------- Режимы скорости ----------
    -- normal -> Normal Speed (CUSTOM 1), carry -> Carry Speed (CUSTOM 1),
    -- lagger1 -> Larger Normal (CUSTOM 2), lagger2 -> Larger Carry (CUSTOM 2)
    local mode = "normal"
    local modeSetters = {}
    local tpBatEnabled = false

    local function activeSpeed()
        if mode == "lagger2" then return boxNum("LargerCarrySpeed", 80)
        elseif mode == "lagger1" then return boxNum("LargerNormalSpeed", 100)
        elseif mode == "carry" then return boxNum("CarrySpeed", 29)
        else return boxNum("NormalSpeed", 60) end
    end

    local function isBlocked(hum)
        if not hum or hum.Health <= 0 or hum.PlatformStand then return true end
        local st = hum:GetState()
        if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.FallingDown then return true end
        for _, n in ipairs({"AutoLeft", "AutoRight", "DropBR", "BatBypass", "BatAimbot"}) do
            local a = Actions[n]
            if a and a.get() then return true end
        end
        return tpBatEnabled
    end

    RunService.RenderStepped:Connect(function()
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root or isBlocked(hum) then return end
        if lastHookedRoot ~= root then hookVelocity(root) end
        local speed = activeSpeed()
        local dir = hum.MoveDirection
        local y = root.AssemblyLinearVelocity.Y
        if dir.Magnitude > 0.05 then
            pcall(function() root:SetNetworkOwner(LP) end)
            local u = dir.Unit
            root.AssemblyLinearVelocity = Vector3.new(u.X * speed, y, u.Z * speed)
        else
            root.AssemblyLinearVelocity = Vector3.new(0, y, 0)
        end
    end)

    local function setMode(newMode)
        mode = newMode
        for name, setter in pairs(modeSetters) do setter(mode == name) end
    end

    -- ---------- TP Down ----------
    local tpDownAt = 0
    local function doTpDown()
        tpDownAt = tick()
        pcall(function()
            local char = LP.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not root then return end
            local _, yaw = root.CFrame:ToEulerAnglesYXZ()
            root.CFrame = CFrame.new(root.Position.X, -7, root.Position.Z) * CFrame.Angles(0, yaw, 0)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    end

    -- ---------- TP Bat (перенесено из хаба Visible) ----------
    -- Телепорт к ближайшему врагу через смену Network Owner + авто-удар битой.
    local TP = {
        thread = nil, ragdollConn = nil, charConn = nil, hittingCooldown = false,
        autoBat = true, autoBatDelay = 0.08, cameraLock = true,
        range = 850, loopDelay = 0.018,
    }

    local function myRoot()
        local c = LP.Character
        return c and c:FindFirstChild("HumanoidRootPart")
    end
    local function myHum()
        local c = LP.Character
        return c and c:FindFirstChildOfClass("Humanoid")
    end

    local function recoverFromRagdoll()
        local hum = myHum()
        if not hum then return end
        pcall(function()
            hum.PlatformStand = false
            hum.Sit = false
            hum.AutoRotate = true
            local st = hum:GetState()
            if st == Enum.HumanoidStateType.Physics
                or st == Enum.HumanoidStateType.Ragdoll
                or st == Enum.HumanoidStateType.FallingDown
                or st == Enum.HumanoidStateType.PlatformStanding then
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                hum:ChangeState(Enum.HumanoidStateType.Running)
            end
        end)
    end

    local function isRagdolled()
        local hum = myHum()
        if not hum then return false end
        if hum.PlatformStand or hum.Sit then return true end
        local st = hum:GetState()
        return st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.FallingDown
            or st == Enum.HumanoidStateType.GettingUp
            or st == Enum.HumanoidStateType.PlatformStanding
    end

    local function isBatTool(tool)
        if not tool or not tool:IsA("Tool") then return false end
        local n = string.lower(tool.Name)
        return string.find(n, "bat", 1, true) ~= nil or string.find(n, "slap", 1, true) ~= nil
    end

    local function getBat()
        local char = LP.Character
        if not char then return nil end
        for _, child in ipairs(char:GetChildren()) do
            if isBatTool(child) then return child end
        end
        local pack = LP:FindFirstChild("Backpack")
        if pack then
            for _, child in ipairs(pack:GetChildren()) do
                if isBatTool(child) then
                    pcall(function()
                        local hum = char:FindFirstChildOfClass("Humanoid")
                        if hum then hum:EquipTool(child) else child.Parent = char end
                    end)
                    return child
                end
            end
        end
        return char:FindFirstChild("Bat")
    end

    local function forceHitBat(targetRoot)
        recoverFromRagdoll()
        pcall(function()
            local bat = getBat()
            if not bat then return end
            pcall(function() bat:Activate() end)
            if targetRoot and typeof(firetouchinterest) == "function" then
                local handle = bat:FindFirstChild("Handle")
                if handle then
                    pcall(function()
                        firetouchinterest(handle, targetRoot, 0)
                        firetouchinterest(handle, targetRoot, 1)
                    end)
                    local torso = targetRoot.Parent and (
                        targetRoot.Parent:FindFirstChild("UpperTorso")
                        or targetRoot.Parent:FindFirstChild("Torso")
                        or targetRoot.Parent:FindFirstChild("Head")
                    )
                    if torso then
                        pcall(function()
                            firetouchinterest(handle, torso, 0)
                            firetouchinterest(handle, torso, 1)
                        end)
                    end
                end
            end
            for _, ev in ipairs(bat:GetDescendants()) do
                if ev:IsA("RemoteEvent") then
                    pcall(function() ev:FireServer() end)
                end
            end
        end)
    end

    local function tryHitBat(targetRoot)
        recoverFromRagdoll()
        local rag = isRagdolled()
        if TP.hittingCooldown and not rag then return end
        if not rag then TP.hittingCooldown = true end
        forceHitBat(targetRoot)
        if not rag then
            task.delay(TP.autoBatDelay, function() TP.hittingCooldown = false end)
        end
    end

    local function findNearestEnemy()
        local me = myRoot()
        if not me then return nil end
        local best, bestPlr, bestD = nil, nil, TP.range
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LP and plr.Character then
                local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                local root = plr.Character:FindFirstChild("HumanoidRootPart")
                if hum and hum.Health > 0 and root then
                    local d = (root.Position - me.Position).Magnitude
                    if d < bestD then bestD, best, bestPlr = d, root, plr end
                end
            end
        end
        return best, bestPlr
    end

    local function applyCamLock(pos)
        if not TP.cameraLock then return end
        pcall(function()
            local cam = workspace.CurrentCamera
            if cam and typeof(pos) == "Vector3" then
                cam.CFrame = CFrame.new(cam.CFrame.Position, pos)
            end
        end)
    end

    local function teleportTo(targetRoot)
        local me = myRoot()
        local hum = myHum()
        if not me or not targetRoot then return end
        pcall(function()
            if me.SetNetworkOwner then me:SetNetworkOwner(nil) end
        end)
        task.wait()
        local targetPosition = targetRoot.Position + Vector3.new(0, 0.9, 0)
        me.CFrame = CFrame.new(targetPosition)
        me.AssemblyLinearVelocity = targetRoot.AssemblyLinearVelocity
        pcall(function()
            if me.SetNetworkOwner then me:SetNetworkOwner(LP) end
        end)
        if hum then
            hum.PlatformStand = false
            hum.Sit = false
        end
        applyCamLock(targetRoot.Position)
    end

    local function stopLoops()
        if TP.thread then pcall(function() task.cancel(TP.thread) end); TP.thread = nil end
        if TP.ragdollConn then pcall(function() TP.ragdollConn:Disconnect() end); TP.ragdollConn = nil end
    end

    local function stopTpBat()
        tpBatEnabled = false
        stopLoops()
        if TP.charConn then pcall(function() TP.charConn:Disconnect() end); TP.charConn = nil end
        TP.hittingCooldown = false
    end

    local function startLoops()
        stopLoops()
        TP.thread = task.spawn(function()
            while tpBatEnabled do
                local target = findNearestEnemy()
                if target then
                    recoverFromRagdoll()
                    teleportTo(target)
                    if TP.autoBat then tryHitBat(target) end
                end
                local delayTime = TP.loopDelay
                if isRagdolled() then delayTime = 0.03 end
                task.wait(delayTime)
            end
        end)
        TP.ragdollConn = RunService.Heartbeat:Connect(function()
            if not tpBatEnabled then return end
            if not isRagdolled() then return end
            recoverFromRagdoll()
            local target = findNearestEnemy()
            if target then
                teleportTo(target)
                if TP.autoBat then forceHitBat(target) end
            end
        end)
    end

    local function startTpBat()
        stopTpBat()
        tpBatEnabled = true
        startLoops()
        -- после респавна перезапускаем циклы
        TP.charConn = LP.CharacterAdded:Connect(function()
            if not tpBatEnabled then return end
            stopLoops()
            task.wait(0.5)
            if tpBatEnabled then startLoops() end
        end)
    end

    -- ---------- Панель MODES (MAIN) ----------
    local function newPanel(page, name, title, height, order)
        local p = Instance.new("Frame")
        p.Name = name
        p.Size = UDim2.new(1, 0, 0, height)
        p.BackgroundColor3 = COLOR_PANEL
        p.BorderSizePixel = 0
        p.LayoutOrder = order
        p.Parent = page
        local c = Instance.new("UICorner", p)
        c.CornerRadius = UDim.new(0, 10)
        local s = Instance.new("UIStroke", p)
        s.Color = COLOR_ACCENT
        s.Thickness = 1.5
        local t = Instance.new("TextLabel")
        t.BackgroundTransparency = 1
        t.Position = UDim2.new(0, 8, 0, 4)
        t.Size = UDim2.new(0, 100, 0, 16)
        t.Text = title
        t.Font = Enum.Font.GothamBold
        t.TextSize = 11
        t.TextColor3 = COLOR_BLUE
        t.TextXAlignment = Enum.TextXAlignment.Left
        t.Parent = p
        return p
    end

    local pm = newPanel(pages["MAIN"], "ModesPanel", "MODES", 186, 5)

    local function modeRow(y, label, key)
        makeLabel(pm, UDim2.new(0, 8, 0, y), label, UDim2.new(0, 100, 0, 18))
        local _, setter = makeToggle(pm, UDim2.new(1, -44, 0, y), false, function(v)
            setMode(v and key or "normal")
        end)
        modeSetters[key] = setter
        Actions[({carry = "Carry", lagger1 = "Lagger1", lagger2 = "Lagger2"})[key]] = {
            get = function() return mode == key end,
            set = function(v) setMode(v and key or "normal") end,
        }
    end
    modeRow(26, "Carry Speed", "carry")
    modeRow(58, "Lagger Normal", "lagger1")
    modeRow(90, "Lagger Carry", "lagger2")

    makeLabel(pm, UDim2.new(0, 8, 0, 122), "TP Down", UDim2.new(0, 100, 0, 18))
    local _, setTpDown = makeToggle(pm, UDim2.new(1, -44, 0, 122), false, function(v)
        if v then
            doTpDown()
            task.delay(0.2, function() setTpDown(false) end)
        end
    end)
    Actions.TpDown = {
        get = function() return tick() - tpDownAt < 0.2 end,
        set = function(v)
            if v then
                setTpDown(true)
                doTpDown()
                task.delay(0.2, function() setTpDown(false) end)
            end
        end,
    }

    -- ---------- Auto TP Down ----------
    -- Если ты несёшь предмет и поднялся выше AUTO_TPDOWN_HEIGHT студов над землёй,
    -- автоматически вызывается обычный TP Down (с кулдауном).
    local AUTO_TPDOWN_HEIGHT = 20      -- <<< порог высоты в студах
    local AUTO_TPDOWN_COOLDOWN = 0.5   -- пауза между срабатываниями
    local autoTpDownOn, autoTpDownConn, autoTpDownLast = false, nil, 0

    local function isCarryingItem(char)
        if not char then return false end
        if LP:GetAttribute("Stealing") == true or char:GetAttribute("Stealing") == true then return true end
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") then
                local n = child.Name:lower()
                if not (n:find("bat") or n:find("slap") or n:find("medusa")) then return true end
            end
        end
        return false
    end

    local function setAutoTpDown(on)
        autoTpDownOn = on == true
        if autoTpDownConn then autoTpDownConn:Disconnect(); autoTpDownConn = nil end
        if not autoTpDownOn then return end
        autoTpDownConn = RunService.Heartbeat:Connect(function()
            if tick() - autoTpDownLast < AUTO_TPDOWN_COOLDOWN then return end
            local char = LP.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not root or not isCarryingItem(char) then return end
            local rp = RaycastParams.new()
            rp.FilterDescendantsInstances = {char}
            rp.FilterType = Enum.RaycastFilterType.Exclude
            local hit = workspace:Raycast(root.Position, Vector3.new(0, -2000, 0), rp)
            if hit and root.Position.Y - hit.Position.Y > AUTO_TPDOWN_HEIGHT then
                autoTpDownLast = tick()
                doTpDown()
            end
        end)
    end

    makeLabel(pm, UDim2.new(0, 8, 0, 154), "Auto TP Down", UDim2.new(0, 100, 0, 18))
    local _, setAutoTpDownVisual = makeToggle(pm, UDim2.new(1, -44, 0, 154), false, function(v)
        setAutoTpDown(v)
    end)
    Actions.AutoTpDown = {
        get = function() return autoTpDownOn end,
        set = function(v)
            setAutoTpDown(v)
            setAutoTpDownVisual(v)
        end,
    }

    -- ---------- Панель TP BAT (COMBAT) ----------
    local pt = newPanel(pages["COMBAT"], "TpBatPanel", "TP BAT", 92, 5)
    makeLabel(pt, UDim2.new(0, 8, 0, 26), "TP Bat", UDim2.new(0, 100, 0, 18))
    local _, setTpBat = makeToggle(pt, UDim2.new(1, -44, 0, 26), false, function(v)
        if v then startTpBat() else stopTpBat() end
    end)

    -- TP Camera Lock (как в меню Visible): камера смотрит на цель при телепорте, по умолчанию включено
    makeLabel(pt, UDim2.new(0, 8, 0, 58), "TP Camera Lock", UDim2.new(0, 130, 0, 18))
    local _, setCamLockVisual = makeToggle(pt, UDim2.new(1, -44, 0, 58), TP.cameraLock, function(v)
        TP.cameraLock = v
    end)
    Flags.tpCamLock = {get = function() return TP.cameraLock end,
        set = function(v) TP.cameraLock = v == true; setCamLockVisual(TP.cameraLock) end}
    Actions.BatV2 = {
        get = function() return tpBatEnabled end,
        set = function(v)
            setTpBat(v)
            if v then startTpBat() else stopTpBat() end
        end,
    }
end

-- ================= VISUALS: INSTANT RESET (мгновенный ресет персонажа, без GUI-анимации) =================
currentPage = pages["VISUALS"]
do
    local RunService = game:GetService("RunService")
    local Player = player
    local CAM_BIND = "SpeexResetCam"

    local FLING_TIME = 0.4
    local FLING_POWER = 50000
    local USE_VOID = true
    local VOID_TIME = 0.6
    local TIMEOUT = 6
    local resetting = false
    local setResetVisual = function() end   -- заполняется после создания тумблера

    local function hide_locally(obj)
        if obj:IsA("BasePart") or obj:IsA("Decal") then
            obj.LocalTransparencyModifier = 1
        end
    end

    local function insta_reset()
        if resetting then return end
        local char = Player.Character
        if not char or not char.Parent then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end
        local hrp = hum.RootPart or char:FindFirstChild("HumanoidRootPart")
        resetting = true

        task.spawn(function()
            local cam = workspace.CurrentCamera
            local frozen = cam.CFrame
            local old_type = cam.CameraType
            pcall(function()
                cam.CameraType = Enum.CameraType.Scriptable
                RunService:BindToRenderStep(CAM_BIND, Enum.RenderPriority.Camera.Value + 1, function()
                    cam.CFrame = frozen
                end)
            end)

            local added
            pcall(function()
                for _, obj in ipairs(char:GetDescendants()) do pcall(hide_locally, obj) end
                added = char.DescendantAdded:Connect(function(obj) pcall(hide_locally, obj) end)
            end)

            local new_char
            local respawned = Player.CharacterAdded:Connect(function(c) new_char = c end)

            local function unlock()
                pcall(function() hum.PlatformStand = false end)
                pcall(function() hum.Sit = false end)
                pcall(function() hum.AutoRotate = true end)
            end
            unlock()

            for _, obj in ipairs(char:GetDescendants()) do
                if obj:IsA("BasePart") then
                    pcall(function() obj.Anchored = false end)
                    pcall(function() obj.CanCollide = false end)
                elseif obj.Name == "SeatWeld" then
                    pcall(function() obj:Destroy() end)
                end
            end

            local started = os.clock()
            local function alive_hrp()
                if hrp and hrp.Parent then return hrp end
                hrp = hum.RootPart or char:FindFirstChild("HumanoidRootPart")
                if hrp and hrp.Parent then return hrp end
                return nil
            end

            local fling_until = os.clock() + FLING_TIME
            while not new_char and os.clock() < fling_until and hum.Parent do
                unlock()
                pcall(function() hum.HipHeight = 1e30 end)
                local root = alive_hrp()
                if root then
                    pcall(function() root.Anchored = false end)
                    pcall(function() root.AssemblyLinearVelocity = Vector3.new(0, FLING_POWER, 0) end)
                    pcall(function() root.Velocity = Vector3.new(0, FLING_POWER, 0) end)
                end
                RunService.Heartbeat:Wait()
            end

            if USE_VOID and not new_char then
                local floor = -500
                pcall(function() floor = workspace.FallenPartsDestroyHeight end)
                local void_until = os.clock() + VOID_TIME
                while not new_char and os.clock() < void_until do
                    local root = alive_hrp()
                    if not root then break end
                    pcall(function() root.CFrame = CFrame.new(0, floor - 500, 0) end)
                    pcall(function() root.AssemblyLinearVelocity = Vector3.new(0, -FLING_POWER, 0) end)
                    RunService.Heartbeat:Wait()
                end
            end

            while not new_char and os.clock() - started < TIMEOUT do
                if hum.Parent then
                    pcall(function() hum.Health = 0 end)
                    pcall(function() hum:ChangeState(Enum.HumanoidStateType.Dead) end)
                end
                if char.Parent then pcall(function() char:BreakJoints() end) end
                task.wait(0.1)
            end

            pcall(function() respawned:Disconnect() end)
            if added then pcall(function() added:Disconnect() end) end
            pcall(function() RunService:UnbindFromRenderStep(CAM_BIND) end)
            pcall(function()
                cam.CameraType = old_type == Enum.CameraType.Scriptable and Enum.CameraType.Custom or old_type
                if new_char then
                    local new_hum = new_char:FindFirstChildOfClass("Humanoid")
                        or new_char:WaitForChild("Humanoid", 5)
                    if new_hum then cam.CameraSubject = new_hum end
                end
            end)
            resetting = false
            setResetVisual(false)
        end)
    end

    local function trigger()
        setResetVisual(true)
        insta_reset()
        if not resetting then setResetVisual(false) end   -- ресет не стартовал (нет персонажа / уже мёртв)
    end

    -- ---------- Панель ----------
    local panelR = Instance.new("Frame")
    panelR.Name = "InstaResetPanel"
    panelR.Size = UDim2.new(1, 0, 0, 56)
    panelR.BackgroundColor3 = COLOR_PANEL
    panelR.BorderSizePixel = 0
    panelR.LayoutOrder = 6
    panelR.Parent = currentPage
    local pcR = Instance.new("UICorner", panelR)
    pcR.CornerRadius = UDim.new(0, 10)
    local psR = Instance.new("UIStroke", panelR)
    psR.Color = COLOR_ACCENT
    psR.Thickness = 1.5

    local titleR = Instance.new("TextLabel")
    titleR.BackgroundTransparency = 1
    titleR.Position = UDim2.new(0, 8, 0, 4)
    titleR.Size = UDim2.new(0, 120, 0, 16)
    titleR.Text = "INSTANT RESET"
    titleR.Font = Enum.Font.GothamBold
    titleR.TextSize = 11
    titleR.TextColor3 = COLOR_BLUE
    titleR.TextXAlignment = Enum.TextXAlignment.Left
    titleR.Parent = panelR

    makeLabel(panelR, UDim2.new(0, 8, 0, 26), "Insta Reset", UDim2.new(0, 100, 0, 18))
    local _, setter = makeToggle(panelR, UDim2.new(1, -44, 0, 26), false, function(v)
        if v then trigger() end
    end)
    setResetVisual = setter

    -- действие для мобильной кнопки RESET и клавиши (одноразовое, как Drop BR / TP Down)
    Actions.InstaReset = {
        get = function() return resetting end,
        set = function(v) if v then trigger() end end,
    }
end

-- ================= VISUALS: HIDE HORN — делает чёрный «рог» на чужой базе прозрачным =================
currentPage = pages["VISUALS"]
do
    local UIS = game:GetService("UserInputService")
    local RunService = game:GetService("RunService")
    local ALPHA = 0.85          -- 0 = как есть, 1 = полностью невидим
    local hOn = false
    local picking = false
    local sig = nil             -- подпись выбранной детали {color, material, parentName}
    local touched = {}          -- что уже спрятали (чтобы вернуть при выключении)
    local conn, addConn = nil, nil

    local function isMyPlot(plot)
        local sign = plot:FindFirstChild("PlotSign")
        local yb = sign and sign:FindFirstChild("YourBase")
        return yb and yb:IsA("BillboardGui") and yb.Enabled == true
    end

    local function nearBlack(c) return c.R < 0.12 and c.G < 0.12 and c.B < 0.12 end

    local function matches(part)
        if not part:IsA("BasePart") then return false end
        if sig then
            local c = part.Color
            return math.abs(c.R - sig.color.R) < 0.05 and math.abs(c.G - sig.color.G) < 0.05
                and math.abs(c.B - sig.color.B) < 0.05
                and part.Material == sig.material
                and (part.Parent and part.Parent.Name == sig.parentName)
        end
        -- без выбора: крупные чёрные детали на чужих базах
        local sz = part.Size
        return nearBlack(part.Color) and math.max(sz.X, sz.Y, sz.Z) >= 8
    end

    local function hide(part)
        if not touched[part] then touched[part] = true end
        part.LocalTransparencyModifier = ALPHA
    end

    local function scan()
        local plots = workspace:FindFirstChild("Plots")
        if not plots then return end
        for _, plot in ipairs(plots:GetChildren()) do
            if plot:IsA("Model") and not isMyPlot(plot) then
                for _, d in ipairs(plot:GetDescendants()) do
                    if matches(d) then hide(d) end
                end
            end
        end
    end

    local function restore()
        for part in pairs(touched) do
            pcall(function() part.LocalTransparencyModifier = 0 end)
        end
        touched = {}
    end

    local function setHorn(v)
        hOn = v
        if conn then conn:Disconnect(); conn = nil end
        if addConn then addConn:Disconnect(); addConn = nil end
        if v then
            pcall(scan)
            -- держим прозрачность всегда: когда база появляется / подгружается / ты заходишь рядом
            local acc = 0
            conn = RunService.Heartbeat:Connect(function(dt)
                acc += dt
                if acc >= 0.5 then acc = 0; pcall(scan) end
            end)
            local plots = workspace:FindFirstChild("Plots")
            if plots then
                addConn = plots.DescendantAdded:Connect(function(d)
                    task.defer(function()
                        if hOn and d:IsA("BasePart") and matches(d) then
                            local plot = d:FindFirstAncestorOfClass("Model")
                            while plot and plot.Parent ~= plots do plot = plot.Parent end
                            if plot and not isMyPlot(plot) then hide(d) end
                        end
                    end)
                end)
            end
        else
            restore()
        end
    end

    -- выбор рога: нажми PICK, потом тапни по чёрному рогу на экране
    UIS.InputBegan:Connect(function(input, gp)
        if not picking then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local cam = workspace.CurrentCamera
        local pos = input.Position
        local ray = cam:ViewportPointToRay(pos.X, pos.Y)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { player.Character }
        local res = workspace:Raycast(ray.Origin, ray.Direction * 500, params)
        if res and res.Instance and res.Instance:IsA("BasePart") then
            picking = false
            local p = res.Instance
            sig = { color = p.Color, material = p.Material, parentName = p.Parent and p.Parent.Name or "" }
            restore()
            if hOn then pcall(scan) end
            print("[Hide Horn] выбран:", p:GetFullName())
        end
    end)

    -- ---------- Панель ----------
    local panelH = Instance.new("Frame")
    panelH.Name = "HideHornPanel"
    panelH.Size = UDim2.new(1, 0, 0, 84)
    panelH.BackgroundColor3 = COLOR_PANEL
    panelH.BorderSizePixel = 0
    panelH.LayoutOrder = 7
    panelH.Parent = currentPage
    Instance.new("UICorner", panelH).CornerRadius = UDim.new(0, 10)
    local psH = Instance.new("UIStroke", panelH)
    psH.Color = COLOR_ACCENT
    psH.Thickness = 1.5

    local titleH = Instance.new("TextLabel")
    titleH.BackgroundTransparency = 1
    titleH.Position = UDim2.new(0, 8, 0, 4)
    titleH.Size = UDim2.new(0, 140, 0, 16)
    titleH.Text = "HIDE HORN"
    titleH.Font = Enum.Font.GothamBold
    titleH.TextSize = 11
    titleH.TextColor3 = COLOR_BLUE
    titleH.TextXAlignment = Enum.TextXAlignment.Left
    titleH.Parent = panelH

    makeLabel(panelH, UDim2.new(0, 8, 0, 26), "Horn Transparent", UDim2.new(0, 120, 0, 18))
    local _, setHornVisual = makeToggle(panelH, UDim2.new(1, -44, 0, 26), false, function(v) setHorn(v) end)

    local pick = makeChip(panelH, UDim2.new(0, 8, 0, 54), UDim2.new(0, 90, 0, 22), "PICK HORN", false)
    pick.TextSize = 9
    pick.MouseButton1Click:Connect(function()
        picking = true
        pick.Text = "TAP HORN..."
        task.delay(8, function() if picking then picking = false end pick.Text = "PICK HORN" end)
    end)
    local clr = makeChip(panelH, UDim2.new(0, 104, 0, 54), UDim2.new(0, 70, 0, 22), "RESET", false)
    clr.TextSize = 9
    clr.MouseButton1Click:Connect(function()
        sig = nil; restore()
        if hOn then pcall(scan) end
    end)

    Actions.HideHorn = {
        get = function() return hOn end,
        set = function(v) setHorn(v); setHornVisual(v) end,
    }
end
currentPage = pages["MAIN"]

-- ================= VISUALS: RAINBOW TRAIL — радужный след при беге =================
currentPage = pages["VISUALS"]
do
    local RunService = game:GetService("RunService")
    local trOn = false
    local trailObjs = {}
    local stepConn = nil
    local charConn = nil

    local function clearTrail()
        if stepConn then stepConn:Disconnect() stepConn = nil end
        for _, o in ipairs(trailObjs) do
            pcall(function() o:Destroy() end)
        end
        table.clear(trailObjs)
    end

    local function attachTrail(char)
        clearTrail()
        if not trOn or not char then return end
        local root = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not root or not hum then return end

        local a0 = Instance.new("Attachment")
        a0.Name = "SpeexTrailA0"
        a0.Position = Vector3.new(-0.35, -2.4, 0)
        a0.Parent = root
        local a1 = Instance.new("Attachment")
        a1.Name = "SpeexTrailA1"
        a1.Position = Vector3.new(0.35, -2.4, 0)
        a1.Parent = root

        local trail = Instance.new("Trail")
        trail.Name = "SpeexRainbowTrail"
        trail.Attachment0 = a0
        trail.Attachment1 = a1
        trail.Lifetime = 0.55
        trail.MinLength = 0.12
        trail.LightEmission = 1
        trail.LightInfluence = 0
        trail.WidthScale = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(1, 0),
        })
        trail.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.05),
            NumberSequenceKeypoint.new(1, 1),
        })
        trail.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 60, 60)),
            ColorSequenceKeypoint.new(0.2, Color3.fromRGB(255, 180, 40)),
            ColorSequenceKeypoint.new(0.4, Color3.fromRGB(60, 255, 90)),
            ColorSequenceKeypoint.new(0.6, Color3.fromRGB(50, 180, 255)),
            ColorSequenceKeypoint.new(0.8, Color3.fromRGB(160, 70, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 60, 200)),
        })
        trail.Enabled = false
        trail.Parent = root

        table.insert(trailObjs, trail)
        table.insert(trailObjs, a0)
        table.insert(trailObjs, a1)

        local hue = 0
        stepConn = RunService.Heartbeat:Connect(function(dt)
            if not trOn or not root.Parent then return end
            local spd = root.AssemblyLinearVelocity.Magnitude
            local moving = spd > 6 or hum.MoveDirection.Magnitude > 0.08
            trail.Enabled = moving
            hue = (hue + dt * 0.7) % 1
            local c1 = Color3.fromHSV(hue, 0.95, 1)
            local c2 = Color3.fromHSV((hue + 0.33) % 1, 0.95, 1)
            local c3 = Color3.fromHSV((hue + 0.66) % 1, 0.95, 1)
            trail.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, c1),
                ColorSequenceKeypoint.new(0.5, c2),
                ColorSequenceKeypoint.new(1, c3),
            })
        end)
    end

    local function setTrail(on)
        trOn = on == true
        if not trOn then
            clearTrail()
            return
        end
        if player.Character then attachTrail(player.Character) end
    end

    charConn = player.CharacterAdded:Connect(function(char)
        task.wait(0.3)
        if trOn then attachTrail(char) end
    end)

    local panel = Instance.new("Frame")
    panel.Name = "RainbowTrailPanel"
    panel.Size = UDim2.new(1, 0, 0, 52)
    panel.BackgroundColor3 = COLOR_PANEL
    panel.BorderSizePixel = 0
    panel.LayoutOrder = 9
    panel.Parent = currentPage
    Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 10)
    Instance.new("UIStroke", panel).Color = COLOR_ACCENT

    local title = Instance.new("TextLabel")
    title.BackgroundTransparency = 1
    title.Position = UDim2.new(0, 8, 0, 4)
    title.Size = UDim2.new(0, 140, 0, 14)
    title.Text = "RAINBOW TRAIL"
    title.Font = Enum.Font.GothamBold
    title.TextSize = 11
    title.TextColor3 = COLOR_BLUE
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = panel

    makeLabel(panel, UDim2.new(0, 8, 0, 24), "Rainbow Trail", UDim2.new(0, 110, 0, 18))
    local _, vis = makeToggle(panel, UDim2.new(1, -44, 0, 24), false, function(v)
        setTrail(v)
    end)

    Actions.RainbowTrail = {
        get = function() return trOn end,
        set = function(v) vis(v == true) setTrail(v) end,
    }
end
currentPage = pages["MAIN"]

-- ================= VISUALS: Lock UI / Hide Button / Lock Mobile Buttons (логика из MVP HUB) =================
-- Мобильные кнопки (как в MVP): плавающие кнопки для Drop BR, Auto Left, Auto Right
currentPage = pages["VISUALS"]
do
    local RunService = game:GetService("RunService")
    local TweenService = game:GetService("TweenService")

    local BTN = 60
    local buttonDefs = {
        {name = "DropBR",   text = "DROP\nBR"},
        {name = "AutoLeft", text = "AUTO\nLEFT"},
        {name = "AutoRight", text = "AUTO\nRIGHT"},
        {name = "TpDown",   text = "TP\nDOWN"},
        {name = "Carry",    text = "CARRY\nSPD"},
        {name = "Lagger1",  text = "LAGGER\nNORMAL"},
        {name = "Lagger2",  text = "LAGGER\nCARRY"},
        {name = "BatV2",    text = "TP\nBAT"},
        {name = "InstaReset", text = "INSTA\nRESET"},
        {name = "BatBypass", text = "BAT\nBYPASS"},
        {name = "BatAimbot", text = "BAT\nAIMBOT"},
    }

    local MobileGui = Instance.new("ScreenGui")
    MobileGui.Name = "SpeexMobilePanel"
    MobileGui.ResetOnSpawn = false
    MobileGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    MobileGui.IgnoreGuiInset = true
    MobileGui.DisplayOrder = 40
    MobileGui.Parent = player:WaitForChild("PlayerGui")

    local mobileButtons = {}
    local hideButtons = false

    local function viewport()
        local cam = workspace.CurrentCamera
        return cam and cam.ViewportSize or Vector2.new(800, 600)
    end

    Flags.buttonScale = 1
    local function clampPos(x, y)
        local vp = viewport()
        local size = BTN * Flags.buttonScale
        return math.clamp(x, 6, math.max(6, vp.X - size - 6)),
               math.clamp(y, 6, math.max(6, vp.Y - size - 6))
    end

    -- снежинки в углах кнопок (unicode, чисто)
    local function addSnow(btn, bottomRight)
        local box = Instance.new("Frame")
        box.BackgroundTransparency = 1
        box.BorderSizePixel = 0
        box.Size = UDim2.fromOffset(22, 22)
        box.ZIndex = 12
        if bottomRight then
            box.AnchorPoint = Vector2.new(1, 1)
            box.Position = UDim2.new(1, -2, 1, -2)
        else
            box.Position = UDim2.fromOffset(2, 2)
        end
        box.Parent = btn

        local flakes = {}
        local marks = bottomRight and {"❄", "❅"} or {"❅", "❄"}
        for i, ch in ipairs(marks) do
            local l = Instance.new("TextLabel")
            l.BackgroundTransparency = 1
            l.Size = UDim2.fromOffset(14, 14)
            l.Position = UDim2.fromOffset((i - 1) * 6, (i - 1) * 5)
            l.Font = Enum.Font.GothamBold
            l.TextSize = i == 1 and 13 or 10
            l.Text = ch
            l.TextColor3 = Color3.fromRGB(210, 235, 255)
            l.TextTransparency = 0.05
            l.TextStrokeTransparency = 0.55
            l.TextStrokeColor3 = Color3.fromRGB(120, 180, 230)
            l.ZIndex = 13
            l.Parent = box
            flakes[#flakes + 1] = l
        end
        return flakes
    end

    local function paintBtn(entry, active)
        local snowColor = active and Color3.fromRGB(240, 250, 255) or Color3.fromRGB(170, 210, 245)
        for _, l in ipairs(entry.web) do
            if l:IsA("TextLabel") then
                l.TextColor3 = snowColor
                l.TextTransparency = active and 0 or 0.12
            end
        end
        local fillColor = active and COLOR_BLUE or COLOR_BG
        entry.btn.BackgroundColor3 = fillColor
        entry.label.TextColor3 = active and Color3.new(1, 1, 1) or COLOR_TEXT
        entry.status.Text = active and "ON" or "OFF"
        entry.status.TextColor3 = active and Color3.fromRGB(200, 235, 255) or COLOR_TEXT_D
        if entry.stroke then
            entry.stroke.Color = active and Color3.fromRGB(180, 230, 255) or COLOR_ACCENT
            entry.stroke.Thickness = active and 2 or 1.5
        end
    end

    for i, def in ipairs(buttonDefs) do
        local btn = Instance.new("TextButton")
        btn.Name = def.name
        btn.Size = UDim2.fromOffset(BTN, BTN)
        local vp = viewport()
        local perCol = math.max(1, math.floor((vp.Y - 90) / (BTN + 8)))
        local col = math.floor((i - 1) / perCol)
        local row = (i - 1) % perCol
        local x, y = clampPos(vp.X - BTN - 16 - col * (BTN + 8), 90 + row * (BTN + 8))
        btn.Position = UDim2.fromOffset(x, y)
        btn.BackgroundColor3 = COLOR_BG
        btn.BorderSizePixel = 0
        btn.Text = ""
        btn.AutoButtonColor = false
        btn.Active = true
        btn.ZIndex = 10
        btn.ClipsDescendants = true
        btn.Parent = MobileGui
        local bc = Instance.new("UICorner", btn)
        bc.CornerRadius = UDim.new(0, 11)
        local bs = Instance.new("UIStroke", btn)
        bs.Color = COLOR_BLUE
        bs.Thickness = 1.5
        local btnScale = Instance.new("UIScale", btn)
        btnScale.Scale = Flags.buttonScale

        local label = Instance.new("TextLabel")
        label.BackgroundTransparency = 1
        label.Position = UDim2.fromOffset(4, 19)
        label.Size = UDim2.new(1, -8, 0, 32)
        label.Text = def.text
        label.Font = Enum.Font.GothamBold
        label.TextSize = 10
        label.TextWrapped = true
        label.TextColor3 = COLOR_TEXT
        label.ZIndex = 11
        label.Parent = btn

        local status = Instance.new("TextLabel")
        status.BackgroundTransparency = 1
        status.Position = UDim2.fromOffset(4, 46)
        status.Size = UDim2.new(1, -8, 0, 10)
        status.Text = "OFF"
        status.Font = Enum.Font.GothamBold
        status.TextSize = 8
        status.TextColor3 = COLOR_TEXT_D
        status.ZIndex = 11
        status.Parent = btn


        local web = addSnow(btn, false)
        for _, l in ipairs(addSnow(btn, true)) do web[#web + 1] = l end

        local entry = {btn = btn, label = label, status = status, name = def.name, scale = btnScale, web = web, stroke = bs}
        mobileButtons[#mobileButtons + 1] = entry

        -- перетаскивание + нажатие
        local pointer, dragStart, origin, moved = nil, nil, nil, 0
        btn.InputBegan:Connect(function(input)
            if pointer then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            pointer, dragStart, origin, moved = input, input.Position, btn.Position, 0
        end)
        UserInputService.InputChanged:Connect(function(input)
            if not pointer then return end
            if pointer.UserInputType == Enum.UserInputType.Touch then
                if input ~= pointer then return end
            elseif input.UserInputType ~= Enum.UserInputType.MouseMovement then
                return
            end
            local delta = input.Position - dragStart
            moved = math.max(moved, delta.Magnitude)
            if moved >= 8 and not Flags.uiLocked and not Flags.buttonsLocked then
                local nx, ny = clampPos(origin.X.Offset + delta.X, origin.Y.Offset + delta.Y)
                btn.Position = UDim2.fromOffset(nx, ny)
            end
        end)
        UserInputService.InputEnded:Connect(function(input)
            if not pointer then return end
            if pointer.UserInputType == Enum.UserInputType.Touch and input ~= pointer then return end
            if pointer.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
            local wasClick = moved < 8
            pointer = nil
            if wasClick then
                local act = Actions[def.name]
                if act then
                    local ok, err = pcall(function() act.set(not act.get()) end)
                    if not ok then warn("[Speex Button] " .. def.name .. ": " .. tostring(err)) end
                end
            end
        end)
    end

    -- кнопки показывают реальное состояние функций (в том числе когда они выключились сами)
    RunService.Heartbeat:Connect(function()
        for _, e in ipairs(mobileButtons) do
            local act = Actions[e.name]
            paintBtn(e, act and act.get() or false)
        end
    end)

    -- Button Scale: масштаб мобильных кнопок
    Flags.applyButtonScale = function(sc)
        Flags.buttonScale = sc
        for _, e in ipairs(mobileButtons) do
            e.scale.Scale = sc
            local nx, ny = clampPos(e.btn.Position.X.Offset, e.btn.Position.Y.Offset)
            e.btn.Position = UDim2.fromOffset(nx, ny)
        end
    end

    Flags.getButtons = function()
        local t = {}
        for _, e in ipairs(mobileButtons) do
            t[e.name] = {x = e.btn.Position.X.Offset, y = e.btn.Position.Y.Offset}
        end
        return t
    end
    Flags.setButtons = function(t)
        for _, e in ipairs(mobileButtons) do
            local p = t[e.name]
            if type(p) == "table" and tonumber(p.x) and tonumber(p.y) then
                local nx, ny = clampPos(p.x, p.y)
                e.btn.Position = UDim2.fromOffset(nx, ny)
            end
        end
    end

    local function applyHide(state)
        hideButtons = state
        for _, e in ipairs(mobileButtons) do e.btn.Visible = not state end
    end

    -- ---------- Панель настроек ----------
    local panel9 = Instance.new("Frame")
    panel9.Name = "InterfacePanel"
    panel9.Size = UDim2.new(1, 0, 0, 122)
    panel9.BackgroundColor3 = COLOR_PANEL
    panel9.BorderSizePixel = 0
    panel9.LayoutOrder = 1
    panel9.Parent = currentPage
    local pc9 = Instance.new("UICorner", panel9)
    pc9.CornerRadius = UDim.new(0, 10)
    local ps9 = Instance.new("UIStroke", panel9)
    ps9.Color = COLOR_ACCENT
    ps9.Thickness = 1.5

    local titleLbl9 = Instance.new("TextLabel")
    titleLbl9.BackgroundTransparency = 1
    titleLbl9.Position = UDim2.new(0, 8, 0, 4)
    titleLbl9.Size = UDim2.new(0, 100, 0, 16)
    titleLbl9.Text = "INTERFACE"
    titleLbl9.Font = Enum.Font.GothamBold
    titleLbl9.TextSize = 11
    titleLbl9.TextColor3 = COLOR_BLUE
    titleLbl9.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl9.Parent = panel9

    makeLabel(panel9, UDim2.new(0, 8, 0, 26), "Lock UI", UDim2.new(0, 100, 0, 18))
    makeToggle(panel9, UDim2.new(1, -44, 0, 26), false, function(v) Flags.uiLocked = v end)

    makeLabel(panel9, UDim2.new(0, 8, 0, 58), "Hide Button", UDim2.new(0, 100, 0, 18))
    makeToggle(panel9, UDim2.new(1, -44, 0, 58), false, function(v) applyHide(v) end)

    local lockMobLbl = makeLabel(panel9, UDim2.new(0, 8, 0, 90), "Lock Mobile Buttons", UDim2.new(0, 92, 0, 18))
    lockMobLbl.TextSize = 9
    makeToggle(panel9, UDim2.new(1, -44, 0, 90), false, function(v) Flags.buttonsLocked = v end)

    -- ---------- BUTTONS VISIBILITY: убрать/вернуть каждую кнопку по отдельности ----------
    do
        local perHidden = {}   -- [имя кнопки] = true (убрана)
        local paints = {}      -- перерисовка чипов (нужна при загрузке сохранения)
        local LIST = {"DropBR", "AutoLeft", "AutoRight", "TpDown", "Carry",
                      "Lagger1", "Lagger2", "BatV2", "InstaReset", "BatBypass"}
        local ROWS = math.ceil(#LIST / 2)

        local panelB = Instance.new("Frame")
        panelB.Name = "ButtonsVisibilityPanel"
        panelB.Size = UDim2.new(1, 0, 0, 24 + ROWS * 24)
        panelB.BackgroundColor3 = COLOR_PANEL
        panelB.BorderSizePixel = 0
        panelB.LayoutOrder = 15
        panelB.Parent = currentPage
        local pbcB = Instance.new("UICorner", panelB)
        pbcB.CornerRadius = UDim.new(0, 10)
        local pbsB = Instance.new("UIStroke", panelB)
        pbsB.Color = COLOR_ACCENT
        pbsB.Thickness = 1.5

        local titleB = Instance.new("TextLabel")
        titleB.BackgroundTransparency = 1
        titleB.Position = UDim2.new(0, 8, 0, 4)
        titleB.Size = UDim2.new(0, 140, 0, 16)
        titleB.Text = "BUTTONS VISIBILITY"
        titleB.Font = Enum.Font.GothamBold
        titleB.TextSize = 11
        titleB.TextColor3 = COLOR_BLUE
        titleB.TextXAlignment = Enum.TextXAlignment.Left
        titleB.Parent = panelB

        for i, name in ipairs(LIST) do
            local col = (i - 1) % 2
            local row = math.floor((i - 1) / 2)
            local chip = makeChip(panelB,
                UDim2.new(0, 6 + col * 68, 0, 22 + row * 24),
                UDim2.new(0, 64, 0, 20), name, true)
            chip.TextSize = 8
            local function paint()
                local vis = not perHidden[name]
                chip.BackgroundColor3 = vis and COLOR_ACCENT_D or COLOR_BG
                chip.TextColor3 = vis and COLOR_TEXT or COLOR_TEXT_D
                local st = chip:FindFirstChildOfClass("UIStroke")
                if st then st.Color = vis and COLOR_ACCENT or COLOR_LINE end
            end
            paints[name] = paint
            chip.MouseButton1Click:Connect(function()
                perHidden[name] = not perHidden[name]
                paint()
                for _, e in ipairs(mobileButtons) do
                    if e.name == name then
                        e.btn.Visible = (not perHidden[name]) and (not hideButtons)
                    end
                end
            end)
        end

        -- убранные кнопки сохраняются через Safe Mode и при повторном запуске не появляются на экране
        local function setHidden(t)
            if type(t) ~= "table" then return end
            for _, name in ipairs(LIST) do
                perHidden[name] = t[name] and true or nil
                if paints[name] then paints[name]() end
            end
            for _, e in ipairs(mobileButtons) do
                e.btn.Visible = (not hideButtons) and (not perHidden[e.name])
            end
        end
        Flags.getHiddenButtons = function()
            local t = {}
            for _, name in ipairs(LIST) do
                if perHidden[name] then t[name] = true end
            end
            return t
        end
        Flags.setHiddenButtons = setHidden
        -- сразу читаем сохранение, чтобы убранные кнопки не мигнули на экране
        pcall(function()
            local f = "SpeexHub_" .. tostring(player.UserId) .. ".json"
            if type(isfile) == "function" and type(readfile) == "function" and isfile(f) then
                local d = game:GetService("HttpService"):JSONDecode(readfile(f))
                if type(d) == "table" then setHidden(d.hiddenButtons) end
            end
        end)

        -- учитываем выбор и в общей кнопке Hide Button: вернутся должны только разрешённые
        applyHide = function(state)
            hideButtons = state
            for _, e in ipairs(mobileButtons) do
                e.btn.Visible = (not state) and (not perHidden[e.name])
            end
        end
    end
end
currentPage = pages["MAIN"]

-- ================= VISUALS: Player ESP, ESP Line, UI Scale, Button Scale (логика из MVP HUB) =================
currentPage = pages["VISUALS"]
do
    local RunService = game:GetService("RunService")
    local LP = player
    local ESP_COLOR = Color3.fromRGB(75, 125, 255)

    local function guiParent()
        local ok, cg = pcall(function() return game:GetService("CoreGui") end)
        if ok and cg then
            local test = pcall(function() local f = Instance.new("Folder"); f.Parent = cg; f:Destroy() end)
            if test then return cg end
        end
        return LP:WaitForChild("PlayerGui")
    end

    -- ---------- Player ESP ----------
    local espEnabled = false
    local espPlayers = {}
    local espLoop, espJoin, espLeave = nil, nil, nil

    local function removeESP(plr)
        local d = espPlayers[plr]
        if d then
            if d.highlight then pcall(function() d.highlight:Destroy() end) end
            if d.tag then pcall(function() d.tag:Destroy() end) end
            espPlayers[plr] = nil
        end
    end

    local function createESP(plr)
        if plr == LP or espPlayers[plr] then return end
        local parent = guiParent()

        local hl = Instance.new("Highlight")
        hl.Name = "SpeexESP_Highlight"
        hl.FillColor = ESP_COLOR
        hl.OutlineColor = Color3.new(0, 0, 0)
        hl.FillTransparency = 0.12
        hl.OutlineTransparency = 0.18
        hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        hl.Parent = parent

        local tag = Instance.new("BillboardGui")
        tag.Name = "SpeexESP_Name"
        tag.Size = UDim2.new(0, 170, 0, 28)
        tag.StudsOffset = Vector3.new(0, 1.3, 0)
        tag.AlwaysOnTop = true
        tag.Parent = parent

        local lbl = Instance.new("TextLabel")
        lbl.Size = UDim2.new(1, 0, 1, 0)
        lbl.BackgroundTransparency = 1
        lbl.Text = plr.Name
        lbl.TextColor3 = ESP_COLOR
        lbl.TextSize = 15
        lbl.Font = Enum.Font.GothamBold
        lbl.TextStrokeColor3 = Color3.new(0, 0, 0)
        lbl.TextStrokeTransparency = 0
        lbl.Parent = tag

        espPlayers[plr] = {highlight = hl, tag = tag}
    end

    local function updateESP(plr, d)
        local char = plr.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local part = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart or char:FindFirstChild("Head"))
        if char and part and (not hum or hum.Health > 0) then
            d.highlight.Adornee = char
            d.highlight.Enabled = true
            d.tag.Adornee = part
            d.tag.Enabled = true
        else
            d.highlight.Adornee = nil
            d.highlight.Enabled = false
            d.tag.Enabled = false
        end
    end

    local function disableESP()
        espEnabled = false
        if espLoop then espLoop:Disconnect(); espLoop = nil end
        if espJoin then espJoin:Disconnect(); espJoin = nil end
        if espLeave then espLeave:Disconnect(); espLeave = nil end
        for plr in pairs(espPlayers) do removeESP(plr) end
    end

    local function enableESP()
        if espEnabled then return end
        espEnabled = true
        for _, plr in ipairs(Players:GetPlayers()) do createESP(plr) end
        local acc = 0
        espLoop = RunService.Heartbeat:Connect(function(dt)
            acc = acc + (dt or 0)
            if acc < 0.15 then return end
            acc = 0
            for plr, d in pairs(espPlayers) do
                pcall(updateESP, plr, d)
            end
        end)
        espJoin = Players.PlayerAdded:Connect(function(plr)
            if not espEnabled then return end
            task.wait(0.3)
            createESP(plr)
        end)
        espLeave = Players.PlayerRemoving:Connect(removeESP)
    end

    -- ---------- ESP Line (линия до ближайшего игрока) ----------
    local lineEnabled = false
    local lineGui, lineFrame, lineConn = nil, nil, nil
    local lineTarget, lineScan = nil, math.huge

    local function stopESPLine()
        lineEnabled = false
        if lineConn then lineConn:Disconnect(); lineConn = nil end
        if lineGui then pcall(function() lineGui:Destroy() end) end
        lineGui, lineFrame, lineTarget, lineScan = nil, nil, nil, math.huge
    end

    local function startESPLine()
        stopESPLine()
        lineEnabled = true
        lineGui = Instance.new("ScreenGui")
        lineGui.Name = "SpeexESPLine"
        lineGui.IgnoreGuiInset = true
        lineGui.ResetOnSpawn = false
        lineGui.DisplayOrder = 1000
        lineGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        lineGui.Parent = guiParent()

        lineFrame = Instance.new("Frame")
        lineFrame.AnchorPoint = Vector2.new(0.5, 0.5)
        lineFrame.BorderSizePixel = 0
        lineFrame.Visible = false
        lineFrame.BackgroundColor3 = ESP_COLOR
        lineFrame.Parent = lineGui
        local ls = Instance.new("UIStroke", lineFrame)
        ls.Color = Color3.new(1, 1, 1)
        ls.Thickness = 0.7
        ls.Transparency = 0.45

        lineConn = RunService.RenderStepped:Connect(function(dt)
            if not lineEnabled or not lineFrame then return end
            local ok = pcall(function()
                local cam = workspace.CurrentCamera
                local myChar = LP.Character
                local myRoot = myChar and (myChar:FindFirstChild("LowerTorso") or myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChild("Torso"))
                if not cam or not myRoot then lineFrame.Visible = false; return end
                local myPos = myRoot.Position

                lineScan = lineScan + (dt or 0)
                local valid = lineTarget and lineTarget.Parent
                if valid then
                    local h = lineTarget.Parent:FindFirstChildOfClass("Humanoid")
                    valid = (not h) or h.Health > 0
                end
                if lineScan >= 0.12 or not valid then
                    lineScan = 0
                    local best, bestD = nil, math.huge
                    for _, other in ipairs(Players:GetPlayers()) do
                        if other ~= LP and other.Character then
                            local h = other.Character:FindFirstChildOfClass("Humanoid")
                            local r = other.Character:FindFirstChild("HumanoidRootPart") or other.Character:FindFirstChild("Torso")
                            if r and r:IsA("BasePart") and (not h or h.Health > 0) then
                                local d = r.Position - myPos
                                local dsq = d:Dot(d)
                                if dsq < bestD then best, bestD = r, dsq end
                            end
                        end
                    end
                    lineTarget = best
                end

                if not lineTarget or not lineTarget.Parent then lineFrame.Visible = false; return end

                local from = cam:WorldToViewportPoint(myPos - Vector3.new(0, myRoot.Size.Y * 0.35, 0))
                local to, onScreen = cam:WorldToViewportPoint(lineTarget.Position)
                local vp = cam.ViewportSize
                local fromP = Vector2.new(from.X, from.Y)
                local toP = Vector2.new(to.X, to.Y)

                if not onScreen or to.Z <= 0 then
                    local center = vp * 0.5
                    local dir = toP - center
                    if to.Z <= 0 then dir = -dir end
                    if dir.Magnitude < 0.001 then dir = Vector2.new(0, -1) end
                    local lim = Vector2.new(math.max(8, center.X - 8), math.max(8, center.Y - 8))
                    local sx = lim.X / math.max(math.abs(dir.X), 0.001)
                    local sy = lim.Y / math.max(math.abs(dir.Y), 0.001)
                    toP = center + dir * math.min(sx, sy)
                end
                if from.Z <= 0 or fromP.X < 0 or fromP.X > vp.X or fromP.Y < 0 or fromP.Y > vp.Y then
                    fromP = Vector2.new(vp.X * 0.5, vp.Y - 8)
                end

                local delta = toP - fromP
                local mid = (fromP + toP) * 0.5
                lineFrame.Position = UDim2.fromOffset(mid.X, mid.Y)
                lineFrame.Size = UDim2.fromOffset(math.max(delta.Magnitude, 1), 2)
                lineFrame.Rotation = math.deg(math.atan2(delta.Y, delta.X))
                lineFrame.Visible = true
            end)
            if not ok and lineFrame then lineFrame.Visible = false end
        end)
    end

    -- ---------- UI Scale / Button Scale ----------
    local mainScale = Instance.new("UIScale", Main)
    mainScale.Scale = 1

    local function numBox(parent, name, y, default, onApply)
        local box = Instance.new("TextBox")
        box.Name = name
        box.Size = UDim2.new(0, 40, 0, 22)
        box.Position = UDim2.new(1, -48, 0, y - 2)
        box.BackgroundColor3 = COLOR_BG
        box.Text = tostring(default)
        box.Font = Enum.Font.GothamBold
        box.TextSize = 12
        box.TextColor3 = COLOR_TEXT
        box.TextXAlignment = Enum.TextXAlignment.Center
        box.ClearTextOnFocus = false
        box.Parent = parent
        local bc = Instance.new("UICorner", box)
        bc.CornerRadius = UDim.new(0, 6)
        local bs = Instance.new("UIStroke", box)
        bs.Color = COLOR_ACCENT
        bs.Thickness = 1.5
        box:GetPropertyChangedSignal("Text"):Connect(function()
            local t = box.Text:gsub("%D", "")
            if box.Text ~= t then box.Text = t end
        end)
        local last = default
        local function commit()
            local v = tonumber(box.Text)
            if v then
                last = onApply(v)
                box.Text = tostring(last)
            else
                box.Text = tostring(last)
            end
        end
        box.FocusLost:Connect(commit)
        Flags.apply[name] = commit
        return box
    end

    -- ---------- Панели ----------
    local function newPanel(name, title, height, order)
        local p = Instance.new("Frame")
        p.Name = name
        p.Size = UDim2.new(1, 0, 0, height)
        p.BackgroundColor3 = COLOR_PANEL
        p.BorderSizePixel = 0
        p.LayoutOrder = order
        p.Parent = currentPage
        local c = Instance.new("UICorner", p)
        c.CornerRadius = UDim.new(0, 10)
        local s = Instance.new("UIStroke", p)
        s.Color = COLOR_ACCENT
        s.Thickness = 1.5
        local t = Instance.new("TextLabel")
        t.BackgroundTransparency = 1
        t.Position = UDim2.new(0, 8, 0, 4)
        t.Size = UDim2.new(0, 100, 0, 16)
        t.Text = title
        t.Font = Enum.Font.GothamBold
        t.TextSize = 11
        t.TextColor3 = COLOR_BLUE
        t.TextXAlignment = Enum.TextXAlignment.Left
        t.Parent = p
        return p
    end

    local pe = newPanel("EspPanel", "ESP", 92, 2)
    makeLabel(pe, UDim2.new(0, 8, 0, 26), "Player ESP", UDim2.new(0, 100, 0, 18))
    makeToggle(pe, UDim2.new(1, -44, 0, 26), false, function(v)
        if v then enableESP() else disableESP() end
    end)
    makeLabel(pe, UDim2.new(0, 8, 0, 58), "ESP Line", UDim2.new(0, 100, 0, 18))
    makeToggle(pe, UDim2.new(1, -44, 0, 58), false, function(v)
        if v then startESPLine() else stopESPLine() end
    end)

    local pd = newPanel("DisplayPanel", "DISPLAY", 92, 3)
    makeLabel(pd, UDim2.new(0, 8, 0, 26), "UI Scale", UDim2.new(0, 90, 0, 18))
    numBox(pd, "UIScaleBox", 26, 100, function(v)
        v = math.clamp(v, 50, 150)
        mainScale.Scale = v / 100
        return v
    end)
    makeLabel(pd, UDim2.new(0, 8, 0, 58), "Button Scale", UDim2.new(0, 90, 0, 18))
    numBox(pd, "ButtonScaleBox", 58, 100, function(v)
        v = math.clamp(v, 50, 200)
        if Flags.applyButtonScale then Flags.applyButtonScale(v / 100) end
        return v
    end)
end
currentPage = pages["MAIN"]


-- ================= CONFIG: GRAPHICS — Anti Lag / Stretch Res / Vivid Graphics =================
currentPage = pages["CONFIG"]
do
    local RunService = game:GetService("RunService")
    local Lighting = game:GetService("Lighting")
    local Workspace = game:GetService("Workspace")

    -- ---------- ANTI LAG ----------
    local antiLagOn = false
    local alStored = setmetatable({}, {__mode = "k"})   -- [Instance] = исходное Enabled
    local alLighting = nil                               -- исходные настройки освещения/качества
    local alConns = {}

    local DISABLE_CLASSES = {
        ParticleEmitter = true, Trail = true, Beam = true, Smoke = true,
        Fire = true, Sparkles = true,
        BlurEffect = true, BloomEffect = true, DepthOfFieldEffect = true, SunRaysEffect = true,
    }

    local function lighten(inst)
        if DISABLE_CLASSES[inst.ClassName] and not string.find(inst.Name, "^Speex") then
            if alStored[inst] == nil then alStored[inst] = inst.Enabled end
            inst.Enabled = false
        end
    end

    local function setAntiLag(v)
        antiLagOn = v
        if v then
            alLighting = {
                shadows = Lighting.GlobalShadows,
                quality = nil,
            }
            pcall(function() alLighting.quality = settings().Rendering.QualityLevel end)
            Lighting.GlobalShadows = false
            pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
            for _, d in ipairs(Workspace:GetDescendants()) do lighten(d) end
            for _, d in ipairs(Lighting:GetDescendants()) do lighten(d) end
            table.insert(alConns, Workspace.DescendantAdded:Connect(lighten))
            table.insert(alConns, Lighting.DescendantAdded:Connect(lighten))
        else
            for _, c in ipairs(alConns) do c:Disconnect() end
            alConns = {}
            for inst, en in pairs(alStored) do
                if inst and inst.Parent then pcall(function() inst.Enabled = en end) end
                alStored[inst] = nil
            end
            if alLighting then
                Lighting.GlobalShadows = alLighting.shadows
                if alLighting.quality then
                    pcall(function() settings().Rendering.QualityLevel = alLighting.quality end)
                end
                alLighting = nil
            end
        end
    end

    -- ---------- STRETCH RES ----------
    local stretchOn = false
    local stretchBox -- TextBox со значением (в %), ниже создаётся
    local function stretchValue()
        local n = stretchBox and tonumber(stretchBox.Text) or 65
        if not n then n = 65 end
        return math.clamp(n, 30, 100) / 100
    end

    local function setStretch(v)
        stretchOn = v
        pcall(function() RunService:UnbindFromRenderStep("SpeexStretchRes") end)
        if v then
            RunService:BindToRenderStep("SpeexStretchRes", Enum.RenderPriority.Camera.Value + 1, function()
                local cam = Workspace.CurrentCamera
                if cam then
                    cam.CFrame = cam.CFrame * CFrame.new(0, 0, 0, 1, 0, 0, 0, stretchValue(), 0, 0, 0, 1)
                end
            end)
        end
    end

    -- ---------- VIVID GRAPHICS ----------
    local vividObjs = {}
    local function setVivid(v)
        for _, o in ipairs(vividObjs) do if o then o:Destroy() end end
        vividObjs = {}
        if v then
            local cc = Instance.new("ColorCorrectionEffect")
            cc.Name = "SpeexVividCC"
            cc.Saturation = 0.35
            cc.Contrast = 0.15
            cc.Brightness = 0.02
            cc.Parent = Lighting

            local bloom = Instance.new("BloomEffect")
            bloom.Name = "SpeexVividBloom"
            bloom.Intensity = 0.35
            bloom.Size = 24
            bloom.Threshold = 1.6
            bloom.Parent = Lighting

            local sun = Instance.new("SunRaysEffect")
            sun.Name = "SpeexVividSun"
            sun.Intensity = 0.08
            sun.Spread = 0.6
            sun.Parent = Lighting

            vividObjs = {cc, bloom, sun}
        end
    end

    -- ---------- Панель ----------
    local panelG = Instance.new("Frame")
    panelG.Name = "GraphicsPanel"
    panelG.Size = UDim2.new(1, 0, 0, 150)
    panelG.BackgroundColor3 = COLOR_PANEL
    panelG.BorderSizePixel = 0
    panelG.LayoutOrder = 3
    panelG.Parent = currentPage
    local pcG = Instance.new("UICorner", panelG)
    pcG.CornerRadius = UDim.new(0, 10)
    local psG = Instance.new("UIStroke", panelG)
    psG.Color = COLOR_ACCENT
    psG.Thickness = 1.5

    local titleG = Instance.new("TextLabel")
    titleG.BackgroundTransparency = 1
    titleG.Position = UDim2.new(0, 8, 0, 4)
    titleG.Size = UDim2.new(0, 100, 0, 16)
    titleG.Text = "GRAPHICS"
    titleG.Font = Enum.Font.GothamBold
    titleG.TextSize = 11
    titleG.TextColor3 = COLOR_BLUE
    titleG.TextXAlignment = Enum.TextXAlignment.Left
    titleG.Parent = panelG

    makeLabel(panelG, UDim2.new(0, 8, 0, 26), "Anti Lag", UDim2.new(0, 100, 0, 18))
    local _, antiVisual = makeToggle(panelG, UDim2.new(1, -44, 0, 26), false, setAntiLag)

    makeLabel(panelG, UDim2.new(0, 8, 0, 58), "Stretch Res", UDim2.new(0, 100, 0, 18))
    local _, stretchVisual = makeToggle(panelG, UDim2.new(1, -44, 0, 58), false, setStretch)

    makeLabel(panelG, UDim2.new(0, 8, 0, 90), "Stretch %", UDim2.new(0, 100, 0, 18))
    stretchBox = Instance.new("TextBox")
    stretchBox.Name = "StretchValue"
    stretchBox.Size = UDim2.new(0, 36, 0, 22)
    stretchBox.Position = UDim2.new(1, -44, 0, 88)
    stretchBox.BackgroundColor3 = COLOR_BG
    stretchBox.Text = "65"
    stretchBox.Font = Enum.Font.GothamBold
    stretchBox.TextSize = 12
    stretchBox.TextColor3 = COLOR_TEXT
    stretchBox.TextXAlignment = Enum.TextXAlignment.Center
    stretchBox.ClearTextOnFocus = false
    stretchBox.Parent = panelG
    local sbcG = Instance.new("UICorner", stretchBox)
    sbcG.CornerRadius = UDim.new(0, 6)
    local sbsG = Instance.new("UIStroke", stretchBox)
    sbsG.Color = COLOR_LINE
    sbsG.Thickness = 1
    stretchBox:GetPropertyChangedSignal("Text"):Connect(function()
        local t = stretchBox.Text:gsub("%D", "")
        if stretchBox.Text ~= t then stretchBox.Text = t end
    end)
    stretchBox.FocusLost:Connect(function()
        local n = tonumber(stretchBox.Text)
        if not n then stretchBox.Text = "65"; return end
        stretchBox.Text = tostring(math.clamp(n, 30, 100))
    end)

    makeLabel(panelG, UDim2.new(0, 8, 0, 122), "Vivid Graphics", UDim2.new(0, 100, 0, 18))
    local _, vividVisual = makeToggle(panelG, UDim2.new(1, -44, 0, 122), false, setVivid)

    Actions.AntiLag = {get = function() return antiLagOn end, set = function(v) antiVisual(v) setAntiLag(v) end}
    Actions.StretchRes = {get = function() return stretchOn end, set = function(v) stretchVisual(v) setStretch(v) end}
    Actions.VividGraphics = {get = function() return #vividObjs > 0 end, set = function(v) vividVisual(v) setVivid(v) end}
end
