-- ================= KEYBINDS: клавиши на функции хаба =================
currentPage = pages["KEYBINDS"]
do
    local HttpService = game:GetService("HttpService")
    local FILE = "SpeexKeybinds_" .. tostring(player.UserId) .. ".json"

    -- Hide GUI: прячет/показывает всё меню хаба
    Actions.HideGUI = {
        get = function() return not Main.Visible end,
        set = function(v) Main.Visible = not v end,
    }

    -- порядок строк: {имя действия в Actions, подпись}
    local DEFS = {
        {"DropBR",    "Drop Brainrot"},
        {"TpDown",    "TP Down"},
        {"AutoTpDown", "Auto TP Down"},
        {"HideGUI",   "Hide GUI"},
        {"Carry",     "Carry Mode"},
        {"Lagger1",   "Lagger Normal"},
        {"Lagger2",   "Lagger Carry"},
        {"AutoLeft",  "Auto Left"},
        {"AutoRight", "Auto Right"},
        {"BatV2",     "TP Bat"},
        {"InstaReset", "Insta Reset"},
        {"BatBypass", "Bat Bypass"},
    }

    local binds = {}      -- [действие] = Enum.KeyCode
    local buttons = {}    -- [действие] = TextButton
    local listening = nil -- действие, для которого ждём клавишу

    local function fsOk()
        return type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
    end

    local function saveBinds()
        if not fsOk() then return end
        local t = {}
        for name, key in pairs(binds) do t[name] = key.Name end
        pcall(function() writefile(FILE, HttpService:JSONEncode(t)) end)
    end

    local function paint(name)
        local b = buttons[name]
        if not b then return end
        if listening == name then
            b.Text = "..."
            b.TextColor3 = COLOR_BLUE
        else
            local k = binds[name]
            b.Text = k and k.Name or "None"
            b.TextColor3 = k and COLOR_TEXT or COLOR_TEXT_D
        end
    end

    local function setBind(name, key)
        if key then
            for other, k in pairs(binds) do      -- одна клавиша = одно действие
                if k == key and other ~= name then binds[other] = nil; paint(other) end
            end
            binds[name] = key
        else
            binds[name] = nil
        end
        paint(name)
        saveBinds()
    end

    -- ---------- Панель ----------
    local panelK = Instance.new("Frame")
    panelK.Name = "KeybindsPanel"
    panelK.Size = UDim2.new(1, 0, 0, 30 + #DEFS * 28)
    panelK.BackgroundColor3 = COLOR_PANEL
    panelK.BorderSizePixel = 0
    panelK.LayoutOrder = 1
    panelK.Parent = currentPage
    local pcK = Instance.new("UICorner", panelK)
    pcK.CornerRadius = UDim.new(0, 10)
    local psK = Instance.new("UIStroke", panelK)
    psK.Color = COLOR_ACCENT
    psK.Thickness = 1.5

    local titleK = Instance.new("TextLabel")
    titleK.BackgroundTransparency = 1
    titleK.Position = UDim2.new(0, 8, 0, 4)
    titleK.Size = UDim2.new(1, -16, 0, 16)
    titleK.Text = "KEYBINDS  (Esc/Backspace = clear)"
    titleK.Font = Enum.Font.GothamBold
    titleK.TextSize = 10
    titleK.TextColor3 = COLOR_BLUE
    titleK.TextXAlignment = Enum.TextXAlignment.Left
    titleK.Parent = panelK

    for i, def in ipairs(DEFS) do
        local name, text = def[1], def[2]
        local y = 24 + (i - 1) * 28
        makeLabel(panelK, UDim2.new(0, 8, 0, y + 2), text, UDim2.new(0, 84, 0, 18))

        local b = Instance.new("TextButton")
        b.Name = "Bind_" .. name
        b.Size = UDim2.new(0, 52, 0, 22)
        b.Position = UDim2.new(1, -60, 0, y)
        b.BackgroundColor3 = COLOR_BG
        b.AutoButtonColor = false
        b.Font = Enum.Font.GothamBold
        b.TextSize = 10
        b.TextColor3 = COLOR_TEXT_D
        b.Text = "None"
        b.TextTruncate = Enum.TextTruncate.AtEnd
        b.Parent = panelK
        local bc = Instance.new("UICorner", b)
        bc.CornerRadius = UDim.new(0, 6)
        local bs = Instance.new("UIStroke", b)
        bs.Color = COLOR_LINE
        bs.Thickness = 1
        buttons[name] = b

        b.MouseButton1Click:Connect(function()
            local prev = listening
            listening = (listening == name) and nil or name
            if prev then paint(prev) end
            paint(name)
        end)
    end

    -- ---------- Обработка нажатий ----------
    UserInputService.InputBegan:Connect(function(input, gpe)
        if input.UserInputType ~= Enum.UserInputType.Keyboard then return end

        if listening then
            local name = listening
            listening = nil
            if input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.Backspace then
                setBind(name, nil)
            else
                setBind(name, input.KeyCode)
            end
            paint(name)
            return
        end

        if gpe then return end   -- не срабатываем при вводе в чат / текстовые поля
        for name, key in pairs(binds) do
            if key == input.KeyCode then
                local act = Actions[name]
                if act then
                    local ok, err = pcall(function()
                        if name == "TpDown" then act.set(true) else act.set(not act.get()) end
                    end)
                    if not ok then warn("[Speex Keybind] " .. name .. ": " .. tostring(err)) end
                end
            end
        end
    end)

    -- ---------- Загрузка сохранённых клавиш (по умолчанию: Hide GUI = RightShift, Insta Reset = R) ----------
    local loaded = false
    if fsOk() then
        pcall(function()
            if isfile(FILE) then
                local data = HttpService:JSONDecode(readfile(FILE))
                for name, kn in pairs(data) do
                    local ok, kc = pcall(function() return Enum.KeyCode[kn] end)
                    if ok and kc and buttons[name] then binds[name] = kc end
                end
                loaded = true
            end
        end)
    end
    if not loaded then
        binds.HideGUI = Enum.KeyCode.RightShift
        binds.InstaReset = Enum.KeyCode.R
    end
    for name in pairs(buttons) do paint(name) end
end
