end,
remove = removeOutfit,
cleanup = function()
state.enabled = false
clearVisuals()
restoreOriginalDescription()
end,
}
    end)()

    -- ---------- Панель ----------
    local CHIP_W, CHIP_H, ROW_H = 68, 20, 24
    local panelO = Instance.new("Frame")
    panelO.Name = "OutfitPanel"
    panelO.Size = UDim2.new(1, 0, 0, 44 + 5 * ROW_H + 4)
    panelO.BackgroundColor3 = COLOR_PANEL
    panelO.BorderSizePixel = 0
    panelO.LayoutOrder = 4
    panelO.Parent = currentPage
    local pcO = Instance.new("UICorner", panelO)
    pcO.CornerRadius = UDim.new(0, 10)
    local psO = Instance.new("UIStroke", panelO)
    psO.Color = COLOR_ACCENT
    psO.Thickness = 1.5

    local titleO = Instance.new("TextLabel")
    titleO.BackgroundTransparency = 1
    titleO.Position = UDim2.new(0, 8, 0, 4)
    titleO.Size = UDim2.new(0, 100, 0, 16)
    titleO.Text = "OUTFIT"
    titleO.Font = Enum.Font.GothamBold
    titleO.TextSize = 11
    titleO.TextColor3 = COLOR_BLUE
    titleO.TextXAlignment = Enum.TextXAlignment.Left
    titleO.Parent = panelO

    local statusO = Instance.new("TextLabel")
    statusO.BackgroundTransparency = 1
    statusO.Position = UDim2.new(0, 8, 0, 22)
    statusO.Size = UDim2.new(1, -16, 0, 14)
    statusO.Text = "Pick a skin"
    statusO.Font = Enum.Font.Gotham
    statusO.TextSize = 9
    statusO.TextColor3 = COLOR_TEXT_D
    statusO.TextXAlignment = Enum.TextXAlignment.Left
    statusO.TextTruncate = Enum.TextTruncate.AtEnd
    statusO.Parent = panelO
    Outfit.setStatusLabel(statusO)

    local selected = nil     -- номер выбранного скина (nil = выключено)
    local chips = {}

    local function paintChip(chip, active)
        chip.BackgroundColor3 = active and COLOR_ACCENT_D or COLOR_BG
        chip.TextColor3 = active and COLOR_TEXT or COLOR_TEXT_D
        local st = chip:FindFirstChildOfClass("UIStroke")
        if st then st.Color = active and COLOR_ACCENT or COLOR_LINE end
    end
    local function paintAll()
        for i, c in pairs(chips) do paintChip(c, selected == i) end
    end

    local busy = false
    local function applySkin(i)
        if busy then return end
        busy = true
        selected = i
        paintAll()
        task.spawn(function()
            pcall(function() Outfit.apply(i) end)
            busy = false
        end)
    end

    for i, o in ipairs(Outfit.outfits) do
        local col = (i - 1) % 2
        local row = math.floor((i - 1) / 2)
        local chip = makeChip(panelO, UDim2.new(0, 6 + col * (CHIP_W + 6), 0, 40 + row * ROW_H),
            UDim2.new(0, CHIP_W, 0, CHIP_H), o.label, false)
        chip.TextSize = 9
        chips[i] = chip
        chip.MouseButton1Click:Connect(function() applySkin(i) end)
    end

    -- кнопка REMOVE (последняя ячейка сетки)
    do
        local i = #Outfit.outfits + 1
        local col = (i - 1) % 2
        local row = math.floor((i - 1) / 2)
        local rm = makeChip(panelO, UDim2.new(0, 6 + col * (CHIP_W + 6), 0, 40 + row * ROW_H),
            UDim2.new(0, CHIP_W, 0, CHIP_H), "REMOVE", false)
        rm.TextSize = 9
        rm.MouseButton1Click:Connect(function()
            selected = nil
            paintAll()
            pcall(Outfit.remove)
        end)
    end

    -- после респавна применяем выбранный скин заново
    player.CharacterAdded:Connect(function()
        if not selected then return end
        task.wait(1.5)
        if selected then pcall(function() Outfit.apply(selected) end) end
    end)

    Actions.Outfit = {
        get = function() return selected ~= nil end,
        set = function(v) if not v then selected = nil; paintAll(); pcall(Outfit.remove) end end,
    }
end
currentPage = pages["MAIN"]

-- ================= VISUALS: ANIMATION PACK (перенесён из Nebula Hub) =================
-- меняет анимации бега/простоя/прыжка/падения/лазания/плавания на выбранный пак
currentPage = pages["VISUALS"]
do
    local RunService = game:GetService("RunService")

local ANIM_PACKS = {
    ["Zombie"] = { idle1="rbxassetid://616158929", idle2="rbxassetid://616160636", walk="rbxassetid://616168032", run="rbxassetid://616163682", jump="rbxassetid://616161997", fall="rbxassetid://616157476", climb="rbxassetid://616156119", swim="rbxassetid://616165109", swimidle="rbxassetid://616166655" },
    ["Ninja"] = { idle1="rbxassetid://656117400", idle2="rbxassetid://656117400", walk="rbxassetid://656121766", run="rbxassetid://656118852", jump="rbxassetid://656117878", fall="rbxassetid://656115606", climb="rbxassetid://656114359", swim="rbxassetid://656117400", swimidle="rbxassetid://656117400" },
    ["Knight"] = { idle1="rbxassetid://657595757", idle2="rbxassetid://657595757", walk="rbxassetid://657552124", run="rbxassetid://657564596", jump="rbxassetid://658409194", fall="rbxassetid://657600338", climb="rbxassetid://658360781", swim="rbxassetid://657595757", swimidle="rbxassetid://657595757" },
    ["Elder"] = { idle1="rbxassetid://845397899", idle2="rbxassetid://845397899", walk="rbxassetid://845403856", run="rbxassetid://845386501", jump="rbxassetid://845398858", fall="rbxassetid://845397673", climb="rbxassetid://845392038", swim="rbxassetid://845397899", swimidle="rbxassetid://845397899" },
    ["Levitate"] = { idle1="rbxassetid://616006778", idle2="rbxassetid://616006778", walk="rbxassetid://616013216", run="rbxassetid://616013216", jump="rbxassetid://616008936", fall="rbxassetid://616005863", climb="rbxassetid://616003713", swim="rbxassetid://616006778", swimidle="rbxassetid://616006778" },
    ["Astronaut"] = { idle1="rbxassetid://891621366", idle2="rbxassetid://891621366", walk="rbxassetid://891636393", run="rbxassetid://891636393", jump="rbxassetid://891627522", fall="rbxassetid://891617961", climb="rbxassetid://891609353", swim="rbxassetid://891621366", swimidle="rbxassetid://891621366" },
    ["Pirate"] = { idle1="rbxassetid://750781874", idle2="rbxassetid://750781874", walk="rbxassetid://750785693", run="rbxassetid://750783738", jump="rbxassetid://750782230", fall="rbxassetid://750780242", climb="rbxassetid://750779899", swim="rbxassetid://750781874", swimidle="rbxassetid://750781874" },
    ["Toy"] = { idle1="rbxassetid://782841498", idle2="rbxassetid://782841498", walk="rbxassetid://782843345", run="rbxassetid://782842708", jump="rbxassetid://782847020", fall="rbxassetid://782846423", climb="rbxassetid://782843869", swim="rbxassetid://782841498", swimidle="rbxassetid://782841498" },
    ["Vampire"] = { idle1="rbxassetid://1083445855", idle2="rbxassetid://1083445855", walk="rbxassetid://1083473930", run="rbxassetid://1083462077", jump="rbxassetid://1083455352", fall="rbxassetid://1083443587", climb="rbxassetid://1083439238", swim="rbxassetid://1083445855", swimidle="rbxassetid://1083445855" },
    ["Werewolf"] = { idle1="rbxassetid://1083195517", idle2="rbxassetid://1083195517", walk="rbxassetid://1083178339", run="rbxassetid://1083216690", jump="rbxassetid://1083218792", fall="rbxassetid://1083189019", climb="rbxassetid://1083182000", swim="rbxassetid://1083195517", swimidle="rbxassetid://1083195517" },
    ["Rthro"] = { idle1="rbxassetid://2510196951", idle2="rbxassetid://2510196951", walk="rbxassetid://2510202577", run="rbxassetid://2510198475", jump="rbxassetid://2510197830", fall="rbxassetid://2510195892", climb="rbxassetid://2510192778", swim="rbxassetid://2510196951", swimidle="rbxassetid://2510196951" },
    ["Stylish"] = { idle1="rbxassetid://616136790", idle2="rbxassetid://616136790", walk="rbxassetid://616146177", run="rbxassetid://616140816", jump="rbxassetid://616139451", fall="rbxassetid://616134815", climb="rbxassetid://616133594", swim="rbxassetid://616136790", swimidle="rbxassetid://616136790" },
}

    local ORDER = {"Off", "Zombie", "Ninja", "Knight", "Elder", "Levitate", "Astronaut",
                   "Pirate", "Toy", "Vampire", "Werewolf", "Rthro", "Stylish"}
    local current = "Off"
    local original = nil
    local hbConn = nil

    local function isPackAnim(id)
        for _, pack in pairs(ANIM_PACKS) do
            for _, v in pairs(pack) do
                if v == id then return true end
            end
        end
        return false
    end

    local function saveOriginal(char)
        local animate = char:FindFirstChild("Animate")
        if not animate then return end
        local function g(obj) return obj and obj.AnimationId or nil end
        local ids = {
            idle1 = g(animate.idle and animate.idle.Animation1),
            idle2 = g(animate.idle and animate.idle.Animation2),
            walk = g(animate.walk and animate.walk.WalkAnim),
            run = g(animate.run and animate.run.RunAnim),
            jump = g(animate.jump and animate.jump.JumpAnim),
            fall = g(animate.fall and animate.fall.FallAnim),
            climb = g(animate.climb and animate.climb.ClimbAnim),
            swim = g(animate.swim and animate.swim.Swim),
            swimidle = g(animate.swimidle and animate.swimidle.SwimIdle),
        }
        if not isPackAnim(ids.walk) then original = ids end
    end

    local function setIds(animate, ids)
        local function set(obj, id) if obj and id then obj.AnimationId = id end end
        set(animate.idle and animate.idle.Animation1, ids.idle1)
        set(animate.idle and animate.idle.Animation2, ids.idle2)
        set(animate.walk and animate.walk.WalkAnim, ids.walk)
        set(animate.run and animate.run.RunAnim, ids.run)
        set(animate.jump and animate.jump.JumpAnim, ids.jump)
        set(animate.fall and animate.fall.FallAnim, ids.fall)
        set(animate.climb and animate.climb.ClimbAnim, ids.climb)
        set(animate.swim and animate.swim.Swim, ids.swim)
        set(animate.swimidle and animate.swimidle.SwimIdle, ids.swimidle)
    end

    local function applyPack(name)
        current = name
        if hbConn then hbConn:Disconnect() hbConn = nil end
        if name == "Off" then
            local animate = player.Character and player.Character:FindFirstChild("Animate")
            if original and animate then setIds(animate, original) end
            return
        end
        local pack = ANIM_PACKS[name]
        if not pack then return end
        -- каждый кадр удерживаем нужные анимации, чтобы игра их не перезаписывала
        hbConn = RunService.Heartbeat:Connect(function()
            local c = player.Character
            local animate = c and c:FindFirstChild("Animate")
            if animate then setIds(animate, pack) end
        end)
    end

    local function startPack(name)
        local char = player.Character
        if char then
            saveOriginal(char)
            applyPack(name)
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                for _, track in ipairs(hum:GetPlayingAnimationTracks()) do track:Stop(0) end
                hum:ChangeState(Enum.HumanoidStateType.Running)
            end
        else
            applyPack(name)
        end
        current = name
    end

    -- ---------- панель ----------
    local panelAP = Instance.new("Frame")
    panelAP.Name = "AnimPackPanel"
    panelAP.Size = UDim2.new(1, 0, 0, 60)
    panelAP.BackgroundColor3 = COLOR_PANEL
    panelAP.BorderSizePixel = 0
    panelAP.LayoutOrder = 90
    panelAP.Parent = currentPage
    Instance.new("UICorner", panelAP).CornerRadius = UDim.new(0, 10)
    local psAP = Instance.new("UIStroke", panelAP)
    psAP.Color = COLOR_ACCENT
    psAP.Thickness = 1.5

    local titleAP = Instance.new("TextLabel")
    titleAP.BackgroundTransparency = 1
    titleAP.Position = UDim2.new(0, 8, 0, 4)
    titleAP.Size = UDim2.new(0, 120, 0, 16)
    titleAP.Text = "ANIMATIONS"
    titleAP.Font = Enum.Font.GothamBold
    titleAP.TextSize = 11
    titleAP.TextColor3 = COLOR_BLUE
    titleAP.TextXAlignment = Enum.TextXAlignment.Left
    titleAP.Parent = panelAP

    local prevChip = makeChip(panelAP, UDim2.new(0, 8, 0, 28), UDim2.new(0, 28, 0, 22), "<", false)
    local nameChip = makeChip(panelAP, UDim2.new(0, 40, 0, 28), UDim2.new(1, -80, 0, 22), "Off", true)
    local nextChip = makeChip(panelAP, UDim2.new(1, -36, 0, 28), UDim2.new(0, 28, 0, 22), ">", false)

    local function indexOf(name)
        for i, v in ipairs(ORDER) do if v == name then return i end end
        return 1
    end

    local function setPack(name)
        if not ANIM_PACKS[name] and name ~= "Off" then name = "Off" end
        nameChip.Text = name
        if name == "Off" then
            applyPack("Off")
        else
            startPack(name)
        end
        current = name
    end

    prevChip.MouseButton1Click:Connect(function()
        local i = indexOf(current) - 1
        if i < 1 then i = #ORDER end
        setPack(ORDER[i])
    end)
    nextChip.MouseButton1Click:Connect(function()
        local i = indexOf(current) + 1
        if i > #ORDER then i = 1 end
        setPack(ORDER[i])
    end)

    -- после респавна возвращаем выбранный пак
    player.CharacterAdded:Connect(function()
        if current ~= "Off" then
            task.wait(0.6)
            if current ~= "Off" then startPack(current) end
        end
    end)

    Flags.animPack = {
        get = function() return current end,
        set = function(name) setPack(name) end,
    }
end
currentPage = pages["MAIN"]

-- ================= COMBAT: AUTO BAT (перенесён из Zurich Hub: режимы V1 / V2 / Perso) =================
currentPage = pages["COMBAT"]
do
    local RunService = game:GetService("RunService")
    local Debris = game:GetService("Debris")

    -- границы карты для V2 / Perso (как в Zurich)
    local MIN_X, MAX_X = -540, -420
    local MIN_Z, MAX_Z = -75, 200
    local MAX_TARGET_SPEED = 100
    local MARK_COLOR = Color3.fromRGB(0, 120, 240)

    local ab = {on = false, mode = "V1", colMode = "V1", tpDist = 8, hitCd = false}
    local hum, hrp = nil, nil
    local safe = {
        lastSafeCF = nil, markerTarget = nil, markerGroundCF = nil, marker = nil,
        ragLatched = false, lastPos = nil, lastT = 0, recoverUntil = 0, repRoot = false,
    }
    local markedPos = nil

    local function inX(x) return x >= MIN_X and x <= MAX_X end
    local function inZ(z) return z >= MIN_Z and z <= MAX_Z end

    -- ---------- коллизия с игроками ----------
    local noColActive, noColConn = false, nil
    local function setNoPlayerCollision(active)
        active = active == true
        if active == noColActive then return end
        noColActive = active
        if noColConn then noColConn:Disconnect() noColConn = nil end
        if active then
            noColConn = RunService.Stepped:Connect(function()
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= player and p.Character then
                        for _, part in ipairs(p.Character:GetDescendants()) do
                            if part:IsA("BasePart") and part.CanCollide then part.CanCollide = false end
                        end
                    end
                end
            end)
        end
    end

    local function restoreRepRoot()
        if not safe.repRoot then return end
        if hrp and hrp.Parent and sethiddenproperty then
            pcall(function() sethiddenproperty(hrp, "PhysicsRepRootPart", hrp) end)
        end
        safe.repRoot = false
    end

    local function clearMarker()
        if safe.marker then pcall(function() safe.marker:Destroy() end) safe.marker = nil end
        markedPos = nil
    end

    local function resetSafety(keepMarker)
        safe.lastSafeCF = nil
        safe.ragLatched = false
        if not keepMarker then
            clearMarker()
            safe.markerTarget = nil
            safe.markerGroundCF = nil
        end
        safe.lastPos = nil
        safe.lastT = 0
        safe.recoverUntil = 0
        if hrp and hrp.Parent and hrp.Position.Y > -30 and inX(hrp.Position.X) and inZ(hrp.Position.Z) then
            safe.lastSafeCF = hrp.CFrame
            safe.lastPos = hrp.Position
            safe.lastT = tick()
        end
    end

    local function syncCollision()
        local colOff = ab.on and ab.mode == "V2"
        local active = not colOff
        if ab.on and ab.mode == "Perso" then active = ab.colMode == "V1" end
        if ab.on and ab.mode == "V2" and safe.ragLatched then active = true end
        if not ab.on then active = false end
        setNoPlayerCollision(active)
    end

    -- ---------- бита ----------
    local function getBat()
        local char = player.Character
        if not char then return nil end
        local tool = char:FindFirstChild("Bat")
        if tool then return tool end
        local bp = player:FindFirstChild("Backpack")
        if bp then
            tool = bp:FindFirstChild("Bat")
            if tool then tool.Parent = char return tool end
        end
        return nil
    end

    local function tryHit()
        if ab.hitCd then return end
        ab.hitCd = true
        pcall(function()
            local bat = getBat()
            if bat then
                bat:Activate()
                local ev = bat:FindFirstChildWhichIsA("RemoteEvent")
                if ev then ev:FireServer() end
            end
        end)
        task.delay(0.08, function() ab.hitCd = false end)
    end

    -- ---------- выбор цели ----------
    local function closestPlayer()
        if not hrp then return nil end
        local cp, cd = nil, math.huge
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= player and p.Character then
                local tr = p.Character:FindFirstChild("HumanoidRootPart")
                local ok = tr ~= nil
                if ok and (ab.mode == "V2" or ab.mode == "Perso") then
                    local h = p.Character:FindFirstChildOfClass("Humanoid")
                    local pos = tr.Position
                    ok = h ~= nil and h.Health > 0 and pos.Y >= -30 and pos.Y <= 75 and inX(pos.X) and inZ(pos.Z)
                end
                if ok then
                    local d = (hrp.Position - tr.Position).Magnitude
                    if d < cd then cd = d cp = p end
                end
            end
        end
        return cp, cd
    end

    -- ---------- маркер «последняя позиция» ----------
    local function showMarker(cf)
        clearMarker()
        local m = Instance.new("Part")
        m.Name = "AutoBatLastTargetPosition"
        m.Anchored = true
        m.CanCollide = false
        m.CanTouch = false
        m.CanQuery = false
        m.CastShadow = false
        m.Shape = Enum.PartType.Ball
        m.Size = Vector3.new(2.4, 2.4, 2.4)
        m.Material = Enum.Material.Neon
        m.Color = MARK_COLOR
        m.Transparency = 0.15
        m.CFrame = cf
        local bb = Instance.new("BillboardGui")
        bb.AlwaysOnTop = true
        bb.Size = UDim2.new(0, 150, 0, 34)
        bb.StudsOffset = Vector3.new(0, 2.2, 0)
        bb.Parent = m
        local tl = Instance.new("TextLabel")
        tl.Size = UDim2.fromScale(1, 1)
        tl.BackgroundTransparency = 1
        tl.Text = "LAST POSITION"
        tl.TextColor3 = Color3.new(1, 1, 1)
        tl.TextStrokeTransparency = 0
        tl.Font = Enum.Font.GothamBold
        tl.TextSize = 13
        tl.Parent = bb
        m.Parent = workspace
        safe.marker = m
        markedPos = cf.Position + Vector3.new(0, 1.8, 0)
    end

    local function updateMarker(target)
        if target then
            if target ~= safe.markerTarget then
                clearMarker()
                safe.markerTarget = target
                safe.markerGroundCF = nil
            end
            local tc = target.Character
            local tr = tc and tc:FindFirstChild("HumanoidRootPart")
            local th = tc and tc:FindFirstChildOfClass("Humanoid")
            local v = tr and tr.AssemblyLinearVelocity or Vector3.zero
            local hs = Vector3.new(v.X, 0, v.Z).Magnitude
            if tr and th and th.Health > 0
                and (ab.mode ~= "Perso" or hs <= MAX_TARGET_SPEED)
                and th.FloorMaterial ~= Enum.Material.Air
                and tr.Position.Y >= -30 and tr.Position.Y <= 75
                and inX(tr.Position.X) and inZ(tr.Position.Z) then
                local rp = RaycastParams.new()
                rp.FilterType = Enum.RaycastFilterType.Exclude
                rp.FilterDescendantsInstances = {tc}
                local hit = workspace:Raycast(tr.Position + Vector3.new(0, 1, 0), Vector3.new(0, -8, 0), rp)
                if hit then
                    safe.markerGroundCF = CFrame.new(hit.Position + Vector3.new(0, 1.2, 0))
                    clearMarker()
                end
            end
            return
        end
        local tracked = safe.markerTarget
        local tc = tracked and tracked.Character
        local tr = tc and tc:FindFirstChild("HumanoidRootPart")
        local th = tc and tc:FindFirstChildOfClass("Humanoid")
        if not tr or not th or th.Health <= 0 then
            clearMarker()
            safe.markerTarget = nil
            safe.markerGroundCF = nil
            return
        end
        local p = tr.Position
        local outside = p.Y < -30 or p.Y > 75 or not inX(p.X) or not inZ(p.Z)
        if outside and safe.markerGroundCF and not safe.marker then
            showMarker(safe.markerGroundCF)
        elseif not outside then
            clearMarker()
        end
    end

    -- ---------- защита от падения в бездну (V2) ----------
    local function guardVoid(root, h, targetRoot)
        if not root or not h then return false end
        local now = tick()
        local pos = root.Position
        local vel = root.AssemblyLinearVelocity
        local destroyH = workspace.FallenPartsDestroyHeight or -500
        local voidFloor = math.max(destroyH + 80, -55)
        local suddenDrop = safe.lastPos and (now - (safe.lastT or now)) <= 0.3 and pos.Y < safe.lastPos.Y - 55
        local launched = vel.Y < -140 or vel.Magnitude > 700
        local inVoid = pos.Y <= voidFloor
        local outX = safe.lastSafeCF ~= nil and not inX(pos.X)
        local outZ = safe.lastSafeCF ~= nil and not inZ(pos.Z)
        local recovering = now < (safe.recoverUntil or 0)

        if inVoid or suddenDrop or launched or outX or outZ then
            local rcf = safe.lastSafeCF
            if targetRoot and targetRoot.Parent and targetRoot.Position.Y > voidFloor + 20 then
                local rp = (targetRoot.CFrame * CFrame.new(0, 1.4, 3.8)).Position
                rp = Vector3.new(math.clamp(rp.X, MIN_X, MAX_X), rp.Y, math.clamp(rp.Z, MIN_Z, MAX_Z))
                rcf = CFrame.lookAt(rp, targetRoot.Position + Vector3.new(0, 0.8, 0))
            end
            pcall(function()
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                h.PlatformStand = false
                h.Sit = false
                h.AutoRotate = true
                h:ChangeState(Enum.HumanoidStateType.GettingUp)
                h:ChangeState(Enum.HumanoidStateType.Running)
                if rcf then root.CFrame = rcf end
            end)
            safe.recoverUntil = now + 0.45
            recovering = true
        elseif not recovering and pos.Y > voidFloor + 15 and math.abs(vel.Y) < 85 and inX(pos.X) and inZ(pos.Z) then
            safe.lastSafeCF = root.CFrame
        end
        if recovering then
            pcall(function()
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end)
        end
        safe.lastPos = root.Position
        safe.lastT = now
        return recovering
    end

    local function latchRagdollCollision(targetRoot)
        if safe.ragLatched or not targetRoot or not targetRoot.Parent then return end
        local th = targetRoot.Parent:FindFirstChildOfClass("Humanoid")
        if not th then return end
        local st = th:GetState()
        if st == Enum.HumanoidStateType.Ragdoll or st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.FallingDown then
            safe.ragLatched = true
            setNoPlayerCollision(true)
        end
    end

    -- ---------- персонаж ----------
    local function setupChar(char)
        task.wait(0.1)
        hum = char:WaitForChild("Humanoid", 5)
        hrp = char:WaitForChild("HumanoidRootPart", 5)
        safe.repRoot = false
        resetSafety()
        syncCollision()
    end
    player.CharacterAdded:Connect(setupChar)
    player.CharacterRemoving:Connect(restoreRepRoot)
    if player.Character then task.spawn(setupChar, player.Character) end

    -- ---------- основной цикл ----------
    RunService.Heartbeat:Connect(function()
        if not (hum and hrp and hum.Parent and hrp.Parent) then return end
        local target = nil
        if ab.mode == "V2" or ab.mode == "Perso" or ab.on then
            target = closestPlayer()
        end
        if ab.mode == "V2" or ab.mode == "Perso" then updateMarker(target) end
        if not ab.on then return end

        local tr = target and target.Character and target.Character:FindFirstChild("HumanoidRootPart") or nil
        if not tr and ab.mode == "Perso" then restoreRepRoot() end
        if ab.mode == "V2" then
            local colRoot = tr
            if not colRoot and safe.markerTarget and safe.markerTarget.Character then
                colRoot = safe.markerTarget.Character:FindFirstChild("HumanoidRootPart")
            end
            latchRagdollCollision(colRoot)
            syncCollision()
            if guardVoid(hrp, hum, tr) then return end
        end

        if tr then
            if sethiddenproperty then
                local assigned = pcall(function() sethiddenproperty(hrp, "PhysicsRepRootPart", tr) end)
                if ab.mode == "Perso" then safe.repRoot = assigned end
            end
            if ab.mode == "V2" then
                local dir = tr.Position - hrp.Position
                if dir.Magnitude > 8 then
                    local step = math.min(dir.Magnitude, 18)
                    pcall(function() hrp.CFrame = hrp.CFrame + dir.Unit * step end)
                end
            else
                local tp = tr.Position + Vector3.new(0, 0.9, 0)
                local dist = ab.mode == "Perso" and ab.tpDist or 8
                if (hrp.Position - tp).Magnitude > dist then
                    pcall(function() hrp.CFrame = CFrame.new(tp) end)
                end
            end
            pcall(function()
                local cam = workspace.CurrentCamera
                cam.CFrame = CFrame.new(cam.CFrame.Position, tr.Position)
            end)
            tryHit()
        elseif ab.mode == "Perso" then
            if markedPos and (hrp.Position - markedPos).Magnitude > ab.tpDist then
                pcall(function() hrp.CFrame = CFrame.new(markedPos) end)
            end
        end
    end)

    -- ---------- включение / выключение ----------
    local abVisual = function() end
    local function setEnabled(on)
        on = on == true
        if ab.on == on then return end
        if not on then restoreRepRoot() end
        ab.on = on
        if on then
            -- Auto Bat и TP Bat не работают одновременно
            local tp = Actions.BatV2
            if tp and tp.get and tp.get() then pcall(tp.set, false) end
        end
        resetSafety(true)
        syncCollision()
    end

    -- ---------- панель ----------
    local function newAbPanel(height, order)
        local p = Instance.new("Frame")
        p.Name = "AutoBatPanel"
        p.Size = UDim2.new(1, 0, 0, height)
        p.BackgroundColor3 = COLOR_PANEL
        p.BorderSizePixel = 0
        p.LayoutOrder = order
        p.Parent = currentPage
        Instance.new("UICorner", p).CornerRadius = UDim.new(0, 10)
        local s = Instance.new("UIStroke", p)
        s.Color = COLOR_ACCENT
        s.Thickness = 1.5
        local t = Instance.new("TextLabel")
        t.BackgroundTransparency = 1
        t.Position = UDim2.new(0, 8, 0, 4)
        t.Size = UDim2.new(0, 100, 0, 16)
        t.Text = "AUTO BAT"
        t.Font = Enum.Font.GothamBold
        t.TextSize = 11
        t.TextColor3 = COLOR_BLUE
        t.TextXAlignment = Enum.TextXAlignment.Left
        t.Parent = p
        return p
    end

    local H_SIMPLE, H_PERSO = 98, 176
    local panel = newAbPanel(H_SIMPLE, 6)

    makeLabel(panel, UDim2.new(0, 8, 0, 26), "Auto Bat", UDim2.new(0, 100, 0, 18))
    local _, vis = makeToggle(panel, UDim2.new(1, -44, 0, 26), false, function(v) setEnabled(v) end)
    abVisual = vis

    -- переключатель режима V1 / V2 / Perso
    local function chipRow(y, items, current, onPick)
        local chips = {}
        local w = math.floor((Content.AbsoluteSize.X > 0 and (WIDTH - 38 - RIGHT_W - 10 - 16) or 140) / #items) - 4
        local function paint(sel)
            for i, c in ipairs(chips) do
                local a = items[i] == sel
                c.BackgroundColor3 = a and COLOR_ACCENT_D or COLOR_BG
                c.TextColor3 = a and COLOR_TEXT or COLOR_TEXT_D
                local st = c:FindFirstChildOfClass("UIStroke")
                if st then st.Color = a and COLOR_ACCENT or COLOR_LINE end
            end
        end
        for i, name in ipairs(items) do
            local c = makeChip(panel, UDim2.new(0, 8 + (i - 1) * (w + 4), 0, y), UDim2.new(0, w, 0, 22), name, name == current)
            c.MouseButton1Click:Connect(function()
                paint(name)
                onPick(name)
            end)
            chips[i] = c
        end
        return paint
    end

    local persoRows = {}
    local function applyLayout()
        local perso = ab.mode == "Perso"
        panel.Size = UDim2.new(1, 0, 0, perso and H_PERSO or H_SIMPLE)
        for _, o in ipairs(persoRows) do o.Visible = perso end
    end

    makeLabel(panel, UDim2.new(0, 8, 0, 54), "Mode", UDim2.new(0, 60, 0, 14))
    local paintMode = chipRow(56 + 14, {"V1", "V2", "Perso"}, ab.mode, function(m)
        if ab.mode == "Perso" and m ~= "Perso" then restoreRepRoot() end
        ab.mode = m
        resetSafety()
        syncCollision()
        applyLayout()
    end)

    -- Perso: режим коллизии и дистанция телепорта
    local colLbl = makeLabel(panel, UDim2.new(0, 8, 0, 100), "Collision Mode", UDim2.new(0, 120, 0, 14))
    colLbl.Visible = false
    table.insert(persoRows, colLbl)
    local paintCol
    do
        -- чипы режима коллизии создаём отдельно, чтобы можно было скрывать
        local before = #panel:GetChildren()
        paintCol = chipRow(116, {"V1", "V2"}, ab.colMode, function(m)
            ab.colMode = m
            syncCollision()
        end)
        local kids = panel:GetChildren()
        for i = before + 1, #kids do
            kids[i].Visible = false
            table.insert(persoRows, kids[i])
        end
    end

    local distLbl = makeLabel(panel, UDim2.new(0, 8, 0, 146), "TP Distance", UDim2.new(0, 100, 0, 18))
    distLbl.Visible = false
    table.insert(persoRows, distLbl)
    local distBox = Instance.new("TextBox")
    distBox.Name = "AutoBatDist"
    distBox.Size = UDim2.new(0, 46, 0, 22)
    distBox.Position = UDim2.new(1, -54, 0, 144)
    distBox.BackgroundColor3 = COLOR_BG
    distBox.Text = tostring(ab.tpDist)
    distBox.Font = Enum.Font.GothamBold
    distBox.TextSize = 12
    distBox.TextColor3 = COLOR_TEXT
    distBox.TextXAlignment = Enum.TextXAlignment.Center
    distBox.ClearTextOnFocus = false
    distBox.Visible = false
    distBox.Parent = panel
    Instance.new("UICorner", distBox).CornerRadius = UDim.new(0, 6)
    local dbs = Instance.new("UIStroke", distBox)
    dbs.Color = COLOR_ACCENT
    dbs.Thickness = 1.5
    table.insert(persoRows, distBox)
    distBox:GetPropertyChangedSignal("Text"):Connect(function()
        local t = distBox.Text:gsub("[^%d%.]", "")
        if distBox.Text ~= t then distBox.Text = t end
    end)
    local function applyDist()
        local v = tonumber(distBox.Text)
        if v then
            ab.tpDist = math.clamp(math.floor(v * 10 + 0.5) / 10, 0, 500)
        end
        distBox.Text = tostring(ab.tpDist)
    end
    distBox.FocusLost:Connect(applyDist)
    Flags.apply.AutoBatDist = applyDist

    applyLayout()

    -- для кнопок на экране и сохранения настроек
    Actions.AutoBat = {
        get = function() return ab.on end,
        set = function(v) abVisual(v == true) setEnabled(v == true) end,
    }
    Flags.autoBatMode = {
        get = function() return {mode = ab.mode, col = ab.colMode} end,
        set = function(d)
            if type(d) ~= "table" then return end
            if d.mode == "V1" or d.mode == "V2" or d.mode == "Perso" then
                ab.mode = d.mode
                paintMode(d.mode)
            end
            if d.col == "V1" or d.col == "V2" then
                ab.colMode = d.col
                paintCol(d.col)
            end
            resetSafety()
            syncCollision()
            applyLayout()
        end,
    }
end
currentPage = pages["MAIN"]

-- ================= COMBAT: BAT BYPASS (перенесён из Demon Duels) =================
-- Логика Demon "Bypass Bat": наведение через AngularVelocity, скорость к цели (Bypass Speed),
-- подбор биты и удар в радиусе 12. V2 = полный Aimbot из Zurich Hub (предикт позиции цели). Анти-стак: при включении гасит Auto Left/Right, Auto Bat,
-- TP Bat, Lock Enemy; если любая из них включится позже — Bat Bypass сам выключается.
currentPage = pages["COMBAT"]
do
    local RunService = game:GetService("RunService")
    local LP = player

    local ANG_NAME, ATT_NAME = "_AdaptBP_AngV", "_AdaptBP_Att"
    local CLEAN = {
        "LockBAV", "LockAngVel", "LockBodyAtt", "BatLock", "LockBAVAtt",
        "AutoBatAtt", "AutoBatAV", "AntiAim", "VelocityLock",
    }
    local SWING_RANGE = 22
    local SWING_CD = 0.012
    local SWING_BURST = 14         -- плотный burst → ~95% рег за 1-2 тика
    local AIM_LEAD = 0.28         -- предикт позиции цели (сек)
    local LUNGE_BOOST = 55         -- сильный рывок в хитбокс
    local SNAP_DIST = 7.5          -- подтягивание к цели перед ударом
    local CONFLICTS = {"AutoLeft", "AutoRight", "AutoBat", "BatV2", "LockEnemy", "BatAimbot"}

    local BP = {
        on = false, speed = 60, mode = "V1", runMode = "V1",
        equipped = false, target = nil,
        intended = Vector3.zero,
        angV = nil, att = nil,
        prevAutoRotate = nil,
        lastSwing = 0,
    }
    local hbConn, safeConn, respawnConn = nil, nil, nil
    local setVisual = function() end

    local function isBat(tool)
        if not tool or not tool:IsA("Tool") then return false end
        local n = tool.Name:lower()
        return n:find("bat", 1, true) ~= nil or n:find("slap", 1, true) ~= nil
    end

    local function findBat()
        local char = LP.Character
        if not char then return nil end
        for _, c in ipairs(char:GetChildren()) do
            if isBat(c) then return c end
        end
        local bp = LP:FindFirstChildOfClass("Backpack")
        if bp then
            for _, c in ipairs(bp:GetChildren()) do
                if isBat(c) then return c end
            end
        end
        return nil
    end

    local function cleanRoot(root)
        if not root then return end
        pcall(function()
            for _, n in ipairs(CLEAN) do
                local c = root:FindFirstChild(n)
                if c then c:Destroy() end
            end
            for _, child in ipairs(root:GetChildren()) do
                if child.Name ~= ANG_NAME and child.Name ~= ATT_NAME then
                    local ln = child.Name:lower()
                    if ln:find("lockb") or ln:find("lockangv") or ln:find("batlock")
                        or ln:find("antiaim") or ln:find("velocitylock") then
                        child:Destroy()
                    end
                end
            end
        end)
    end

    local function ensureAngular(parent)
        pcall(function()
            local a = parent:FindFirstChild(ANG_NAME) if a then a:Destroy() end
            local b = parent:FindFirstChild(ATT_NAME) if b then b:Destroy() end
        end)
        local att = Instance.new("Attachment")
        att.Name = ATT_NAME
        att.Parent = parent
        local angV = Instance.new("AngularVelocity")
        angV.Name = ANG_NAME
        angV.Attachment0 = att
        angV.RelativeTo = Enum.ActuatorRelativeTo.World
        angV.MaxTorque = math.huge
        angV.AngularVelocity = Vector3.zero
        angV.Parent = parent
        BP.att, BP.angV = att, angV
    end

    local function removeAngular()
        pcall(function() if BP.angV and BP.angV.Parent then BP.angV:Destroy() end end)
        pcall(function() if BP.att and BP.att.Parent then BP.att:Destroy() end end)
        BP.angV, BP.att = nil, nil
    end

    local function nearest(fromRoot)
        local best, bestDist = nil, math.huge
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LP and plr.Character then
                local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local d = (hrp.Position - fromRoot.Position).Magnitude
                    if d < bestDist then bestDist = d best = hrp end
                end
            end
        end
        return best, bestDist
    end

    local function ragdolled(hum)
        if hum.PlatformStand then return true end
        local st = hum:GetState()
        return st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.FallingDown
    end

    local function anyConflict()
        for _, n in ipairs(CONFLICTS) do
            local a = Actions[n]
            if a and a.get and a.get() then return true end
        end
        return false
    end

    local stopBypass, stopV1 -- объявлены заранее

    local function mainStep()
        if not BP.on then return end
        -- анти-стак: если включили другую функцию движения/наведения — выключаемся
        if anyConflict() then
            stopBypass()
            setVisual(false)
            return
        end
        local char = LP.Character
        local humanoid = char and char:FindFirstChildOfClass("Humanoid")
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root or not humanoid or humanoid.Health <= 0 then return end

        -- Drop Brainrot и рэгдолл: не перебиваем физику
        local drop = Actions.DropBR
        if drop and drop.get and drop.get() then return end
        if ragdolled(humanoid) then
            if BP.angV then BP.angV.AngularVelocity = Vector3.zero end
            return
        end

        cleanRoot(root)
        if not BP.angV or not BP.angV.Parent then ensureAngular(root) end

        if not BP.equipped then
            BP.equipped = true
            if not char:FindFirstChildOfClass("Tool") then
                local b = findBat()
                if b then pcall(function() humanoid:EquipTool(b) end) end
            end
        end

        local target, dist = nearest(root)
        if not target then
            BP.target = nil
            humanoid.AutoRotate = true
            if BP.angV then BP.angV.AngularVelocity = Vector3.zero end
            return
        end
        BP.target = target

        local vel = target.AssemblyLinearVelocity or target.Velocity
        local lead = (AIM_LEAD or 0.12)
        local aimPos = target.Position + vel * lead
            + target.CFrame.LookVector * (vel.Magnitude < 0.1 and 1.2 or 3.5)
        local delta = aimPos - root.Position
        local flat = Vector3.new(delta.X, 0, delta.Z)
        humanoid.AutoRotate = false

        -- поворот только вокруг вертикали (yaw) + постоянное выравнивание тела,
        -- чтобы персонажа не клонило вниз/вперёд при ударе
        local lvl = root.CFrame.UpVector:Cross(Vector3.yAxis) * 20
        if delta.Magnitude > 0.01 and flat.Magnitude > 0.01 then
            local look = root.CFrame.LookVector
            local flatLook = Vector3.new(look.X, 0, look.Z)
            if flatLook.Magnitude < 0.01 then flatLook = flat end
            local yawErr = math.atan2(flatLook.Unit:Cross(flat.Unit).Y, flatLook.Unit:Dot(flat.Unit))
            local rotY = math.clamp(yawErr * 55, -36, 36)
            BP.angV.AngularVelocity = Vector3.new(lvl.X, rotY, lvl.Z)
        else
            BP.angV.AngularVelocity = lvl
        end

        local spd = tonumber(BP.speed) or 58
        if spd ~= spd or spd <= 0 or spd == math.huge then spd = 58 end

        BP.intended =
            (flat.Magnitude > 0.1 and flat.Unit * spd or Vector3.zero)
            + (math.abs(delta.Y) > 0.8
                and Vector3.new(0, math.clamp(delta.Y * 6, -20, 45), 0)
                or Vector3.new(0, -2, 0))
        root.Velocity = BP.intended

        if flat.Magnitude > 0.5 then
            pcall(function() humanoid:Move(flat.Unit, false) end)
        end

        if dist <= SWING_RANGE and tick() - BP.lastSwing >= SWING_CD then
            local bat = char:FindFirstChildOfClass("Tool")
            if not isBat(bat) then bat = findBat() end
            if bat then
                if bat.Parent ~= char then
                    pcall(function() humanoid:EquipTool(bat) end)
                end
                BP.lastSwing = tick()

                -- разворот лицом в цель
                pcall(function()
                    root.CFrame = CFrame.new(root.Position, Vector3.new(aimPos.X, root.Position.Y, aimPos.Z))
                end)

                -- подтягивание в хитбокс (если близко)
                if dist <= (SNAP_DIST or 7.5) + 4 and flat.Magnitude > 0.05 then
                    local snap = math.clamp(dist - 2.2, 0, 4.5)
                    pcall(function()
                        root.CFrame = root.CFrame + flat.Unit * snap * 0.55
                    end)
                end

                -- рывок в цель
                if flat.Magnitude > 0.05 then
                    local lunge = flat.Unit * (LUNGE_BOOST or 55)
                    local vy = math.clamp(delta.Y * 5, -14, 28)
                    root.AssemblyLinearVelocity = Vector3.new(lunge.X, vy, lunge.Z)
                    root.Velocity = Vector3.new(lunge.X, vy, lunge.Z)
                end

                -- 2 волны Activate: мгновенная + короткая (без блокировки Heartbeat надолго)
                task.spawn(function()
                    for _ = 1, (SWING_BURST or 14) do
                        pcall(function() bat:Activate() end)
                    end
                    task.wait(0.02)
                    for _ = 1, 8 do
                        pcall(function() bat:Activate() end)
                    end
                    -- добивание если всё ещё рядом
                    if BP.target and BP.target.Parent then
                        local d2 = (BP.target.Position - root.Position).Magnitude
                        if d2 <= 12 then
                            task.wait(0.015)
                            for _ = 1, 6 do
                                pcall(function() bat:Activate() end)
                            end
                        end
                    end
                end)
            end
        end
    end

    local function safetyStep()
        if not BP.on then return end
        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local v = root.Velocity
        if math.abs(v.X) > 350 or math.abs(v.Z) > 350 then
            root.Velocity = BP.intended
        end
        cleanRoot(root)
    end


    -- ================= V2: ПОЛНЫЙ AIMBOT (перенесён из Zurich Hub) =================
    -- предсказание позиции цели (пинг, ускорение, прыжки/воздух), наведение и удар битой.
    -- Упаковано в отдельную функцию, чтобы не упереться в лимит локальных переменных.
    local AIM = {speed = 55}
    local AimV2 = {}
    local function aimActive() return BP.on and BP.runMode == "V2" end
    local function backpackTools()
        local bp = LP:FindFirstChildOfClass("Backpack")
        return bp and bp:GetChildren() or {}
    end
    local pingToken = 0
    ;(function()
        local Stats = game:GetService("Stats")
            local C0 = {
            predictionSphere = nil,
            targetPlayer = nil,
            lastTargetPos = nil,
            targetVelocity = Vector3.new(0,0,0),
            smoothedVelocity = Vector3.new(0,0,0),
            velocityHistory = {},
            MAX_HISTORY = 8,
            airborneTime = 0,
            lastActivationTime = 0,
            highYVelocityTime = 0,
            pingHistory = {},
            currentPing = 0.1,
            accelerationHistory = {},
            MAX_ACCEL_HISTORY = 4,
            lastDirectionChangeTime = 0,
            previousDirection = nil,
            wasAirborne = false,
            aerialVelocityHistory = {},
            MAX_AERIAL_HISTORY = 6,
            aerialSmoothVelocity = Vector3.new(0,0,0),
            lastYVelocity = 0,
            peakHeight = 0,
            groundHeight = 0,
            lastJumpTime = 0,
            isMultiJumping = false,
            verticalVelocityHistory = {},
            MAX_VERTICAL_HISTORY = 5,
            lastGroundedPosition = nil,
            realPingMs = 0,
            }
            local CFG0 = {
            FOLLOW_SPEED = 55,
            ACTIVATE_DISTANCE = 13,
            MIN_FOLLOW_DISTANCE = 1,
            PREDICTION_TIME = 0.22,
            PREDICT_AHEAD = 3,
            JUMP_SPEED_BOOST = 1.5,
            JUMP_THRESHOLD = 8,
            MAX_SPEED = 59,
            ACTIVATION_DELAY = 0.2,
            AIRBORNE_THRESHOLD = 0.15,
            FLOAT_Y_THRESHOLD = 3,
            FALLING_THRESHOLD = -8,
            RISING_THRESHOLD = 8,
            VERTICAL_OFFSET_MULTIPLIER = 0.15,
            JUMPBOOST_Y_THRESHOLD = 35,
            EXTREME_JUMPBOOST_THRESHOLD = 50,
            JUMPBOOST_SUSTAINED_TIME = 0.15,
            MAX_VELOCITY_CHANGE = 150,
            VELOCITY_SMOOTHING = 0.2,
            MAX_HORIZONTAL_VELOCITY = 80,
            ERRATIC_MOVEMENT_THRESHOLD = 3,
            SERVER_TICKRATE = 1/60,
            PING_SAMPLE_SIZE = 10,
            MIN_PING_COMPENSATION = 0.03,
            MAX_PING_COMPENSATION = 0.25,
            ACCELERATION_PREDICTION_WEIGHT = 0.3,
            DIRECTION_CHANGE_DETECTION_TIME = 0.12,
            QUICK_DIRECTION_CHANGE_MULTIPLIER = 1.5,
            GRAVITY = 196.2,
            AIR_CONTROL_FACTOR = 0.8,
            AERIAL_VELOCITY_DECAY = 0.95,
            AERIAL_DIRECTION_CHANGE_WEIGHT = 0.6,
            MIN_AIRBORNE_TIME = 0.08,
            AERIAL_SMOOTHING = 0.15,
            PEAK_JUMP_THRESHOLD = 3,
            AERIAL_PREDICTION_BOOST = 1.2,
            STRAFE_DETECTION_THRESHOLD = 0.7,
            HIGH_JUMP_THRESHOLD = 20,
            FALLING_SPEED_THRESHOLD = -15,
            GRAVITY_PREDICTION_WEIGHT = 1.0,
            MULTI_JUMP_DETECTION_WINDOW = 0.2,
            UPWARD_VELOCITY_RESET_THRESHOLD = 10,
            VERTICAL_POSITION_LEAD = 2.5,
            FALLING_VERTICAL_LEAD = 3.5,
            SPHERE_SMOOTH_SPEED = 15,
            }
            local CFG = CFG0
            local C = C0
            local function updatePing()
            local pingSeconds = C.realPingMs/1000
            table.insert(C.pingHistory, pingSeconds)
            if #C.pingHistory > CFG.PING_SAMPLE_SIZE then table.remove(C.pingHistory,1) end
            local sum = 0; for _,p in ipairs(C.pingHistory) do sum = sum + p end
            C.currentPing = sum / #C.pingHistory
            C.currentPing = math.clamp(C.currentPing, CFG.MIN_PING_COMPENSATION, CFG.MAX_PING_COMPENSATION)
            end
            local function getNearestPlayer()
            local char = LP.Character; if not char then return nil end
            local root = char:FindFirstChild("HumanoidRootPart"); if not root then return nil end
            local myPos = root.Position; local nearestDist = math.huge; local nearestPlayer = nil
            for _,p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
            local otherRoot = p.Character:FindFirstChild("HumanoidRootPart")
            if otherRoot then local dist = (myPos - otherRoot.Position).Magnitude; if dist < nearestDist then nearestDist = dist; nearestPlayer = p end end
            end
            end
            return nearestPlayer
            end

            local function getAverageVelocity()
            if #C.velocityHistory == 0 then return Vector3.new(0,0,0) end
            local sum = Vector3.new(0,0,0)
            for _,vel in ipairs(C.velocityHistory) do sum = sum + vel end
            return sum / #C.velocityHistory
            end

            local function getAverageAcceleration()
            if #C.accelerationHistory == 0 then return Vector3.new(0,0,0) end
            local sum = Vector3.new(0,0,0)
            for _,a in ipairs(C.accelerationHistory) do sum = sum + a end
            return sum / #C.accelerationHistory
            end

            local function getAverageAerialVelocity()
            if #C.aerialVelocityHistory == 0 then return Vector3.new(0,0,0) end
            local sum = Vector3.new(0,0,0)
            for _,vel in ipairs(C.aerialVelocityHistory) do
            sum = sum + Vector3.new(vel.X, 0, vel.Z)
            end
            return sum / #C.aerialVelocityHistory
            end

            local function getAverageVerticalVelocity()
            if #C.verticalVelocityHistory == 0 then return 0 end
            local sum = 0
            for _,y in ipairs(C.verticalVelocityHistory) do sum = sum + y end
            return sum / #C.verticalVelocityHistory
            end

            local function detectMultiJump(currentYVel, wasRising)
            local t = tick()
            if C.lastYVelocity < -5 and currentYVel > CFG.UPWARD_VELOCITY_RESET_THRESHOLD then
            if t - C.lastJumpTime < CFG.MULTI_JUMP_DETECTION_WINDOW then return true end
            C.lastJumpTime = t; return true
            end
            return false
            end

            local function isFallingFromHeight(currentPos, yVel)
            return (currentPos.Y - C.groundHeight > CFG.HIGH_JUMP_THRESHOLD) and yVel < CFG.FALLING_SPEED_THRESHOLD
            end

            local function isAerialStrafing()
            if #C.aerialVelocityHistory < 3 then return false end
            local dc = 0
            for i = 2, #C.aerialVelocityHistory do
            local v1 = Vector3.new(C.aerialVelocityHistory[i-1].X, 0, C.aerialVelocityHistory[i-1].Z)
            local v2 = Vector3.new(C.aerialVelocityHistory[i].X, 0, C.aerialVelocityHistory[i].Z)
            if v1.Magnitude > 3 and v2.Magnitude > 3 then
            if v1.Unit:Dot(v2.Unit) < CFG.STRAFE_DETECTION_THRESHOLD then dc = dc + 1 end
            end
            end
            return dc >= 2
            end

            local function detectDirectionChange(currentVel)
            local horizontal = Vector3.new(currentVel.X, 0, currentVel.Z)
            if horizontal.Magnitude < 5 then return false end
            if C.previousDirection then
            local dot = C.previousDirection:Dot(horizontal.Unit)
            if dot < 0.5 then
            local t = tick()
            if t - C.lastDirectionChangeTime < CFG.DIRECTION_CHANGE_DETECTION_TIME then
            C.previousDirection = horizontal.Unit
            C.lastDirectionChangeTime = t
            return true
            end
            C.lastDirectionChangeTime = t
            end
            end
            C.previousDirection = horizontal.Unit
            return false
            end

            local function isErraticMovement()
            if #C.velocityHistory < 3 then return false end
            local changes = 0
            for i = 2, #C.velocityHistory do
            local v1 = Vector3.new(C.velocityHistory[i-1].X, 0, C.velocityHistory[i-1].Z)
            local v2 = Vector3.new(C.velocityHistory[i].X, 0, C.velocityHistory[i].Z)
            if v1.Magnitude > 5 and v2.Magnitude > 5 then
            if v1.Unit:Dot(v2.Unit) < 0.3 then changes = changes + 1 end
            end
            end
            return changes >= CFG.ERRATIC_MOVEMENT_THRESHOLD
            end

            local function isInfiniteJumping()
            if #C.velocityHistory < 3 then return false end
            local yc = 0
            for i = 2, #C.velocityHistory do
            if math.abs(C.velocityHistory[i].Y - C.velocityHistory[i-1].Y) > 15 then yc = yc + 1 end
            end
            return yc >= 2
            end

            local function isJumpBoostCheat()
            return math.abs(C.targetVelocity.Y) > CFG.JUMPBOOST_Y_THRESHOLD and C.highYVelocityTime > CFG.JUMPBOOST_SUSTAINED_TIME
            end

            local function isExtremeJumpBoost()
            return math.abs(C.targetVelocity.Y) > CFG.EXTREME_JUMPBOOST_THRESHOLD
            end

            local function isFloating()
            return C.airborneTime > CFG.AIRBORNE_THRESHOLD and math.abs(C.targetVelocity.Y) > CFG.FLOAT_Y_THRESHOLD
            end

            local function checkAirborne(targetRoot)
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = {C.targetPlayer.Character, LP.Character}
            local rayResult = workspace:Raycast(targetRoot.Position, Vector3.new(0,-100,0), params)
            if rayResult then C.groundHeight = rayResult.Position.Y; return false end
            return true
            end

            local function clampVelocityChange(newVel, oldVel, maxChange)
            local delta = newVel - oldVel
            if delta.Magnitude > maxChange then return oldVel + (delta.Unit * maxChange) end
            return newVel
            end

            local function smoothVelocity(current, target, alpha)
            return current:Lerp(target, alpha)
            end

            local function predictAerialPosition(currentPos, velocity, dt, isStrafing, isFastFalling, isMultiJump)
            local horizVel = Vector3.new(velocity.X, 0, velocity.Z)
            local vertVel = velocity.Y
            if isStrafing then
            local avgAerial = getAverageAerialVelocity()
            horizVel = Vector3.new(avgAerial.X, 0, avgAerial.Z) * CFG.AIR_CONTROL_FACTOR
            else
            horizVel = horizVel * CFG.AIR_CONTROL_FACTOR
            end
            horizVel = horizVel * CFG.AERIAL_VELOCITY_DECAY
            local gravityEffect = CFG.GRAVITY * CFG.GRAVITY_PREDICTION_WEIGHT
            if isMultiJump then gravityEffect = gravityEffect * 0.3; vertVel = vertVel * 0.9 end
            local verticalDisplacement
            if isFastFalling then
            verticalDisplacement = (vertVel * dt) - (0.5 * gravityEffect * 1.2 * dt * dt) - (CFG.FALLING_VERTICAL_LEAD * dt)
            else
            verticalDisplacement = (vertVel * dt) - (0.5 * gravityEffect * dt * dt)
            end
            if vertVel > CFG.RISING_THRESHOLD and not isMultiJump then
            verticalDisplacement = verticalDisplacement + (CFG.VERTICAL_POSITION_LEAD * dt)
            end
            return currentPos + horizVel * dt + Vector3.new(0, verticalDisplacement, 0)
            end

            local function predictServerPosition(currentPos, velocity, acceleration, ping, isQuickTurn, isAerial, isStrafing, isFastFalling, isMultiJump)
            local serverDelay = ping + CFG.SERVER_TICKRATE
            if isQuickTurn then serverDelay = serverDelay * CFG.QUICK_DIRECTION_CHANGE_MULTIPLIER end
            if isAerial then
            return predictAerialPosition(currentPos, velocity, serverDelay, isStrafing, isFastFalling, isMultiJump)
            end
            local predictedPos = currentPos + velocity * serverDelay
            if acceleration.Magnitude > 1 then
            predictedPos = predictedPos + (acceleration * CFG.ACCELERATION_PREDICTION_WEIGHT) * (serverDelay * serverDelay * 0.5)
            end
            return predictedPos
            end

            local function createPredictionSphere()
            if C.predictionSphere then C.predictionSphere:Destroy() end
            C.predictionSphere = Instance.new("Part")
            C.predictionSphere.Name = "PredictionSphere"
            C.predictionSphere.Shape = Enum.PartType.Ball
            C.predictionSphere.Size = Vector3.new(2,2,2)
            C.predictionSphere.Anchored = true
            C.predictionSphere.CanCollide = false
            C.predictionSphere.Material = Enum.Material.Neon
            local visualAccent = Color3.fromRGB(0,120,240)
            local visualOutline = Color3.fromRGB(245,248,255)
            C.predictionSphere.Color = visualAccent
            C.predictionSphere.Transparency = 0.4
            local light = Instance.new("PointLight")
            light.Color = visualAccent
            light.Range = 8
            light.Brightness = 2
            light.Parent = C.predictionSphere
            local outline = Instance.new("Highlight")
            outline.FillTransparency = 1
            outline.OutlineColor = visualOutline
            outline.OutlineTransparency = 0
            outline.Parent = C.predictionSphere
            C.predictionSphere.Parent = workspace
            return C.predictionSphere
            end

            local function updatePredictionSphere(targetPosition, dt)
            if not C.predictionSphere then return end
            local alpha = math.min(1, dt * CFG.SPHERE_SMOOTH_SPEED)
            C.predictionSphere.CFrame = C.predictionSphere.CFrame:Lerp(CFrame.new(targetPosition), alpha)
            end

            local function updateRotationAngular(lookDirection, rootPart)
            if not rootPart then return end
            if lookDirection.Magnitude < 0.01 then return end
            local currentLook = rootPart.CFrame.LookVector
            local targetDir = lookDirection.Unit
            local axis = currentLook:Cross(targetDir)
            local angle = math.asin(math.clamp(axis.Magnitude, -1, 1))
            if axis.Magnitude > 0.01 then
            local rotSpeed = 80
            rootPart.AssemblyAngularVelocity = axis.Unit * angle * rotSpeed
            else
            rootPart.AssemblyAngularVelocity = Vector3.zero
            end
            end
local aimConn = nil
            local function aimGetBat()
            local char = LP.Character
            if char then
            local equippedTool = char:FindFirstChildOfClass("Tool")
            if equippedTool then return equippedTool end
            for _, tool in ipairs(backpackTools()) do
            if tool:IsA("Tool") and tool.Name:lower():find("bat") then return tool end
            end
            for _, tool in ipairs(backpackTools()) do
            if tool:IsA("Tool") then return tool end
            end
            end
            return nil
            end
            local function aimStart(char)
            local humanoid = char:FindFirstChildOfClass("Humanoid")
            local rootPart = char:FindFirstChild("HumanoidRootPart")
            if not humanoid or not rootPart then return end
            humanoid.AutoRotate = false
            local bat = aimGetBat()
            if bat and bat.Parent ~= char then humanoid:EquipTool(bat) end
            if not C.predictionSphere then createPredictionSphere() end
            if aimConn then aimConn:Disconnect() end
            aimConn = RunService.RenderStepped:Connect(function(dt)
            if not aimActive() then
            if aimConn then aimConn:Disconnect(); aimConn = nil end
            return
            end
            if anyConflict() then
            AimV2.abort()
            return
            end
            if humanoid.Health <= 0 or humanoid.PlatformStand then return end
            local dropAct = Actions.DropBR
            if dropAct and dropAct.get and dropAct.get() then return end
            local markedPosition = _G.__abatV2MarkedPosition
            if markedPosition then
            local markedDirection = markedPosition - rootPart.Position
            if C.predictionSphere then C.predictionSphere.Transparency = 0.4 end
            if markedDirection.Magnitude > 0.1 then updateRotationAngular(markedDirection, rootPart) end
            if markedDirection.Magnitude > CFG.MIN_FOLLOW_DISTANCE then
            local markedSpeed = tonumber(AIM.speed) or CFG.FOLLOW_SPEED
            rootPart.AssemblyLinearVelocity = markedDirection.Unit * math.clamp(markedSpeed, 1, 120)
            else
            rootPart.AssemblyLinearVelocity = Vector3.zero
            end
            return
            end
            C.targetPlayer = getNearestPlayer()
            if not C.targetPlayer or not C.targetPlayer.Character then
            if C.predictionSphere then C.predictionSphere.Transparency = 0.4 end
            C.targetPlayer = nil
            C.lastTargetPos = nil
            C.targetVelocity = Vector3.zero
            C.smoothedVelocity = Vector3.zero
            C.velocityHistory = {}
            C.accelerationHistory = {}
            C.aerialVelocityHistory = {}
            C.verticalVelocityHistory = {}
            C.aerialSmoothVelocity = Vector3.zero
            C.airborneTime = 0
            C.highYVelocityTime = 0
            C.previousDirection = nil
            C.wasAirborne = false
            C.lastYVelocity = 0
            C.peakHeight = 0
            C.isMultiJumping = false
            return
            end
            local targetRoot = C.targetPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not targetRoot then
            if C.predictionSphere then C.predictionSphere.Transparency = 0.4 end
            return
            end
            if C.predictionSphere then C.predictionSphere.Transparency = 0.4 end
            local targetPos = targetRoot.Position
            local myPos = rootPart.Position
            if C.lastTargetPos then
            local deltaPos = targetPos - C.lastTargetPos
            local rawVelocity = deltaPos / dt
            rawVelocity = clampVelocityChange(rawVelocity, C.targetVelocity, CFG.MAX_VELOCITY_CHANGE)
            local horizontalVel = Vector3.new(rawVelocity.X, 0, rawVelocity.Z)
            if horizontalVel.Magnitude > CFG.MAX_HORIZONTAL_VELOCITY then
            horizontalVel = horizontalVel.Unit * CFG.MAX_HORIZONTAL_VELOCITY
            rawVelocity = Vector3.new(horizontalVel.X, rawVelocity.Y, horizontalVel.Z)
            end
            local currentAcceleration = (rawVelocity - C.targetVelocity) / dt
            table.insert(C.accelerationHistory, currentAcceleration)
            if #C.accelerationHistory > C.MAX_ACCEL_HISTORY then table.remove(C.accelerationHistory, 1) end
            table.insert(C.verticalVelocityHistory, rawVelocity.Y)
            if #C.verticalVelocityHistory > C.MAX_VERTICAL_HISTORY then table.remove(C.verticalVelocityHistory, 1) end
            C.targetVelocity = rawVelocity
            C.smoothedVelocity = smoothVelocity(C.smoothedVelocity, C.targetVelocity, CFG.VELOCITY_SMOOTHING)
            table.insert(C.velocityHistory, C.targetVelocity)
            if #C.velocityHistory > C.MAX_HISTORY then table.remove(C.velocityHistory, 1) end
            end
            C.lastTargetPos = targetPos
            if math.abs(C.targetVelocity.Y) > CFG.JUMPBOOST_Y_THRESHOLD then
            C.highYVelocityTime = C.highYVelocityTime + dt
            else
            C.highYVelocityTime = 0
            end
            local isAirborne = checkAirborne(targetRoot)
            if isAirborne then
            C.airborneTime = C.airborneTime + dt
            if targetPos.Y > C.peakHeight then C.peakHeight = targetPos.Y end
            if C.airborneTime >= CFG.MIN_AIRBORNE_TIME then
            table.insert(C.aerialVelocityHistory, C.targetVelocity)
            if #C.aerialVelocityHistory > C.MAX_AERIAL_HISTORY then table.remove(C.aerialVelocityHistory, 1) end
            C.aerialSmoothVelocity = smoothVelocity(C.aerialSmoothVelocity, C.targetVelocity, CFG.AERIAL_SMOOTHING)
            end
            C.wasAirborne = true
            else
            C.airborneTime = 0
            C.wasAirborne = false
            C.aerialVelocityHistory = {}
            C.aerialSmoothVelocity = Vector3.zero
            C.lastGroundedPosition = targetPos
            C.peakHeight = 0
            end
            local isJumping = math.abs(C.targetVelocity.Y) > CFG.JUMP_THRESHOLD
            local isInfJump = isInfiniteJumping()
            local isFloater = isFloating()
            local isJumpBoost = isJumpBoostCheat()
            local isExtremeBoost = isExtremeJumpBoost()
            local isErratic = isErraticMovement()
            local avgVelocity = getAverageVelocity()
            local avgAcceleration = getAverageAcceleration()
            local isQuickTurn = detectDirectionChange(C.targetVelocity)
            local isStrafing = isAerialStrafing()
            local isTrulyAirborne = isAirborne and C.airborneTime >= CFG.MIN_AIRBORNE_TIME
            local wasRising = C.lastYVelocity > CFG.RISING_THRESHOLD
            C.isMultiJumping = detectMultiJump(C.targetVelocity.Y, wasRising)
            local isFastFalling = isFallingFromHeight(targetPos, C.targetVelocity.Y)
            local avgYVel = getAverageVerticalVelocity()
            C.lastYVelocity = C.targetVelocity.Y
            local predictionVel = C.targetVelocity
            local predictionAccel = avgAcceleration
            local useCurrentPos = false
            if isExtremeBoost then
            useCurrentPos = true
            predictionVel = Vector3.new(avgVelocity.X, 0, avgVelocity.Z)
            predictionAccel = Vector3.zero
            elseif isJumpBoost then
            local avgH = Vector3.new(avgVelocity.X, 0, avgVelocity.Z)
            predictionVel = Vector3.new(avgH.X, C.targetVelocity.Y * 0.15, avgH.Z)
            predictionAccel = Vector3.new(avgAcceleration.X, 0, avgAcceleration.Z)
            elseif isInfJump or isFloater then
            local avgH = Vector3.new(avgVelocity.X, 0, avgVelocity.Z)
            predictionVel = Vector3.new(avgH.X, C.targetVelocity.Y * 0.5, avgH.Z)
            predictionAccel = Vector3.new(avgAcceleration.X * 0.5, 0, avgAcceleration.Z * 0.5)
            elseif isTrulyAirborne and isStrafing then
            local avgAerial = getAverageAerialVelocity()
            predictionVel = Vector3.new(
            C.aerialSmoothVelocity.X * CFG.AERIAL_DIRECTION_CHANGE_WEIGHT + avgAerial.X * (1 - CFG.AERIAL_DIRECTION_CHANGE_WEIGHT),
            avgYVel,
            C.aerialSmoothVelocity.Z * CFG.AERIAL_DIRECTION_CHANGE_WEIGHT + avgAerial.Z * (1 - CFG.AERIAL_DIRECTION_CHANGE_WEIGHT)
            )
            predictionAccel = Vector3.new(avgAcceleration.X * 0.3, 0, avgAcceleration.Z * 0.3)
            elseif isTrulyAirborne then
            predictionVel = Vector3.new(C.aerialSmoothVelocity.X, avgYVel, C.aerialSmoothVelocity.Z)
            predictionAccel = Vector3.zero
            elseif isErratic then
            predictionVel = Vector3.new(C.smoothedVelocity.X, C.targetVelocity.Y, C.smoothedVelocity.Z)
            predictionAccel = Vector3.new(avgAcceleration.X * 0.7, 0, avgAcceleration.Z * 0.7)
            end
            local serverPredictedPos
            if useCurrentPos then
            serverPredictedPos = targetPos
            else
            serverPredictedPos = predictServerPosition(targetPos, predictionVel, predictionAccel, C.currentPing, isQuickTurn, isTrulyAirborne, isStrafing, isFastFalling, C.isMultiJumping)
            end
            local predTime = CFG.PREDICTION_TIME * 1.1
            if isErratic then predTime = predTime * 0.6
            elseif isQuickTurn then predTime = predTime * 1.2
            elseif isTrulyAirborne and isStrafing then predTime = predTime * 0.7
            elseif isTrulyAirborne and isFastFalling then predTime = predTime * 1.3
            elseif isTrulyAirborne then predTime = predTime * 0.85 end
            local predictedPos
            if isTrulyAirborne then
            predictedPos = predictAerialPosition(serverPredictedPos, predictionVel, predTime, isStrafing, isFastFalling, C.isMultiJumping)
            else
            predictedPos = serverPredictedPos + predictionVel * predTime
            end
            local verticalOffset = Vector3.new(0,0,0)
            if not isTrulyAirborne and not isExtremeBoost and not isJumpBoost and not isInfJump then
            if C.targetVelocity.Y < CFG.FALLING_THRESHOLD then
            verticalOffset = Vector3.new(0, C.targetVelocity.Y * CFG.VERTICAL_OFFSET_MULTIPLIER, 0)
            elseif C.targetVelocity.Y > CFG.RISING_THRESHOLD then
            verticalOffset = Vector3.new(0, C.targetVelocity.Y * CFG.VERTICAL_OFFSET_MULTIPLIER, 0)
            end
            end
            predictedPos = predictedPos + verticalOffset
            local interceptOffset = Vector3.new(0,0,0)
            local horizontalVel = Vector3.new(predictionVel.X, 0, predictionVel.Z)
            if horizontalVel.Magnitude > 1 and not useCurrentPos then
            interceptOffset = horizontalVel.Unit * CFG.PREDICT_AHEAD
            end
            local interceptPoint = predictedPos + interceptOffset
            updatePredictionSphere(interceptPoint, dt)
            local toTarget = interceptPoint - myPos
            if toTarget.Magnitude > 0.1 then updateRotationAngular(toTarget, rootPart) end
            local actualDistance = (targetPos - myPos).Magnitude
            if actualDistance <= CFG.ACTIVATE_DISTANCE then
            local currentTime = tick()
            if currentTime - C.lastActivationTime >= 0.3 then
            if useCurrentPos or (isErratic and not isTrulyAirborne) then
            interceptPoint = serverPredictedPos
            elseif isTrulyAirborne then
            interceptPoint = predictAerialPosition(serverPredictedPos, predictionVel, CFG.ACTIVATION_DELAY, isStrafing, isFastFalling, C.isMultiJumping)
            else
            interceptPoint = serverPredictedPos + predictionVel * CFG.ACTIVATION_DELAY
            end
            local tool = char:FindFirstChildOfClass("Tool")
            if tool then tool:Activate() end
            C.lastActivationTime = currentTime
            end
            end
            local direction = interceptPoint - myPos
            if direction.Magnitude > CFG.MIN_FOLLOW_DISTANCE then
            local dirUnit = direction.Unit
            local currentSpeed = tonumber(AIM.speed) or CFG.FOLLOW_SPEED
            currentSpeed = math.clamp(currentSpeed, 1, 120)
            rootPart.AssemblyLinearVelocity = dirUnit * currentSpeed
            else
            rootPart.AssemblyLinearVelocity = Vector3.new(0, rootPart.AssemblyLinearVelocity.Y * 0.5, 0)
            end
            end)
            end
            local function aimStop()
            if aimConn then aimConn:Disconnect(); aimConn = nil end
            if C.predictionSphere then C.predictionSphere:Destroy(); C.predictionSphere = nil end
            local char = LP.Character
            if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then hum.AutoRotate = true end
            local root = char:FindFirstChild("HumanoidRootPart")
            if root then root.AssemblyAngularVelocity = Vector3.zero end
            end
            C.targetPlayer = nil
            C.lastTargetPos = nil
            C.targetVelocity = Vector3.zero
            C.smoothedVelocity = Vector3.zero
            C.velocityHistory = {}
            C.accelerationHistory = {}
            C.aerialVelocityHistory = {}
            C.verticalVelocityHistory = {}
            C.aerialSmoothVelocity = Vector3.zero
            C.airborneTime = 0
            C.highYVelocityTime = 0
            C.previousDirection = nil
            C.wasAirborne = false
            C.lastYVelocity = 0
            C.peakHeight = 0
            C.groundHeight = 0
            C.isMultiJumping = false
            C.lastActivationTime = 0
            end

        local function pingLoop(my)
            task.spawn(function()
                while my == pingToken do
                    pcall(function()
                        local okP, val = pcall(function() return LP:GetNetworkPing() * 1000 end)
                        if okP and type(val) == "number" and val > 0 then C.realPingMs = val return end
                        local ok2, val2 = pcall(function() return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
                        if ok2 and type(val2) == "number" then C.realPingMs = math.floor(val2) end
                    end)
                    task.wait(0.5)
                end
            end)
            task.spawn(function()
                while my == pingToken do
                    task.wait(0.5)
                    pcall(updatePing)
                end
            end)
        end

        AimV2.start = function(char)
            pingToken = pingToken + 1
            pingLoop(pingToken)
            aimStart(char)
        end
        AimV2.stop = function()
            pingToken = pingToken + 1
            aimStop()
        end
        AimV2.abort = function()
            if BP.on and BP.runMode == "V2" then
                stopBypass()
                setVisual(false)
            end
        end
    end)()

    local function startV1()
        if BP.on then return end
        -- анти-стак: гасим всё, что двигает/вращает персонажа
        for _, n in ipairs(CONFLICTS) do
            local a = Actions[n]
            if a and a.get and a.get() then pcall(a.set, false) end
        end
        BP.on = true
        BP.equipped = false
        BP.target = nil
        BP.intended = Vector3.zero
        BP.lastSwing = 0

        local char0 = LP.Character
        local hum0 = char0 and char0:FindFirstChildOfClass("Humanoid")
        local root0 = char0 and char0:FindFirstChild("HumanoidRootPart")
        if hum0 and BP.prevAutoRotate == nil then BP.prevAutoRotate = hum0.AutoRotate end
        if root0 then
            cleanRoot(root0)
            ensureAngular(root0)
        end

        hbConn = RunService.Heartbeat:Connect(mainStep)
        safeConn = RunService.RenderStepped:Connect(safetyStep)
        respawnConn = LP.CharacterAdded:Connect(function(character)
            task.wait(0.5)
            BP.equipped = false
            BP.target = nil
            if BP.on then
                local root = character:WaitForChild("HumanoidRootPart", 5)
                if root then
                    cleanRoot(root)
                    ensureAngular(root)
                end
            end
        end)
    end

    stopV1 = function()
        if not BP.on then return end
        BP.on = false
        if hbConn then hbConn:Disconnect() hbConn = nil end
        if safeConn then safeConn:Disconnect() safeConn = nil end
        if respawnConn then respawnConn:Disconnect() respawnConn = nil end
        BP.equipped = false
        BP.target = nil

        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if root then pcall(function() root.Velocity = root.Velocity * 0.3 end) end
        if root then
            pcall(function()
                local lk = root.CFrame.LookVector
                local fl = Vector3.new(lk.X, 0, lk.Z)
                if fl.Magnitude > 0.01 then
                    root.CFrame = CFrame.lookAt(root.Position, root.Position + fl)
                end
            end)
        end
        if hum then
            hum.AutoRotate = (BP.prevAutoRotate == nil) and true or BP.prevAutoRotate
            hum.PlatformStand = false
            pcall(function() hum:ChangeState(Enum.HumanoidStateType.Running) end)
        end
        BP.prevAutoRotate = nil
        if BP.angV then pcall(function() BP.angV.AngularVelocity = Vector3.zero end) end
        removeAngular()
        if root then
            local a = root:FindFirstChild(ANG_NAME) if a then a:Destroy() end
            local at = root:FindFirstChild(ATT_NAME) if at then at:Destroy() end
            pcall(function()
                root.AssemblyLinearVelocity = Vector3.new(0, -0.1, 0)
                root.AssemblyAngularVelocity = Vector3.zero
            end)
        end
    end


    -- ---------- V2: запуск / остановка ----------
    local function startV2()
        if BP.on then return end
        for _, n in ipairs(CONFLICTS) do
            local a = Actions[n]
            if a and a.get and a.get() then pcall(a.set, false) end
        end
        BP.on = true
        BP.runMode = "V2"
        local char0 = LP.Character
        if char0 then AimV2.start(char0) end
        respawnConn = LP.CharacterAdded:Connect(function(character)
            task.wait(0.5)
            if BP.on and BP.runMode == "V2" then AimV2.start(character) end
        end)
    end

    local function stopV2()
        if not BP.on then return end
        BP.on = false
        if respawnConn then respawnConn:Disconnect() respawnConn = nil end
        AimV2.stop()
    end

    -- ---------- V3: BYPASS BAT — полный перенос из KSK OP ----------
    -- Полностью самостоятельный режим: свои имена AngularVelocity, свой список чистки, своя скорость,
    -- своё состояние (KV3). Не использует данные/функции V1 и V2, поэтому с ними не стакается.
    local KV3_ANG, KV3_ATT = "_KSKBP_AngV", "_KSKBP_Att"
    local KV3_CLEAN = {
        "LockBAV", "LockAngVel", "LockBodyAtt", "BatLock", "LockBAVAtt",
        "AutoBatAtt", "AutoBatAV", "AntiBatDet", "AntiAim", "VelocityLock",
    }
    local KV3_SWING_RANGE = 15     -- радиус удара (в KSK было 12) — бьём чуть раньше, чтобы попасть с 1 тика
    local KV3_SNAP_DIST   = 9      -- ближе этого: прямой рывок в хитбокс цели
    local KV3_STAND       = 3.5    -- держимся на этой дистанции от цели и не врезаемся в неё (бита бьёт на 15)
    local KV3_BRAKE       = 12     -- чем больше, тем резче торможение при подходе
    local KV3_MAXV        = 1.15   -- потолок скорости относительно V3 Speed (учитывая скорость цели)
    local KV3_BURST       = 6      -- сколько Activate/FireServer за один тик
    local KV3_SWING_CD    = 0.04   -- минимальная пауза между сериями
    local KV3_ping        = 0.08
    local KV3_lastPing    = 0
    local KV3 = {
        speed = 60,                      -- BYPASS_AIMBOT_SPEED из KSK
        equipped = false, target = nil,
        intended = Vector3.zero,
        angV = nil, att = nil,
        hbConn = nil, safeConn = nil, respawnConn = nil,
        lastSwing = 0, swinging = false, noColConn = nil, noCol = {},
    }

    local function kv3Clean(root)
        if not root then return end
        pcall(function()
            for _, n in ipairs(KV3_CLEAN) do
                local c = root:FindFirstChild(n)
                if c then c:Destroy() end
            end
            for _, child in ipairs(root:GetChildren()) do
                if child.Name ~= KV3_ANG and child.Name ~= KV3_ATT then
                    local ln = child.Name:lower()
                    if ln:find("lockb") or ln:find("lockangv") or ln:find("batlock")
                       or ln:find("antiaim") or ln:find("velocitylock") then
                        child:Destroy()
                    end
                end
            end
        end)
    end

    local function kv3EnsureAngular(parent)
        pcall(function()
            local a = parent:FindFirstChild(KV3_ANG); if a then a:Destroy() end
            local b = parent:FindFirstChild(KV3_ATT); if b then b:Destroy() end
        end)
        local att = Instance.new("Attachment")
        att.Name = KV3_ATT
        att.Parent = parent
        local angV = Instance.new("AngularVelocity")
        angV.Name = KV3_ANG
        angV.Attachment0 = att
        angV.RelativeTo = Enum.ActuatorRelativeTo.World
        angV.MaxTorque = math.huge
        angV.AngularVelocity = Vector3.zero
        angV.Parent = parent
        KV3.att, KV3.angV = att, angV
    end

    local function kv3RemoveAngular()
        pcall(function() if KV3.angV and KV3.angV.Parent then KV3.angV:Destroy() end end)
        pcall(function() if KV3.att and KV3.att.Parent then KV3.att:Destroy() end end)
        KV3.angV, KV3.att = nil, nil
    end

    local function kv3IsBat(tool)
        if not tool or not tool:IsA("Tool") then return false end
        local n = tool.Name:lower()
        return n:find("bat", 1, true) ~= nil or n:find("slap", 1, true) ~= nil
    end

    local function kv3FindBat()
        local char = LP.Character
        if not char then return nil end
        for _, child in ipairs(char:GetChildren()) do
            if kv3IsBat(child) then return child end
        end
        local backpack = LP:FindFirstChildOfClass("Backpack")
        if backpack then
            for _, child in ipairs(backpack:GetChildren()) do
                if kv3IsBat(child) then return child end
            end
        end
        return nil
    end

    local function kv3Nearest(fromRoot)
        local best, bestDist = nil, math.huge
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LP and plr.Character then
                local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local d = (hrp.Position - fromRoot.Position).Magnitude
                    if d < bestDist then bestDist = d; best = hrp end
                end
            end
        end
        return best, bestDist
    end

    local function kv3UpdatePing()
        local now = tick()
        if now - KV3_lastPing < 1 then return end
        KV3_lastPing = now
        local ok, ping = pcall(function()
            return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
        end)
        if ok and type(ping) == "number" then KV3_ping = math.clamp(ping / 1000, 0.03, 0.3) end
    end

    -- серия ударов: Activate + RemoteEvent несколько раз подряд + добивание
    local function kv3Swing(char, humanoid, root)
        local now = tick()
        if KV3.swinging or now - KV3.lastSwing < KV3_SWING_CD then return end
        local bat = char:FindFirstChildOfClass("Tool")
        if not kv3IsBat(bat) then bat = kv3FindBat() end
        if not bat then return end
        if bat.Parent ~= char then pcall(function() humanoid:EquipTool(bat) end) end
        KV3.swinging = true
        KV3.lastSwing = now
        task.spawn(function()
            local function hit()
                pcall(function()
                    bat:Activate()
                    local re = bat:FindFirstChildWhichIsA("RemoteEvent")
                    if re then re:FireServer() end
                end)
            end
            for _ = 1, KV3_BURST do hit() end
            task.wait(0.02)
            -- добивание, если цель ещё рядом
            local t = KV3.target
            if t and t.Parent and root.Parent and (t.Position - root.Position).Magnitude <= KV3_SWING_RANGE then
                for _ = 1, KV3_BURST do hit() end
            end
            KV3.swinging = false
        end)
    end

    -- убираем всё, что могли оставить V1/V2, чтобы V3 работал "чисто"
    local function kv3KillOtherModes()
        if hbConn then hbConn:Disconnect() hbConn = nil end
        if safeConn then safeConn:Disconnect() safeConn = nil end
        if respawnConn then respawnConn:Disconnect() respawnConn = nil end
        pcall(function() if AimV2.stop then AimV2.stop() end end)
        removeAngular()   -- AngularVelocity режима V1
        local c = LP.Character
        local r = c and c:FindFirstChild("HumanoidRootPart")
        if r then
            pcall(function()
                local x = r:FindFirstChild(ANG_NAME) if x then x:Destroy() end
                local y = r:FindFirstChild(ATT_NAME) if y then y:Destroy() end
            end)
        end
    end

    local function startV3()
        if BP.on then return end
        -- анти-стак с остальными функциями меню
        for _, n in ipairs(CONFLICTS) do
            local a = Actions[n]
            if a and a.get and a.get() then pcall(a.set, false) end
        end
        kv3KillOtherModes()

        BP.on = true
        BP.runMode = "V3"
        KV3.equipped = false
        KV3.target = nil
        KV3.intended = Vector3.zero

        local c0 = LP.Character
        local r0 = c0 and c0:FindFirstChild("HumanoidRootPart")
        if r0 then
            kv3Clean(r0)
            kv3EnsureAngular(r0)
        end

        KV3.hbConn = RunService.Heartbeat:Connect(function()
            if not BP.on or BP.runMode ~= "V3" then return end
            -- анти-стак: включили другую функцию — выключаемся
            if anyConflict() then
                stopBypass()
                setVisual(false)
                return
            end
            local char = LP.Character
            local humanoid = char and char:FindFirstChildOfClass("Humanoid")
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not root or not humanoid or humanoid.Health <= 0 then return end

            kv3Clean(root)
            if not KV3.angV or not KV3.angV.Parent then
                kv3EnsureAngular(root)
            end

            do
                local held = char:FindFirstChildOfClass("Tool")
                if not kv3IsBat(held) then
                    local b = kv3FindBat()
                    if b then pcall(function() humanoid:EquipTool(b) end) end
                end
                KV3.equipped = true
            end

            local target, dist = kv3Nearest(root)
            if not target then
                KV3.target = nil
                humanoid.AutoRotate = true
                if KV3.angV then KV3.angV.AngularVelocity = Vector3.zero end
                return
            end
            KV3.target = target

            kv3UpdatePing()
            local tvel = target.AssemblyLinearVelocity
            local lead = math.clamp(KV3_ping + 0.1, 0.08, 0.32)
            local predicted = target.Position + Vector3.new(tvel.X, 0, tvel.Z) * lead
            local aimPos
            if dist <= KV3_SNAP_DIST then
                -- вблизи целимся прямо в предсказанную позицию — максимум попаданий
                aimPos = predicted
            else
                aimPos = predicted
                    + target.CFrame.LookVector * (tvel.Magnitude < 0.1 and 1.5 or 5)
            end
            local delta = aimPos - root.Position
            local flat = Vector3.new(delta.X, 0, delta.Z)
            humanoid.AutoRotate = false

            if delta.Magnitude > 0.01 and flat.Magnitude > 0.01 then
                local curY = root.Orientation.Y
                local yawD = (math.deg(math.atan2(-flat.X, -flat.Z)) - curY + 180) % 360 - 180
                local curX = root.Orientation.X
                local pitchD = (math.deg(math.atan2(delta.Y, flat.Magnitude)) - curX + 180) % 360 - 180
                local rotY = math.clamp(math.rad(yawD) * 40, -28, 28)
                local rotX = math.clamp(math.rad(pitchD) * 40, -28, 28)
                local yawR = math.rad(root.Orientation.Y)
                local fwd = Vector3.new(math.cos(yawR), 0, -math.sin(yawR))
                KV3.angV.AngularVelocity = Vector3.new(0, rotY, 0) + fwd * rotX
            else
                KV3.angV.AngularVelocity = Vector3.zero
            end

            local spd = tonumber(KV3.speed) or 58
            if spd ~= spd or spd <= 0 or spd == math.huge then spd = 58 end

            -- скорость цели по горизонтали: едем вместе с ней, чтобы не отставать и не улетать
            local tflat = Vector3.new(tvel.X, 0, tvel.Z)
            local d = flat.Magnitude
            local hv
            if d > KV3_STAND then
                -- чем ближе, тем медленнее (мягкое торможение), потолок — V3 Speed
                local push = math.min(spd, (d - KV3_STAND) * KV3_BRAKE)
                hv = flat.Unit * push + tflat
            else
                -- вплотную: только повторяем движение цели, никаких толчков в неё
                hv = tflat
            end
            local cap = spd * KV3_MAXV
            if hv.Magnitude > cap then hv = hv.Unit * cap end

            -- вертикаль: плавный добор высоты, без ±speed (из-за этого подбрасывало)
            local vy
            if math.abs(delta.Y) > 0.8 then
                vy = math.clamp(delta.Y * 8, -40, 40)
            else
                vy = -2
            end

            KV3.intended = Vector3.new(hv.X, vy, hv.Z)
            root.AssemblyLinearVelocity = KV3.intended
            pcall(function() root.Velocity = KV3.intended end)

            if d > KV3_STAND + 0.5 then
                pcall(function() humanoid:Move(flat.Unit, false) end)
            else
                pcall(function() humanoid:Move(Vector3.zero, false) end)
            end

            if dist <= KV3_SWING_RANGE then
                kv3Swing(char, humanoid, root)
            end
        end)

        -- страховка из KSK: гасим всплески скорости и чистим чужие "локи"
        KV3.noColConn = RunService.Stepped:Connect(function()
            if not BP.on or BP.runMode ~= "V3" then return end
            local t = KV3.target
            local model = t and t.Parent
            if not model then return end
            for _, part in ipairs(model:GetDescendants()) do
                if part:IsA("BasePart") and part.CanCollide then
                    part.CanCollide = false
                    KV3.noCol[part] = true
                end
            end
        end)

        KV3.safeConn = RunService.RenderStepped:Connect(function()
            if not BP.on or BP.runMode ~= "V3" then return end
            local char = LP.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not root then return end
            local v = root.AssemblyLinearVelocity
            if math.abs(v.X) > 350 or math.abs(v.Z) > 350 then
                root.AssemblyLinearVelocity = KV3.intended
            end
            kv3Clean(root)
        end)

        if not KV3.respawnConn then
            KV3.respawnConn = LP.CharacterAdded:Connect(function(character)
                task.wait(0.5)
                KV3.equipped = false
                KV3.target = nil
                if BP.on and BP.runMode == "V3" then
                    local root = character:WaitForChild("HumanoidRootPart", 5)
                    if root then
                        kv3Clean(root)
                        kv3EnsureAngular(root)
                    end
                end
            end)
        end
    end

    local function stopV3()
        if not BP.on then return end
        BP.on = false
        if KV3.hbConn then KV3.hbConn:Disconnect() KV3.hbConn = nil end
        if KV3.safeConn then KV3.safeConn:Disconnect() KV3.safeConn = nil end
        if KV3.noColConn then KV3.noColConn:Disconnect() KV3.noColConn = nil end
        for part in pairs(KV3.noCol) do
            if part and part.Parent then pcall(function() part.CanCollide = true end) end
        end
        KV3.noCol = {}
        if KV3.respawnConn then KV3.respawnConn:Disconnect() KV3.respawnConn = nil end
        KV3.equipped = false
        KV3.target = nil
        KV3.swinging = false

        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if root then
            pcall(function() root.AssemblyLinearVelocity = root.AssemblyLinearVelocity * 0.3 end)
        end
        if hum then hum.AutoRotate = true end
        if KV3.angV then
            pcall(function() KV3.angV.AngularVelocity = Vector3.zero end)
        end
        kv3RemoveAngular()
        if root then
            local x = root:FindFirstChild(KV3_ANG); if x then x:Destroy() end
            local y = root:FindFirstChild(KV3_ATT); if y then y:Destroy() end
        end
    end

    -- общие точки входа: работают с выбранным режимом V1 / V2 / V3
    local function startBypass()
        if BP.on then return end
        if BP.mode == "V2" then startV2()
        elseif BP.mode == "V3" then startV3()
        else BP.runMode = "V1" startV1() end
    end
    stopBypass = function()
        if not BP.on then return end
        if BP.runMode == "V2" then stopV2()
        elseif BP.runMode == "V3" then stopV3()
        else stopV1() end
    end

    -- ---------- панель ----------
    local panelBP = Instance.new("Frame")
    panelBP.Name = "BatBypassPanel"
    panelBP.Size = UDim2.new(1, 0, 0, 124)
    panelBP.BackgroundColor3 = COLOR_PANEL
    panelBP.BorderSizePixel = 0
    panelBP.LayoutOrder = 4
    panelBP.Parent = currentPage
    local pbc = Instance.new("UICorner", panelBP)
    pbc.CornerRadius = UDim.new(0, 10)
    local pbs = Instance.new("UIStroke", panelBP)
    pbs.Color = COLOR_ACCENT
    pbs.Thickness = 1.5

    local titleBP = Instance.new("TextLabel")
    titleBP.BackgroundTransparency = 1
    titleBP.Position = UDim2.new(0, 8, 0, 4)
    titleBP.Size = UDim2.new(0, 100, 0, 16)
    titleBP.Text = "ATTACK"
    titleBP.Font = Enum.Font.GothamBold
    titleBP.TextSize = 11
    titleBP.TextColor3 = COLOR_BLUE
    titleBP.TextXAlignment = Enum.TextXAlignment.Left
    titleBP.Parent = panelBP

    makeLabel(panelBP, UDim2.new(0, 8, 0, 26), "Bat Bypass", UDim2.new(0, 100, 0, 18))
    local _, setBPVisual = makeToggle(panelBP, UDim2.new(1, -44, 0, 26), false, function(v)
        if v then startBypass() else stopBypass() end
    end)
    setVisual = setBPVisual

    -- режим: V1 (Demon Bypass) / V2 (Zurich Aimbot) / V3 (KSK Bypass Bat)
    makeLabel(panelBP, UDim2.new(0, 8, 0, 58), "Mode", UDim2.new(0, 60, 0, 18))
    local chipM1 = makeChip(panelBP, UDim2.new(1, -100, 0, 58), UDim2.new(0, 26, 0, 18), "V1", true)
    local chipM2 = makeChip(panelBP, UDim2.new(1, -72, 0, 58), UDim2.new(0, 26, 0, 18), "V2", false)
    local chipM3 = makeChip(panelBP, UDim2.new(1, -44, 0, 58), UDim2.new(0, 26, 0, 18), "V3", false)

    local function makeSpeedBox(name, y, default)
        local box = Instance.new("TextBox")
        box.Name = name
        box.Size = UDim2.new(0, 36, 0, 22)
        box.Position = UDim2.new(1, -44, 0, y)
        box.BackgroundColor3 = COLOR_BG
        box.Text = tostring(default)
        box.Font = Enum.Font.GothamBold
        box.TextSize = 12
        box.TextColor3 = COLOR_TEXT
        box.TextXAlignment = Enum.TextXAlignment.Center
        box.ClearTextOnFocus = false
        box.Parent = panelBP
        local c = Instance.new("UICorner", box)
        c.CornerRadius = UDim.new(0, 6)
        local s = Instance.new("UIStroke", box)
        s.Color = COLOR_ACCENT
        s.Thickness = 1.5
        box:GetPropertyChangedSignal("Text"):Connect(function()
            local txt = box.Text:gsub("%D", "")
            if box.Text ~= txt then box.Text = txt end
        end)
        return box
    end

    -- V1: Bypass Speed
    local lblV1 = makeLabel(panelBP, UDim2.new(0, 8, 0, 92), "Bypass Speed", UDim2.new(0, 100, 0, 18))
    local speedBox = makeSpeedBox("BypassSpeed", 90, BP.speed)
    local function applySpeed()
        local v = tonumber(speedBox.Text)
        if v and v > 0 then BP.speed = math.clamp(math.floor(v), 1, 250) end
        speedBox.Text = tostring(BP.speed)
    end
    speedBox.FocusLost:Connect(applySpeed)
    Flags.apply.BypassSpeed = applySpeed

    -- V3: отдельная скорость (KSK Bypass Speed), не связана с V1
    local lblV3 = makeLabel(panelBP, UDim2.new(0, 8, 0, 92), "V3 Speed", UDim2.new(0, 100, 0, 18))
    local v3Box = makeSpeedBox("BypassV3Speed", 90, KV3.speed)
    local function applyV3Speed()
        local v = tonumber(v3Box.Text)
        if v and v > 0 then KV3.speed = math.clamp(math.floor(v), 1, 250) end
        v3Box.Text = tostring(KV3.speed)
    end
    v3Box.FocusLost:Connect(applyV3Speed)
    Flags.apply.BypassV3Speed = applyV3Speed

    -- V2: Aimbot Speed (в Zurich по умолчанию 55, предел 1-120)
    local lblV2 = makeLabel(panelBP, UDim2.new(0, 8, 0, 92), "Aimbot Speed", UDim2.new(0, 100, 0, 18))
    local aimBox = makeSpeedBox("AimbotSpeed", 90, AIM.speed)
    local function applyAimSpeed()
        local v = tonumber(aimBox.Text)
        if v and v > 0 then AIM.speed = math.clamp(math.floor(v), 1, 120) end
        aimBox.Text = tostring(AIM.speed)
    end
    aimBox.FocusLost:Connect(applyAimSpeed)
    Flags.apply.AimbotSpeed = applyAimSpeed

    local function paintModeChip(chip, active)
        chip.BackgroundColor3 = active and COLOR_ACCENT_D or COLOR_BG
        chip.TextColor3 = active and COLOR_TEXT or COLOR_TEXT_D
        local st = chip:FindFirstChildOfClass("UIStroke")
        if st then st.Color = active and COLOR_ACCENT or COLOR_LINE end
    end
    local function paintBypassMode()
        paintModeChip(chipM1, BP.mode == "V1")
        paintModeChip(chipM2, BP.mode == "V2")
        paintModeChip(chipM3, BP.mode == "V3")
        lblV1.Visible = BP.mode == "V1"
        speedBox.Visible = BP.mode == "V1"
        lblV2.Visible = BP.mode == "V2"
        aimBox.Visible = BP.mode == "V2"
        lblV3.Visible = BP.mode == "V3"
        v3Box.Visible = BP.mode == "V3"
    end
    local function setBypassMode(m)
        if m ~= "V1" and m ~= "V2" and m ~= "V3" then return end
        if BP.mode ~= m then
            local wasOn = BP.on
            if wasOn then stopBypass() end
            BP.mode = m
            if wasOn then startBypass() end
        end
        paintBypassMode()
    end
    chipM1.MouseButton1Click:Connect(function() setBypassMode("V1") end)
    chipM2.MouseButton1Click:Connect(function() setBypassMode("V2") end)
    chipM3.MouseButton1Click:Connect(function() setBypassMode("V3") end)
    paintBypassMode()
    Flags.bypassMode = {get = function() return BP.mode end, set = function(m) setBypassMode(m) end}

    -- для плавающих кнопок, анти-стака и сохранения настроек
    Actions.BatBypass = {
        get = function() return BP.on end,
        set = function(v)
            setBPVisual(v == true)
            if v then startBypass() else stopBypass() end
        end,
    }
end
currentPage = pages["MAIN"]

-- ================= COMBAT: BAT AIMBOT (перенесён из KSK OP — BAT V3 / аимбот с предиктом) =================
-- Предикт позиции цели (скорость, ускорение, пинг, воздух), наведение через AssemblyAngularVelocity,
-- авто-удар битой в радиусе. Анти-стак: при включении гасит Auto Left/Right, Auto Bat, Bat Bypass, Lock Enemy.
currentPage = pages["COMBAT"]
do
    local RunService = game:GetService("RunService")
    local LP = player
    local aimbotOn = false
    local setAimbotVisual = function() end
    local AIM_CONFLICTS = {"AutoLeft", "AutoRight", "AutoBat", "BatV2", "LockEnemy", "BatBypass"}

    local V3 = {
        enabled = false, conn = nil, speed = 55,
        cfg = {
            FOLLOW_SPEED = 55, ACTIVATE_DISTANCE = 16, MIN_FOLLOW_DISTANCE = 1,
            ACTIVATION_GAP = 0.12, SWING_BURST = 6, SNAP_IN = true, SNAP_MIN = 5, SNAP_MAX = 4,
            PREDICTION_TIME = 0.22, PREDICT_AHEAD = 3, MAX_VELOCITY_CHANGE = 150,
            VELOCITY_SMOOTHING = 0.2, MAX_HORIZONTAL_VELOCITY = 80,
            SERVER_TICKRATE = 1/60, MIN_PING_COMPENSATION = 0.03, MAX_PING_COMPENSATION = 0.25,
            ACCELERATION_PREDICTION_WEIGHT = 0.3, DIRECTION_CHANGE_DETECTION_TIME = 0.12,
            QUICK_DIRECTION_CHANGE_MULTIPLIER = 1.5, GRAVITY = 196.2, AIR_CONTROL_FACTOR = 0.8,
            MIN_AIRBORNE_TIME = 0.08, SWING_COOLDOWN = 0.05,
        },
        st = {
            targetPlayer = nil, lastTargetPos = nil,
            targetVelocity = Vector3.zero, smoothedVelocity = Vector3.zero,
            velocityHistory = {}, accelerationHistory = {}, aerialVelocityHistory = {},
            verticalVelocityHistory = {}, previousDirection = nil,
            lastDirectionChangeTime = 0, airborneTime = 0, lastYVelocity = 0,
            lastActivationTime = 0, currentPing = 0.1, realPingMs = 0,
            previousAutoRotate = nil, previousHumanoid = nil,
            swingLocked = false, nextSwingAt = 0,
        },
    }

    function V3.avg(list)
        if #list == 0 then return Vector3.zero end
        local sum = Vector3.zero
        for _, v in ipairs(list) do sum = sum + v end
        return sum / #list
    end

    function V3.push(list, value, maxSize)
        table.insert(list, value)
        if #list > maxSize then table.remove(list, 1) end
    end

    function V3.reset()
        local s = V3.st
        s.targetPlayer = nil; s.lastTargetPos = nil
        s.targetVelocity = Vector3.zero; s.smoothedVelocity = Vector3.zero
        s.velocityHistory = {}; s.accelerationHistory = {}
        s.aerialVelocityHistory = {}; s.verticalVelocityHistory = {}
        s.previousDirection = nil; s.airborneTime = 0; s.lastYVelocity = 0
    end

    function V3.findBat()
        local char = LP.Character
        if not char then return nil end
        local equipped = char:FindFirstChildOfClass("Tool")
        if equipped then
            local n = equipped.Name:lower()
            if n:find("bat") or n:find("slap") then return equipped end
        end
        local bp = LP:FindFirstChildOfClass("Backpack")
        if bp then
            for _, tool in ipairs(bp:GetChildren()) do
                if tool:IsA("Tool") then
                    local n = tool.Name:lower()
                    if n:find("bat") or n:find("slap") then return tool end
                end
            end
        end
        return nil
    end

    function V3.nearest(myRoot)
        local nearest, nearestDist = nil, math.huge
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LP and player.Character then
                local tr = player.Character:FindFirstChild("HumanoidRootPart")
                local th = player.Character:FindFirstChildOfClass("Humanoid")
                if tr and th and th.Health > 0 then
                    local d = (tr.Position - myRoot.Position).Magnitude
                    if d < nearestDist then nearestDist = d; nearest = player end
                end
            end
        end
        return nearest, nearestDist
    end

    function V3.face(myRoot, direction)
        if direction.Magnitude < 0.01 then return end
        local cross = myRoot.CFrame.LookVector:Cross(direction.Unit)
        local angle = math.asin(math.clamp(cross.Magnitude, -1, 1))
        myRoot.AssemblyAngularVelocity = cross.Magnitude > 0.01
            and cross.Unit * angle * 80
            or Vector3.zero
    end

    function V3.updatePing()
        local ok, ping = pcall(function()
            return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
        end)
        if ok and type(ping) == "number" then V3.st.realPingMs = math.floor(ping) end
        V3.st.currentPing = math.clamp(V3.st.realPingMs / 1000, V3.cfg.MIN_PING_COMPENSATION, V3.cfg.MAX_PING_COMPENSATION)
    end

    -- Удар с упором на рег с 1 тика: доворот лицом в цель (с компенсацией пинга) ->
    -- подтяжка в хитбокс -> burst Activate в тот же кадр + вторая волна через 0.02с.
    function V3.swing(root, aimPos)
        local s, cfg = V3.st, V3.cfg
        local now = tick()
        if s.swingLocked or now < s.nextSwingAt then return false end
        local char = LP.Character
        if not char then return false end
        local bat = V3.findBat()
        if not bat then return false end
        s.swingLocked = true
        s.nextSwingAt = now + cfg.SWING_COOLDOWN

        pcall(function()
            if bat.Parent ~= char then
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then hum:EquipTool(bat) end
            end

            if root and aimPos then
                local flat = Vector3.new(aimPos.X - root.Position.X, 0, aimPos.Z - root.Position.Z)
                if flat.Magnitude > 0.05 then
                    -- мгновенный доворот (AngularVelocity не успевает за 1 тик)
                    root.CFrame = CFrame.lookAt(root.Position, root.Position + flat)
                    -- подтяжка в хитбокс, если цель на краю дальности
                    if cfg.SNAP_IN and flat.Magnitude > cfg.SNAP_MIN then
                        local snap = math.clamp(flat.Magnitude - cfg.SNAP_MIN, 0, cfg.SNAP_MAX)
                        root.CFrame = root.CFrame + flat.Unit * snap * 0.6
                    end
                end
            end
        end)

        local remote = bat:FindFirstChildWhichIsA("RemoteEvent")
        local function wave(n)
            for _ = 1, n do
                pcall(function() bat:Activate() end)
                if remote then pcall(function() remote:FireServer() end) end
            end
        end
        wave(cfg.SWING_BURST)                 -- волна 1: в этот же кадр
        task.spawn(function()
            task.wait(0.02)
            if bat.Parent == char then wave(math.max(cfg.SWING_BURST - 2, 2)) end  -- волна 2: добивание
        end)
        task.delay(cfg.SWING_COOLDOWN, function() s.swingLocked = false end)
        return true
    end

    function V3.loop(dt)
        local s, cfg = V3.st, V3.cfg
        local spd = tonumber(V3.speed) or 55
        if spd ~= spd or spd <= 0 or spd == math.huge then spd = 55 end
        cfg.FOLLOW_SPEED = spd
        if not V3.enabled then return end

        local char = LP.Character
        if not char then return end
        local myRoot = char:FindFirstChild("HumanoidRootPart")
        local myHum = char:FindFirstChildOfClass("Humanoid")
        if not myRoot or not myHum or myHum.Health <= 0 then return end

        myHum.AutoRotate = false

        if not char:FindFirstChildOfClass("Tool") then
            local bat = V3.findBat()
            if bat and bat.Parent ~= char then
                pcall(function() myHum:EquipTool(bat) end)
            end
        end

        local target = V3.nearest(myRoot)
        if not target or not target.Character then V3.reset(); return end
        local targetRoot = target.Character:FindFirstChild("HumanoidRootPart")
        local targetHum = target.Character:FindFirstChildOfClass("Humanoid")
        if not targetRoot or not targetHum or targetHum.Health <= 0 then V3.reset(); return end

        if s.targetPlayer ~= target then V3.reset() end
        s.targetPlayer = target

        V3.updatePing()

        local targetPos = targetRoot.Position
        local dtc = math.max(dt, 1/240)

        if s.lastTargetPos then
            local instantVel = (targetPos - s.lastTargetPos) / dtc
            local accel = instantVel - s.targetVelocity
            if accel.Magnitude > cfg.MAX_VELOCITY_CHANGE then
                instantVel = s.targetVelocity + accel.Unit * cfg.MAX_VELOCITY_CHANGE
            end
            local hv = Vector3.new(instantVel.X, 0, instantVel.Z)
            if hv.Magnitude > cfg.MAX_HORIZONTAL_VELOCITY then
                hv = hv.Unit * cfg.MAX_HORIZONTAL_VELOCITY
                instantVel = Vector3.new(hv.X, instantVel.Y, hv.Z)
            end
            V3.push(s.accelerationHistory, (instantVel - s.targetVelocity) / dtc, 4)
            V3.push(s.velocityHistory, instantVel, 8)
            V3.push(s.verticalVelocityHistory, instantVel.Y, 5)
            s.targetVelocity = instantVel
            s.smoothedVelocity = s.smoothedVelocity:Lerp(instantVel, cfg.VELOCITY_SMOOTHING)
        end
        s.lastTargetPos = targetPos

        local isAirborne = targetHum.FloorMaterial == Enum.Material.Air
        s.airborneTime = isAirborne and (s.airborneTime + dtc) or 0
        if isAirborne and s.airborneTime >= cfg.MIN_AIRBORNE_TIME then
            V3.push(s.aerialVelocityHistory, s.targetVelocity, 6)
        elseif not isAirborne then
            s.aerialVelocityHistory = {}
        end

        local smoothedVel = s.smoothedVelocity
        if isAirborne and #s.aerialVelocityHistory > 0 then
            local avgAerial = V3.avg(s.aerialVelocityHistory)
            smoothedVel = Vector3.new(avgAerial.X, s.targetVelocity.Y, avgAerial.Z) * cfg.AIR_CONTROL_FACTOR
        end

        local isQuickTurn = false
        local htv = Vector3.new(s.targetVelocity.X, 0, s.targetVelocity.Z)
        if htv.Magnitude > 5 then
            local newDir = htv.Unit
            if s.previousDirection and s.previousDirection:Dot(newDir) < 0.5 then
                isQuickTurn = (tick() - s.lastDirectionChangeTime) < cfg.DIRECTION_CHANGE_DETECTION_TIME
                s.lastDirectionChangeTime = tick()
            end
            s.previousDirection = newDir
        end

        local serverDelay = s.currentPing + cfg.SERVER_TICKRATE
        local adjustedDelay = isQuickTurn and (serverDelay * cfg.QUICK_DIRECTION_CHANGE_MULTIPLIER) or serverDelay

        local avgAccel = V3.avg(s.accelerationHistory)
        local accelContribution = avgAccel * cfg.ACCELERATION_PREDICTION_WEIGHT * (adjustedDelay * adjustedDelay * 0.5)
        local predictedPos = targetPos + smoothedVel * adjustedDelay + accelContribution

        local predictionTime = cfg.PREDICTION_TIME * 1.1
        if isAirborne then
            predictedPos = predictedPos + smoothedVel * predictionTime
                + Vector3.new(0, -0.5 * cfg.GRAVITY * predictionTime * predictionTime, 0)
        else
            predictedPos = predictedPos + smoothedVel * predictionTime
        end

        local hs = Vector3.new(smoothedVel.X, 0, smoothedVel.Z)
        if hs.Magnitude > 1 then
            predictedPos = predictedPos + hs.Unit * cfg.PREDICT_AHEAD
        end

        -- позиция для удара: только компенсация пинга (без PREDICT_AHEAD, иначе промах вблизи)
        local hitPos = targetPos + Vector3.new(smoothedVel.X, 0, smoothedVel.Z) * adjustedDelay
        local realDist = (targetPos - myRoot.Position).Magnitude
        if realDist <= cfg.ACTIVATE_DISTANCE + 4 then
            predictedPos = hitPos
        end

        local direction = predictedPos - myRoot.Position
        V3.face(myRoot, direction)

        if math.min(realDist, (hitPos - myRoot.Position).Magnitude) <= cfg.ACTIVATE_DISTANCE then
            if tick() - s.lastActivationTime >= cfg.ACTIVATION_GAP then
                if V3.swing(myRoot, hitPos) then
                    s.lastActivationTime = tick()
                end
            end
        end

        if direction.Magnitude > cfg.MIN_FOLLOW_DISTANCE then
            myRoot.AssemblyLinearVelocity = direction.Unit * cfg.FOLLOW_SPEED
        else
            local cv = myRoot.AssemblyLinearVelocity
            myRoot.AssemblyLinearVelocity = Vector3.new(0, cv.Y * 0.5, 0)
        end
    end

    function V3.start()
        if V3.enabled then return end
        V3.enabled = true
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            V3.st.previousHumanoid = hum
            V3.st.previousAutoRotate = hum.AutoRotate
            hum.AutoRotate = false
        end
        V3.reset()
        V3.st.lastActivationTime = 0
        V3.conn = RunService.RenderStepped:Connect(function(dt)
            pcall(V3.loop, dt)
        end)
    end

    function V3.stop()
        if not V3.enabled then return end
        V3.enabled = false
        if V3.conn then V3.conn:Disconnect(); V3.conn = nil end
        local char = LP.Character
        if char then
            local myRoot = char:FindFirstChild("HumanoidRootPart")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if myRoot then
                myRoot.AssemblyLinearVelocity = Vector3.zero
                myRoot.AssemblyAngularVelocity = Vector3.zero
            end
            local prev = V3.st.previousHumanoid
            if prev and prev.Parent then
                prev.AutoRotate = V3.st.previousAutoRotate == nil and true or V3.st.previousAutoRotate
            elseif hum then
                hum.AutoRotate = true
            end
        end
        V3.st.previousHumanoid = nil
        V3.st.previousAutoRotate = nil
        V3.reset()
    end

    local function startAimbot()
        if V3.enabled then return end
        for _, n in ipairs(AIM_CONFLICTS) do
            local a = Actions[n]
            if a and a.get and a.get() then pcall(a.set, false) end
        end
        V3.start()
    end
    local function stopAimbot()
        V3.stop()
    end

    -- ---------- панель ----------
    local panelBA = Instance.new("Frame")
    panelBA.Name = "BatAimbotPanel"
    panelBA.Size = UDim2.new(1, 0, 0, 90)
    panelBA.BackgroundColor3 = COLOR_PANEL
    panelBA.BorderSizePixel = 0
    panelBA.LayoutOrder = 7
    panelBA.Parent = currentPage
    local pbaC = Instance.new("UICorner", panelBA)
    pbaC.CornerRadius = UDim.new(0, 10)
    local pbaS = Instance.new("UIStroke", panelBA)
    pbaS.Color = COLOR_ACCENT
    pbaS.Thickness = 1.5

    local titleBA = Instance.new("TextLabel")
    titleBA.BackgroundTransparency = 1
    titleBA.Position = UDim2.new(0, 8, 0, 4)
    titleBA.Size = UDim2.new(0, 120, 0, 16)
    titleBA.Text = "BAT AIMBOT"
    titleBA.Font = Enum.Font.GothamBold
    titleBA.TextSize = 11
    titleBA.TextColor3 = COLOR_BLUE
    titleBA.TextXAlignment = Enum.TextXAlignment.Left
    titleBA.Parent = panelBA

    makeLabel(panelBA, UDim2.new(0, 8, 0, 26), "Bat Aimbot", UDim2.new(0, 110, 0, 18))
    local _, setBA = makeToggle(panelBA, UDim2.new(1, -44, 0, 26), false, function(v)
        aimbotOn = v == true
        if aimbotOn then startAimbot() else stopAimbot() end
    end)
    setAimbotVisual = setBA

    makeLabel(panelBA, UDim2.new(0, 8, 0, 58), "Aimbot Speed", UDim2.new(0, 110, 0, 18))
    local aimSpeedBox = Instance.new("TextBox")
    aimSpeedBox.Name = "BatAimbotSpeed"
    aimSpeedBox.Size = UDim2.new(0, 36, 0, 22)
    aimSpeedBox.Position = UDim2.new(1, -44, 0, 56)
    aimSpeedBox.BackgroundColor3 = COLOR_BG
    aimSpeedBox.Text = tostring(V3.speed)
    aimSpeedBox.Font = Enum.Font.GothamBold
    aimSpeedBox.TextSize = 12
    aimSpeedBox.TextColor3 = COLOR_TEXT
    aimSpeedBox.TextXAlignment = Enum.TextXAlignment.Center
    aimSpeedBox.ClearTextOnFocus = false
    aimSpeedBox.Parent = panelBA
    local asC = Instance.new("UICorner", aimSpeedBox)
    asC.CornerRadius = UDim.new(0, 6)
    local asS = Instance.new("UIStroke", aimSpeedBox)
    asS.Color = COLOR_ACCENT
    asS.Thickness = 1.5
    aimSpeedBox:GetPropertyChangedSignal("Text"):Connect(function()
        local txt = aimSpeedBox.Text:gsub("%D", "")
        if aimSpeedBox.Text ~= txt then aimSpeedBox.Text = txt end
    end)
    local function applyBatAimSpeed()
        local v = tonumber(aimSpeedBox.Text)
        if v and v > 0 then V3.speed = math.clamp(math.floor(v), 1, 250) end
        aimSpeedBox.Text = tostring(V3.speed)
    end
    aimSpeedBox.FocusLost:Connect(applyBatAimSpeed)
    Flags.apply.BatAimbotSpeed = applyBatAimSpeed

    -- для плавающей кнопки / клавиши
    Actions.BatAimbot = {
        get = function() return aimbotOn end,
        set = function(v)
            aimbotOn = v == true
            setAimbotVisual(aimbotOn)
            if aimbotOn then startAimbot() else stopAimbot() end
        end,
    }

    -- респавн: возвращаем AutoRotate=false на новый персонаж, пока аимбот включён
    LP.CharacterAdded:Connect(function(char)
        task.wait(0.5)
        if aimbotOn then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                V3.st.previousHumanoid = hum
                V3.st.previousAutoRotate = true
                hum.AutoRotate = false
            end
            V3.reset()
        end
    end)
end
currentPage = pages["MAIN"]

-- ================= VISUALS: SPEED DISPLAY — скорость над собой и над соперником =================
currentPage = pages["VISUALS"]
do
    local RunService = game:GetService("RunService")

    local showMine, showEnemy = false, false
    local tags = {}   -- [Player] = {gui, label, lastPos, lastT, smooth}

    local function removeTag(plr)
        local t = tags[plr]
        if t then
            if t.gui then t.gui:Destroy() end
            tags[plr] = nil
        end
    end

    local function makeTag(plr, root)
        local gui = Instance.new("BillboardGui")
        gui.Name = "SpeexSpeedTag"
        gui.Adornee = root
        gui.Size = UDim2.new(0, 95, 0, 20)
        gui.StudsOffset = Vector3.new(0, 4.4, 0)
        gui.AlwaysOnTop = true
        gui.ResetOnSpawn = false
        gui.Parent = ScreenGui

        local lbl = Instance.new("TextLabel")
        lbl.BackgroundTransparency = 1
        lbl.Size = UDim2.new(1, 0, 1, 0)
        lbl.Font = Enum.Font.FredokaOne
        lbl.TextSize = 15
        lbl.TextColor3 = Color3.fromRGB(70, 130, 255)      -- синий
        lbl.TextStrokeTransparency = 1
        lbl.Text = "Speed: 0.0"
        lbl.Parent = gui
        local lblStroke = Instance.new("UIStroke", lbl)
        lblStroke.Color = Color3.fromRGB(10, 25, 100)      -- тёмно-синяя обводка
        lblStroke.Thickness = 1.5

        tags[plr] = {gui = gui, label = lbl, root = root, lastPos = root.Position, lastT = os.clock(), smooth = 0}
        return tags[plr]
    end

    local function wanted(plr)
        if plr == player then return showMine end
        return showEnemy
    end

    RunService.Heartbeat:Connect(function()
        local now = os.clock()
        for _, plr in ipairs(Players:GetPlayers()) do
            local char = plr.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if wanted(plr) and root then
                local t = tags[plr]
                if (not t) or t.root ~= root or not t.gui.Parent then
                    removeTag(plr)
                    t = makeTag(plr, root)
                end
                local dt = now - t.lastT
                if dt >= 0.05 then
                    -- точная скорость по смещению позиции (по горизонтали), работает и на чужих персах
                    local p0, p1 = t.lastPos, root.Position
                    local d = Vector3.new(p1.X - p0.X, 0, p1.Z - p0.Z).Magnitude
                    local inst = d / dt
                    -- если телепорт/рывок > 500 stud/s — берём реальную скорость движка
                    if inst > 500 then
                        local v = root.AssemblyLinearVelocity
                        inst = Vector3.new(v.X, 0, v.Z).Magnitude
                    end
                    t.smooth = t.smooth * 0.5 + inst * 0.5
                    t.lastPos, t.lastT = p1, now
                    t.label.Text = string.format("Speed: %.1f", t.smooth)
                end
            else
                removeTag(plr)
            end
        end
    end)

    Players.PlayerRemoving:Connect(removeTag)

    -- ---------- Панель ----------
    local panelS = Instance.new("Frame")
    panelS.Name = "SpeedDisplayPanel"
    panelS.Size = UDim2.new(1, 0, 0, 86)
    panelS.BackgroundColor3 = COLOR_PANEL
    panelS.BorderSizePixel = 0
    panelS.LayoutOrder = 5
    panelS.Parent = currentPage
    local pcS = Instance.new("UICorner", panelS)
    pcS.CornerRadius = UDim.new(0, 10)
    local psS = Instance.new("UIStroke", panelS)
    psS.Color = COLOR_ACCENT
    psS.Thickness = 1.5

    local titleS = Instance.new("TextLabel")
    titleS.BackgroundTransparency = 1
    titleS.Position = UDim2.new(0, 8, 0, 4)
    titleS.Size = UDim2.new(0, 120, 0, 16)
    titleS.Text = "SPEED DISPLAY"
    titleS.Font = Enum.Font.GothamBold
    titleS.TextSize = 11
    titleS.TextColor3 = COLOR_BLUE
    titleS.TextXAlignment = Enum.TextXAlignment.Left
    titleS.Parent = panelS

    makeLabel(panelS, UDim2.new(0, 8, 0, 26), "My Speed", UDim2.new(0, 100, 0, 18))
    makeToggle(panelS, UDim2.new(1, -44, 0, 26), false, function(v) showMine = v end)

    makeLabel(panelS, UDim2.new(0, 8, 0, 58), "Enemy Speed", UDim2.new(0, 100, 0, 18))
    makeToggle(panelS, UDim2.new(1, -44, 0, 58), false, function(v) showEnemy = v end)

    Actions.MySpeed = {get = function() return showMine end, set = function(v) showMine = v end}
    Actions.EnemySpeed = {get = function() return showEnemy end, set = function(v) showEnemy = v end}
end
currentPage = pages["MAIN"]

-- ================= VISUALS: RAGDOLL TIMER — после удара отсчёт 2.4 … 0.1 и надпись READY =================
currentPage = pages["VISUALS"]
do
    local RunService = game:GetService("RunService")

    local timerOn = false
    local DUR = 2.5              -- сколько секунд отсчитывать после удара
    local READY_TIME = 1.0       -- сколько держится READY
    local MILK = Color3.fromRGB(255, 247, 232)   -- молочный цвет
    local posMode = "Head"       -- Head: над головой выше Speed (мелко) / Body: на теле как на видео

    local tag, label, tagRoot = nil, nil, nil
    local phase = "idle"         -- idle -> count -> ready -> cool
    local startT, lastActiveT, readyUntil = 0, 0, 0
    local usedAttr = false       -- берём точное время из атрибута игры RagdollEndTime

    -- сколько секунд рэгдолла осталось по данным игры (0, если рэгдолла нет)
    local function gameLeft()
        local endT = player:GetAttribute("RagdollEndTime")
        if type(endT) ~= "number" then return 0 end
        return math.max(endT - workspace:GetServerTimeNow(), 0)
    end

    local function removeTag()
        if tag then tag:Destroy() end
        tag, label, tagRoot = nil, nil, nil
    end

    local function applyLook()
        if not tag or not label then return end
        if posMode == "Body" then
            tag.Size = UDim2.fromOffset(200, 50)
            tag.StudsOffset = Vector3.new(0, 0.4, 0)
            label.TextSize = 30
        else
            tag.Size = UDim2.fromOffset(120, 26)
            tag.StudsOffset = Vector3.new(0, 5.9, 0)   -- выше тега Speed (он на 4.4)
            label.TextSize = 19
        end
    end

    local function makeTag(root)
        removeTag()
        tag = Instance.new("BillboardGui")
        tag.Name = "SpeexRagdollTimerTag"
        tag.Adornee = root
        tag.AlwaysOnTop = true
        tag.ResetOnSpawn = false
        tag.Enabled = false
        tag.Parent = root
        label = Instance.new("TextLabel")
        label.BackgroundTransparency = 1
        label.Size = UDim2.new(1, 0, 1, 0)
        label.Font = Enum.Font.FredokaOne
        label.TextColor3 = MILK
        label.TextStrokeTransparency = 1
        label.Text = ""
        label.Parent = tag
        local st = Instance.new("UIStroke", label)
        st.Color = Color3.fromRGB(40, 40, 40)
        st.Transparency = 0.35
        st.Thickness = 1.2
        tagRoot = root
        applyLook()
    end

    local function isRagdolled(hum)
        local st = hum:GetState()
        return st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.FallingDown
            or st == Enum.HumanoidStateType.Physics
            or hum.PlatformStand
    end

    RunService.Heartbeat:Connect(function()
        local char = player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not timerOn or not hum or not root or hum.Health <= 0 then
            if tag then tag.Enabled = false end
            phase = "idle"
            return
        end
        if not tag or not tag.Parent or tagRoot ~= root then makeTag(root) end

        local now = tick()
        local gl = gameLeft()
        local rag = isRagdolled(hum) or gl > 0.05
        if rag then lastActiveT = now end
        local ragNow = rag or (now - lastActiveT) < 0.15   -- сглаживаем мигание состояния

        if phase == "idle" then
            if rag then
                phase, startT, usedAttr = "count", now, false
            end
        end

        if phase == "count" then
            if gl > 0.05 then usedAttr = true end
            local left, finished
            if usedAttr then
                left = gl                       -- точное время из игры
                finished = gl <= 0.05
            else
                left = DUR - (now - startT)     -- запасной вариант: фиксированное время
                finished = left <= 0 or not ragNow
            end
            if finished then
                phase, readyUntil = "ready", now + READY_TIME
            else
                label.Text = string.format("%.1f", math.max(left, 0))
                tag.Enabled = true
            end
        end

        if phase == "ready" then
            if now < readyUntil then
                label.Text = "READY!"
                tag.Enabled = true
            else
                tag.Enabled = false
                phase = "cool"
            end
        end

        if phase == "cool" then
            tag.Enabled = false
            if not ragNow then phase = "idle" end   -- ждём, пока рэгдолл закончится, чтобы не запускать заново
        end
    end)

    player.CharacterAdded:Connect(function()
        phase = "idle"
        removeTag()
    end)

    -- ---------- Панель ----------
    local panelRT = Instance.new("Frame")
    panelRT.Name = "RagdollTimerPanel"
    panelRT.Size = UDim2.new(1, 0, 0, 124)
    panelRT.BackgroundColor3 = COLOR_PANEL
    panelRT.BorderSizePixel = 0
    panelRT.LayoutOrder = 6
    panelRT.Parent = currentPage
    Instance.new("UICorner", panelRT).CornerRadius = UDim.new(0, 10)
    local psRT = Instance.new("UIStroke", panelRT)
    psRT.Color = COLOR_ACCENT
    psRT.Thickness = 1.5

    local titleRT = Instance.new("TextLabel")
    titleRT.BackgroundTransparency = 1
    titleRT.Position = UDim2.new(0, 8, 0, 4)
    titleRT.Size = UDim2.new(0, 140, 0, 16)
    titleRT.Text = "RAGDOLL TIMER"
    titleRT.Font = Enum.Font.GothamBold
    titleRT.TextSize = 11
    titleRT.TextColor3 = COLOR_BLUE
    titleRT.TextXAlignment = Enum.TextXAlignment.Left
    titleRT.Parent = panelRT

    makeLabel(panelRT, UDim2.new(0, 8, 0, 26), "Ragdoll Timer", UDim2.new(0, 110, 0, 18))
    local _, rtVisual = makeToggle(panelRT, UDim2.new(1, -44, 0, 26), false, function(v)
        timerOn = v
        if not v then
            phase = "idle"
            if tag then tag.Enabled = false end
        end
    end)

    -- время отсчёта (сек)
    makeLabel(panelRT, UDim2.new(0, 8, 0, 60), "Time (s)", UDim2.new(0, 80, 0, 18))
    local durBox = Instance.new("TextBox")
    durBox.Name = "RagTimerDur"
    durBox.Size = UDim2.new(0, 44, 0, 22)
    durBox.Position = UDim2.new(1, -54, 0, 58)
    durBox.BackgroundColor3 = COLOR_BG
    durBox.Text = tostring(DUR)
    durBox.Font = Enum.Font.GothamBold
    durBox.TextSize = 12
    durBox.TextColor3 = COLOR_TEXT
    durBox.TextXAlignment = Enum.TextXAlignment.Center
    durBox.ClearTextOnFocus = false
    durBox.Parent = panelRT
    Instance.new("UICorner", durBox).CornerRadius = UDim.new(0, 6)
    local dbs = Instance.new("UIStroke", durBox)
    dbs.Color = COLOR_ACCENT
    dbs.Thickness = 1.5
    local function applyDur()
        local v = tonumber(durBox.Text)
        if v and v >= 0.5 and v <= 10 then DUR = math.floor(v * 10 + 0.5) / 10 end
        durBox.Text = tostring(DUR)
    end
    durBox.FocusLost:Connect(applyDur)
    Flags.apply.RagTimerDur = applyDur

    -- положение: над головой (мелко) или на теле (крупно, как на видео)
    makeLabel(panelRT, UDim2.new(0, 8, 0, 92), "Position", UDim2.new(0, 70, 0, 18))
    local posChip = makeChip(panelRT, UDim2.new(1, -78, 0, 90), UDim2.new(0, 70, 0, 22), posMode, true)
    local function setPos(m)
        posMode = (m == "Body") and "Body" or "Head"
        posChip.Text = posMode
        applyLook()
    end
    posChip.MouseButton1Click:Connect(function()
        setPos(posMode == "Head" and "Body" or "Head")
    end)
    Flags.ragTimerPos = {get = function() return posMode end, set = function(m) setPos(m) end}

    Actions.RagdollTimer = {
        get = function() return timerOn end,
        set = function(v) rtVisual(v == true) timerOn = v == true end,
    }
end
currentPage = pages["MAIN"]

-- ================= COMBAT: AUTO STEAL (Full Auto) — портировано из Adapt (режим NORMAL) =================
-- Сам ворует брейнрота с чужой базы, как только ты оказываешься в радиусе.
-- Радиус, Pause % и тумблер сохраняются через Safe Mode.
currentPage = pages["COMBAT"]
do
    local RunService = game:GetService("RunService")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local LP = player

    local STEAL_RADIUS = 60                                 -- студы (меняется в меню)
    local PAUSE_OPTIONS = {70, 80, 85, 90, 95, 100}         -- как в Adapt
    local pausePercent = 70
    local enabled = false

    local conn = nil
    local busy = false
    local token = 0
    local nextScan = 0
    local promptCache = setmetatable({}, {__mode = "k"})
    local getconns = getconnections or get_signal_cons

    -- ---------- панель ----------
    local pa = Instance.new("Frame")
    pa.Name = "AutoStealPanel"
    pa.Size = UDim2.new(1, 0, 0, 122)
    pa.BackgroundColor3 = COLOR_PANEL
    pa.BorderSizePixel = 0
    pa.LayoutOrder = 0
    pa.Parent = currentPage
    local pac = Instance.new("UICorner", pa)
    pac.CornerRadius = UDim.new(0, 10)
    local pas = Instance.new("UIStroke", pa)
    pas.Color = COLOR_ACCENT
    pas.Thickness = 1.5

    local paTitle = Instance.new("TextLabel")
    paTitle.BackgroundTransparency = 1
    paTitle.Position = UDim2.new(0, 8, 0, 4)
    paTitle.Size = UDim2.new(0, 120, 0, 16)
    paTitle.Text = "AUTO STEAL"
    paTitle.Font = Enum.Font.GothamBold
    paTitle.TextSize = 11
    paTitle.TextColor3 = COLOR_BLUE
    paTitle.TextXAlignment = Enum.TextXAlignment.Left
    paTitle.Parent = pa

    -- ---------- полоска прогресса (перетаскивается) ----------
    local barGui = Instance.new("ScreenGui")
    barGui.Name = "SpeexStealBar"
    barGui.ResetOnSpawn = false
    barGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    barGui.Enabled = false
    barGui.Parent = ScreenGui.Parent

    local barFrame = Instance.new("Frame")
    barFrame.Size = UDim2.new(0, 190, 0, 22)
    barFrame.Position = UDim2.new(0.5, -95, 0, 70)
    barFrame.BackgroundColor3 = COLOR_PANEL
    barFrame.BorderSizePixel = 0
    barFrame.Parent = barGui
    Instance.new("UICorner", barFrame).CornerRadius = UDim.new(0, 8)
    local barStroke = Instance.new("UIStroke", barFrame)
    barStroke.Color = COLOR_ACCENT
    barStroke.Thickness = 1.5

    local barFill = Instance.new("Frame")
    barFill.Size = UDim2.new(0, 0, 1, 0)
    barFill.BackgroundColor3 = COLOR_BLUE
    barFill.BorderSizePixel = 0
    barFill.Parent = barFrame
    Instance.new("UICorner", barFill).CornerRadius = UDim.new(0, 8)

    local barText = Instance.new("TextLabel")
    barText.BackgroundTransparency = 1
    barText.Size = UDim2.new(1, 0, 1, 0)
    barText.Text = "0%"
    barText.Font = Enum.Font.GothamBold
    barText.TextSize = 11
    barText.TextColor3 = COLOR_TEXT
    barText.Parent = barFrame

    do
        local drag, dStart, dPos, dInput
        barFrame.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                drag, dStart, dPos, dInput = true, input.Position, barFrame.Position, input
            end
        end)
        UserInputService.InputChanged:Connect(function(input)
            if drag and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                local d = input.Position - dStart
                barFrame.Position = UDim2.new(dPos.X.Scale, dPos.X.Offset + d.X, dPos.Y.Scale, dPos.Y.Offset + d.Y)
            end
        end)
        UserInputService.InputEnded:Connect(function(input)
            if input == dInput then drag = false end
        end)
    end

    local function setBar(frac)
        frac = math.clamp(frac, 0, 1)
        barFill.Size = UDim2.new(frac, 0, 1, 0)
        barText.Text = math.floor(frac * 100) .. "%"
    end
    local function resetBar()
        setBar(0)
        barStroke.Color = COLOR_ACCENT
    end

    -- ---------- поиск цели ----------
    local function getRoot()
        local char = LP.Character
        return char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
    end

    local function isOwnPlot(plot)
        local sign = plot:FindFirstChild("PlotSign")
        local yb = sign and sign:FindFirstChild("YourBase")
        return yb ~= nil and yb:IsA("BillboardGui") and yb.Enabled == true
    end

    -- ближайший чужой подиум со Steal-промптом в радиусе
    local function findTarget()
        local root = getRoot()
        local plots = workspace:FindFirstChild("Plots")
        if not root or not plots then return nil end
        local best, bestPrompt, bestDist = nil, nil, math.huge
        for _, plot in ipairs(plots:GetChildren()) do
            if not isOwnPlot(plot) then
                local podiums = plot:FindFirstChild("AnimalPodiums")
                if podiums then
                    for _, slot in ipairs(podiums:GetChildren()) do
                        local base = slot:FindFirstChild("Base")
                        local spawnPart = base and base:FindFirstChild("Spawn")
                        if spawnPart then
                            local dist = (spawnPart.Position - root.Position).Magnitude
                            if dist < bestDist and dist <= STEAL_RADIUS then
                                local att = spawnPart:FindFirstChild("PromptAttachment")
                                if att then
                                    for _, p in ipairs(att:GetChildren()) do
                                        if p:IsA("ProximityPrompt") and tostring(p.ActionText):find("Steal") then
                                            best, bestPrompt, bestDist = slot, p, dist
                                            break
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        return best, bestPrompt, bestDist
    end

    -- горизонтальная дистанция от игрока до промпта
    local function distToPrompt(prompt)
        local root = getRoot()
        if not root then return nil end
        local node = prompt.Parent
        local pos
        while node and node ~= workspace do
            if node:IsA("Attachment") then pos = node.WorldPosition break
            elseif node:IsA("BasePart") then pos = node.Position break end
            node = node.Parent
        end
        if not pos then return nil end
        local d = root.Position - pos
        return Vector3.new(d.X, 0, d.Z).Magnitude
    end

    -- коллбэки промпта (нужен getconnections у экзекьютора)
    local function getCallbacks(prompt)
        local c = promptCache[prompt]
        if c then return c end
        c = {hold = {}, trigger = {}}
        if getconns then
            local ok, r = pcall(getconns, prompt.PromptButtonHoldBegan)
            if ok and type(r) == "table" then
                for _, x in ipairs(r) do
                    if type(x.Function) == "function" then table.insert(c.hold, x.Function) end
                end
            end
            local ok2, r2 = pcall(getconns, prompt.Triggered)
            if ok2 and type(r2) == "table" then
                for _, x in ipairs(r2) do
                    if type(x.Function) == "function" then table.insert(c.trigger, x.Function) end
                end
            end
        end
        promptCache[prompt] = c
        return c
    end

    -- ---------- сам стил (логика NORMAL из Adapt) ----------
    local function runSteal(prompt, slot)
        if busy then return end
        busy = true
        token += 1
        local my = token
        local cb = getCallbacks(prompt)
        local pause = pausePercent / 100
        local phase1 = 1.3 * pause

        local function alive() return enabled and busy and my == token end
        local function finish()
            if my == token then
                busy = false
                resetBar()
            end
        end

        local t0 = tick()
        local paused = 0
        local pausedAt = nil
        resetBar()
        barStroke.Color = COLOR_BLUE

        -- прогресс-бар
        local barConn
        barConn = RunService.Heartbeat:Connect(function()
            if not alive() then barConn:Disconnect() return end
            local ref = pausedAt or tick()
            setBar((ref - t0 - paused) / 1.3)
        end)

        task.spawn(function()
            pcall(function() prompt.HoldDuration = 0 end)
            for _, f in ipairs(cb.hold) do task.spawn(f) end

            -- фаза 1: ждём, пока идёт первая часть удержания
            while alive() and tick() - t0 < phase1 do
                local d = distToPrompt(prompt)
                if not d or d > STEAL_RADIUS then break end
                task.wait()
            end
            if not alive() then if barConn then barConn:Disconnect() end finish() return end

            -- фаза 2: бар встаёт на Pause %, ждём подхода к подиуму (<= 6 студов)
            setBar(pause)
            pausedAt = tick()
            local maxWait = math.max(2.99 - phase1 - math.max(1.3 - phase1, 0), 0.05)
            local t1 = tick()
            while alive() do
                if tick() - t1 >= maxWait then break end
                local d = distToPrompt(prompt)
                if not d or d > STEAL_RADIUS then
                    if barConn then barConn:Disconnect() end
                    finish()
                    return
                end
                if d <= 6 then
                    paused += tick() - pausedAt
                    pausedAt = nil
                    break
                end
                task.wait()
            end
            if not alive() then if barConn then barConn:Disconnect() end finish() return end

            -- фаза 3: добиваем остаток и воруем
            local rest = math.max(1.3 - phase1, 0.05)
            local t2 = tick()
            while alive() and tick() - t2 < rest do task.wait() end

            if alive() then
                pcall(function()
                    for _, f in ipairs(cb.trigger) do task.spawn(f) end
                    local ev = ReplicatedStorage:FindFirstChild("StealAnimal")
                    if ev and slot then ev:FireServer(slot.Name) end
                    prompt:Fire()
                end)
            end
            if barConn then barConn:Disconnect() end
            finish()
        end)
    end

    -- ---------- включение / выключение ----------
    local function stopAll()
        token += 1
        busy = false
        if conn then conn:Disconnect() conn = nil end
        resetBar()
    end

    local function setEnabled(on)
        enabled = on == true
        barGui.Enabled = enabled
        stopAll()
        if not enabled then return end
        -- мгновенное удержание на всех промптах плотов
        pcall(function()
            local plots = workspace:FindFirstChild("Plots")
            if plots then
                for _, d in ipairs(plots:GetDescendants()) do
                    if d:IsA("ProximityPrompt") then pcall(function() d.HoldDuration = 0 end) end
                end
            end
        end)
        conn = RunService.Heartbeat:Connect(function()
            if not enabled or busy then return end
            if tick() < nextScan then return end
            nextScan = tick() + 0.08
            local slot, prompt = findTarget()
            if slot and prompt then runSteal(prompt, slot) end
        end)
    end

    -- ---------- UI ----------
    makeLabel(pa, UDim2.new(0, 8, 0, 26), "Auto Steal", UDim2.new(0, 100, 0, 18))
    local _, setStealVisual = makeToggle(pa, UDim2.new(1, -44, 0, 26), false, function(v)
        setEnabled(v)
    end)
    Actions.AutoSteal = {
        get = function() return enabled end,
        set = function(v)
            setEnabled(v)
            setStealVisual(v)
        end,
    }

    -- радиус (поле ввода, сохраняется как "StealRadius")
    makeLabel(pa, UDim2.new(0, 8, 0, 58), "Radius", UDim2.new(0, 90, 0, 18))
    local rBox = Instance.new("TextBox")
    rBox.Name = "StealRadius"
    rBox.Size = UDim2.new(0, 40, 0, 22)
    rBox.Position = UDim2.new(1, -48, 0, 56)
    rBox.BackgroundColor3 = COLOR_BG
    rBox.Text = tostring(STEAL_RADIUS)
    rBox.Font = Enum.Font.GothamBold
    rBox.TextSize = 12
    rBox.TextColor3 = COLOR_TEXT
    rBox.TextXAlignment = Enum.TextXAlignment.Center
    rBox.ClearTextOnFocus = false
    rBox.Parent = pa
    Instance.new("UICorner", rBox).CornerRadius = UDim.new(0, 6)
    local rs = Instance.new("UIStroke", rBox)
    rs.Color = COLOR_ACCENT
    rs.Thickness = 1.5
    rBox:GetPropertyChangedSignal("Text"):Connect(function()
        local t = rBox.Text:gsub("[^%d]", "")
        if rBox.Text ~= t then rBox.Text = t end
    end)
    local function applyRadius()
        local n = tonumber(rBox.Text)
        if n then STEAL_RADIUS = math.clamp(n, 1, 250) end
        rBox.Text = tostring(STEAL_RADIUS)
    end
    rBox.FocusLost:Connect(applyRadius)
    Flags.apply["StealRadius"] = applyRadius

    -- Pause % (кнопка листает 70 / 80 / 85 / 90 / 95 / 100)
    makeLabel(pa, UDim2.new(0, 8, 0, 90), "Pause %", UDim2.new(0, 90, 0, 18))
    local pauseChip = makeChip(pa, UDim2.new(1, -62, 0, 90), UDim2.new(0, 54, 0, 22), tostring(pausePercent) .. "%", true)
    local function setPause(v)
        local best, bd = PAUSE_OPTIONS[1], math.huge
        for _, o in ipairs(PAUSE_OPTIONS) do
            local d = math.abs((tonumber(v) or 70) - o)
            if d < bd then best, bd = o, d end
        end
        pausePercent = best
        pauseChip.Text = tostring(best) .. "%"
    end
    pauseChip.MouseButton1Click:Connect(function()
        local idx = 1
        for i, o in ipairs(PAUSE_OPTIONS) do if o == pausePercent then idx = i end end
        setPause(PAUSE_OPTIONS[idx % #PAUSE_OPTIONS + 1])
    end)
    Flags.stealPause = {get = function() return pausePercent end, set = setPause}

    LP.CharacterAdded:Connect(function()
        busy = false
        token += 1
        resetBar()
    end)
end
currentPage = pages["MAIN"]

-- ================= VISUALS: SAFE MODE — сохранение настроек меню (SAVE / RESET) =================
currentPage = pages["VISUALS"]
do
    local HttpService = game:GetService("HttpService")
    local FILE = "SpeexHub_" .. tostring(player.UserId) .. ".json"

    -- текстовые поля, которые сохраняем (имя TextBox -> применение после загрузки)
    local BOX_NAMES = {"NormalSpeed", "CarrySpeed", "LargerNormalSpeed", "LargerCarrySpeed",
                       "LockRange", "StealRadius", "BypassSpeed", "AimbotSpeed", "BypassV3Speed", "BatAimbotSpeed", "AutoBatDist", "RagTimerDur", "UIScaleBox", "ButtonScaleBox", "StretchValue"}
    -- тумблеры, которые НЕ сохраняем (одноразовые действия и авто-маршруты)
    local SKIP = {["DropPanel:26"] = true, ["ModesPanel:122"] = true, ["InstaResetPanel:26"] = true, ["BatBypassPanel:26"] = true, ["BatAimbotPanel:26"] = true}

    local function fsOk()
        return type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
    end

    local function collect()
        local data = {toggles = {}, boxes = {}, buttons = {}}
        for key, reg in pairs(Registry) do
            if not SKIP[key] and not key:match("^AutoPanel") then
                data.toggles[key] = reg.get() and true or false
            end
        end
        for _, name in ipairs(BOX_NAMES) do
            local box = Main:FindFirstChild(name, true)
            if box then data.boxes[name] = box.Text end
        end
        local p = Main.Position
        data.hub = {xs = p.X.Scale, xo = p.X.Offset, ys = p.Y.Scale, yo = p.Y.Offset}
        if Flags.getButtons then data.buttons = Flags.getButtons() end
        if Flags.getHiddenButtons then data.hiddenButtons = Flags.getHiddenButtons() end
        if Flags.arMode then data.arMode = Flags.arMode.get() end
        if Flags.tpCamLock then data.tpCamLock = Flags.tpCamLock.get() end
        if Flags.dropModeCtl then data.dropMode = Flags.dropModeCtl.get() end
        if Flags.autoBatMode then data.autoBatMode = Flags.autoBatMode.get() end
        if Flags.bypassMode then data.bypassMode = Flags.bypassMode.get() end
        if Flags.ragTimerPos then data.ragTimerPos = Flags.ragTimerPos.get() end
        if Flags.animPack then data.animPack = Flags.animPack.get() end
        if Flags.stealVersion then data.stealVersion = Flags.stealVersion.get() end
        if Flags.stealPause then data.stealPause = Flags.stealPause.get() end
        if Flags.afterDropMode then data.afterDropMode = Flags.afterDropMode.get() end
        return data
    end

    local function apply(data)
        if type(data) ~= "table" then return end
        if data.hiddenButtons and Flags.setHiddenButtons then pcall(Flags.setHiddenButtons, data.hiddenButtons) end
        -- поля ввода и масштабы
        for name, text in pairs(data.boxes or {}) do
            local box = Main:FindFirstChild(name, true)
            if box and type(text) == "string" then
                box.Text = text
                if Flags.apply[name] then pcall(Flags.apply[name]) end
            end
        end
        -- тумблеры
        for key, v in pairs(data.toggles or {}) do
            local reg = Registry[key]
            if reg and not SKIP[key] and reg.get() ~= v then pcall(reg.set, v) end
        end
        if data.arMode and Flags.arMode then pcall(Flags.arMode.set, data.arMode) end
        if data.tpCamLock ~= nil and Flags.tpCamLock then pcall(Flags.tpCamLock.set, data.tpCamLock) end
        if data.dropMode and Flags.dropModeCtl then pcall(Flags.dropModeCtl.set, data.dropMode) end
        if data.autoBatMode and Flags.autoBatMode then pcall(Flags.autoBatMode.set, data.autoBatMode) end
        if data.bypassMode and Flags.bypassMode then pcall(Flags.bypassMode.set, data.bypassMode) end
        if data.ragTimerPos and Flags.ragTimerPos then pcall(Flags.ragTimerPos.set, data.ragTimerPos) end
        if data.animPack and Flags.animPack then pcall(Flags.animPack.set, data.animPack) end
        if data.stealVersion and Flags.stealVersion then pcall(Flags.stealVersion.set, data.stealVersion) end
        if data.stealPause and Flags.stealPause then pcall(Flags.stealPause.set, data.stealPause) end
        if data.afterDropMode and Flags.afterDropMode then pcall(Flags.afterDropMode.set, data.afterDropMode) end
        -- позиция хаба и мобильных кнопок
        local h = data.hub
        if type(h) == "table" and tonumber(h.xo) and tonumber(h.yo) then
            Main.Position = UDim2.new(tonumber(h.xs) or 0, h.xo, tonumber(h.ys) or 0, h.yo)
        end
        if data.buttons and Flags.setButtons then pcall(Flags.setButtons, data.buttons) end
    end

    local function save()
        if not fsOk() then return false, "no file api" end
        local ok, err = pcall(function() writefile(FILE, HttpService:JSONEncode(collect())) end)
        return ok, err
    end

    local function load()
        if not fsOk() or not isfile(FILE) then return false end
        local ok, data = pcall(function() return HttpService:JSONDecode(readfile(FILE)) end)
        if not ok then return false end
        apply(data)
        return true
    end

    local function reset()
        if fsOk() and isfile(FILE) and type(delfile) == "function" then pcall(delfile, FILE) end
    end

    -- ---------- Панель ----------
    local ps = Instance.new("Frame")
    ps.Name = "SafePanel"
    ps.Size = UDim2.new(1, 0, 0, 116)
    ps.BackgroundColor3 = COLOR_PANEL
    ps.BorderSizePixel = 0
    ps.LayoutOrder = 4
    ps.Parent = currentPage
    local psc = Instance.new("UICorner", ps)
    psc.CornerRadius = UDim.new(0, 10)
    local pss = Instance.new("UIStroke", ps)
    pss.Color = COLOR_ACCENT
    pss.Thickness = 1.5

    local title = Instance.new("TextLabel")
    title.BackgroundTransparency = 1
    title.Position = UDim2.new(0, 8, 0, 2)
    title.Size = UDim2.new(0, 100, 0, 16)
    title.Text = "SAFE MODE"
    title.Font = Enum.Font.GothamBold
    title.TextSize = 11
    title.TextColor3 = COLOR_BLUE
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = ps

    local status = Instance.new("TextLabel")
    status.BackgroundTransparency = 1
    status.Position = UDim2.new(0, 8, 0, 94)
    status.Size = UDim2.new(1, -16, 0, 14)
    status.Text = fsOk() and "Save keeps menu after rejoin" or "Executor has no file access"
    status.Font = Enum.Font.Gotham
    status.TextSize = 9
    status.TextColor3 = COLOR_TEXT_D
    status.TextXAlignment = Enum.TextXAlignment.Left
    status.Parent = ps

    local function mkBtn(x, w, text)
        local b = makeChip(ps, UDim2.new(0, x, 0, 28), UDim2.new(0, w, 0, 30), text, true)
        b.TextSize = 11
        return b
    end
    local saveBtn = mkBtn(8, 62, "SAVE")
    local resetBtn = mkBtn(76, 62, "RESET")

    saveBtn.MouseButton1Click:Connect(function()
        local ok = save()
        status.Text = ok and "Saved ✓" or "Save failed"
        status.TextColor3 = ok and COLOR_BLUE or Color3.fromRGB(200, 60, 60)
    end)
    resetBtn.MouseButton1Click:Connect(function()
        reset()
        status.Text = "Save deleted"
        status.TextColor3 = COLOR_TEXT_D
    end)

    -- ---------- Auto Save: любое изменение меню (скорость, тумблеры, позиция...) сохраняется само ----------
    local autoSaveOn = true
    local autoLoaded = false      -- автосохранение стартует только после автозагрузки, чтобы не затереть файл
    local lastSavedJson = nil
    local pendingJson, pendingCount = nil, 0

    makeLabel(ps, UDim2.new(0, 8, 0, 66), "Auto Save", UDim2.new(0, 100, 0, 18))
    local _, setAutoSaveVisual = makeToggle(ps, UDim2.new(1, -44, 0, 66), true, function(v)
        autoSaveOn = v
        if v then lastSavedJson = nil end
    end)

    local function encodeNow()
        local ok, json = pcall(function() return HttpService:JSONEncode(collect()) end)
        return ok and json or nil
    end

    local myRun = (getgenv and getgenv().__SpeexHubRun) or 0
    task.spawn(function()
        while true do
            task.wait(1)
            if ((getgenv and getgenv().__SpeexHubRun) or 0) ~= myRun then break end   -- запущена новая копия: старая не пишет в файл
            if autoSaveOn and autoLoaded and fsOk() then
                local json = encodeNow()
                if json and json ~= lastSavedJson then
                    -- ждём, чтобы значение не менялось 1 сек подряд (например, пока вводишь число или тащишь меню)
                    if json == pendingJson then pendingCount = pendingCount + 1 else pendingJson, pendingCount = json, 0 end
                    if pendingCount >= 1 then
                        local ok = pcall(function() writefile(FILE, json) end)
                        if ok then
                            lastSavedJson = json
                            status.Text = "Auto saved ✓"
                            status.TextColor3 = COLOR_BLUE
                        end
                        pendingJson, pendingCount = nil, 0
                    end
                end
            end
        end
    end)

    -- автозагрузка при запуске, когда всё меню уже построено
    Flags.loadSaved = function()
        if load() then
            status.Text = "Loaded saved menu"
            status.TextColor3 = COLOR_BLUE
        end
        task.wait(0.3)               -- даём применённым настройкам устояться
        lastSavedJson = encodeNow()
        autoLoaded = true
    end
end
currentPage = pages["MAIN"]

-- ================= ОБЪЁМНОЕ НАЗВАНИЕ ВНИЗУ (надутый стиль как у REAL) =================
local BottomPanel = Instance.new("Frame")
BottomPanel.Name = "BottomPanel"
BottomPanel.Size = UDim2.new(1, 0, 0, BOTTOM_H)
BottomPanel.Position = UDim2.new(0, 0, 1, -BOTTOM_H)
BottomPanel.BackgroundColor3 = COLOR_BLUE_D
BottomPanel.BorderSizePixel = 0
BottomPanel.ClipsDescendants = true   -- обрезает баннер ровно по контуру панели (в т.ч. углы)
BottomPanel.Parent = Main
local bpc = Instance.new("UICorner", BottomPanel)
bpc.CornerRadius = UDim.new(0, 12)

local BottomFill = Instance.new("Frame") -- прямые верхние углы
BottomFill.Size = UDim2.new(1, 0, 0, 12)
BottomFill.BackgroundColor3 = COLOR_BLUE_D
BottomFill.BorderSizePixel = 0
BottomFill.Parent = BottomPanel

local TitleHolder = Instance.new("Frame")
TitleHolder.BackgroundTransparency = 1
TitleHolder.Position = UDim2.new(0, 0, 0, 0)
TitleHolder.Size = UDim2.new(1, 0, 1, 0)
TitleHolder.ClipsDescendants = true
TitleHolder.Parent = BottomPanel
Instance.new("UICorner", TitleHolder).CornerRadius = UDim.new(0, 12)

