local titleImg = Instance.new("ImageLabel")
titleImg.Name = "SpeexTitle"
titleImg.BackgroundTransparency = 1
titleImg.Size = UDim2.new(1, 0, 1, 0)
titleImg.Position = UDim2.new(0, 0, 0, 0)
titleImg.ScaleType = Enum.ScaleType.Stretch
titleImg.ZIndex = 2
titleImg.Parent = TitleHolder
Instance.new("UICorner", titleImg).CornerRadius = UDim.new(0, 12)
-- без UICorner у картинки: края квадратные, обрезку по скруглённым углам делает сама панель

local okTitle, titleAsset = pcall(function()
    writefile("speex_title.jpg", b64decode(TITLE_B64))
    return (getcustomasset or getsynasset)("speex_title.jpg")
end)
if okTitle and titleAsset then
    titleImg.Image = titleAsset
else
    -- fallback текст если executor без getcustomasset
    local fb = Instance.new("TextLabel")
    fb.BackgroundTransparency = 1
    fb.Size = UDim2.new(1, 0, 1, 0)
    fb.Text = "SPEEX VS"
    fb.Font = Enum.Font.GothamBlack
    fb.TextScaled = true
    fb.TextColor3 = Color3.fromRGB(180, 220, 255)
    fb.Parent = TitleHolder
end

