local function sideText(y, h, text, font, color, size, wrap)
    local l = Instance.new("TextLabel")
    l.BackgroundTransparency = 1
    l.Position = UDim2.new(0, 3, 0, y)
    l.Size = UDim2.new(1, -6, 0, h)
    l.Text = text
    l.Font = font
    l.TextSize = size
    l.TextWrapped = wrap
    l.TextTruncate = Enum.TextTruncate.AtEnd
    l.TextColor3 = color
    l.Parent = SideRight
    return l
end

sideText(48, 16, string.upper(player.DisplayName), Enum.Font.GothamBold, CARD_TEXT, 6, true)
sideText(66, 11, "@" .. player.Name, Enum.Font.Gotham, CARD_TEXT_D, 7, false)
sideText(79, 10, "ID", Enum.Font.GothamBold, CARD_TEXT_D, 7, false)
sideText(89, 11, tostring(player.UserId), Enum.Font.Gotham, CARD_TEXT, 7, false)

