-- ================= МИНИМИЗАЦИЯ =================
local minimized = false
MinimizeBtn.MouseButton1Click:Connect(function()
    minimized = not minimized
    Content.Visible = not minimized
    SideLeft.Visible = not minimized
    SideRight.Visible = not minimized
    HeaderFill.Visible = not minimized
    Background.Visible = not minimized
    Veil.Visible = not minimized
    local r = minimized and UDim.new(0, HEADER_H / 2) or UDim.new(0, 12)
    MainCorner.CornerRadius = r
    hdc.CornerRadius = r
    BottomPanel.Visible = not minimized
    if minimized then
        Main.Size = UDim2.new(0, MINI_W, 0, HEADER_H)
        MinimizeBtn.Text = "+"
    else
        Main.Size = UDim2.new(0, WIDTH, 0, HEIGHT)
        MinimizeBtn.Text = "-"
    end
end)

-- ================= ПЕРЕТАСКИВАНИЕ (за синюю шапку) =================
local dragging, dragStart, startPos

Header.InputBegan:Connect(function(input)
    if Flags.uiLocked then return end
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true
        dragStart = input.Position
        startPos = Main.Position
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
        local delta = input.Position - dragStart
        Main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
    end
end)

UserInputService.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging = false
    end
end)

-- ================= АВТОЗАГРУЗКА СОХРАНЁННЫХ НАСТРОЕК =================
task.defer(function()
    task.wait(0.5)
    if Flags.loadSaved then pcall(Flags.loadSaved) end
end)